// Auto-generated for the Unit Board — LiveABC Level 2–4 Advanced
window.KA_DASHBOARD_UNITS = [{"unit":1,"theme":"be dependent on – gadget","cards":[{"w":"be dependent on","p":"adj.","d":"needing someone or something for support or help.","c":"依賴的","s":"Children are dependent on their parents for support.","t":"孩子們依賴他們的父母來支持。"},{"w":"be independent from","p":"adj.","d":"not controlled by or needing help from someone or something.","c":"獨立的","s":"She became independent from her family after moving out of her parents' house.","t":"搬出父母家後，她變得脫離父母獨立了。"},{"w":"dependence on","p":"n.","d":"the state of needing or relying on someone or something.","c":"依賴","s":"There's a heavy dependence on imported goods.","t":"對進口商品有很大的依賴。"},{"w":"independence","p":"n.","d":"freedom from control by another person, group, or country.","c":"獨立","s":"The country celebrated its independence Day last month.","t":"上個月，該國慶祝了獨立日。"},{"w":"imagine","p":"v.","d":"to form a picture or idea in your mind.","c":"想像","s":"Imagine a world without borders. What woud life become?","t":"想像一個沒有邊界的世界。生活會變得如何?"},{"w":"imaginative","p":"adj.","d":"good at thinking of new and creative ideas.","c":"富有想像力的","s":"She has an imaginative approach to problem-solving.","t":"她在解決問題時有豐富的想像力。"},{"w":"imagination","p":"n.","d":"the ability to create ideas or pictures in your mind.","c":"想像力","s":"Writers often have vivid imaginations.","t":"作家們通常有豐富的想像力。"},{"w":"imaginary","p":"adj.","d":"not real; existing only in the mind or in a story.","c":"虛構的","s":"The characters in the story are imaginary.","t":"故事中的角色是虛構的。"},{"w":"electronics","p":"n.","d":"the study or use of electronic equipment and circuits.","c":"電子學","s":"He studied electronics in college.","t":"他在大學學習電子學。"},{"w":"electronic","p":"adj.","d":"using or related to electronic devices or technology.","c":"電子的","s":"The new electronic device is compact and efficient.","t":"這款新的電子裝置小巧高效。"},{"w":"electric","p":"adj.","d":"using or producing electricity.","c":"電的","s":"The car runs on electric power.","t":"這輛車是電動的。"},{"w":"commercial","p":"adj.","d":"related to business or buying and selling.","c":"商業的","s":"He is involved in commercial real estate.","t":"他從事商業房地產。"},{"w":"TV commercial","p":"n.","d":"a short advertisement shown on television.","c":"電視廣告","s":"They aired a new TV commercial during the Super Bowl.","t":"他們在超級碗期間播放了一條新的電視廣告。"},{"w":"advertisement","p":"n.","d":"a public notice that promotes a product, service, or event.","c":"廣告","s":"The advertisement featured a catchy jingle.","t":"這個廣告有一個引人注目的廣告詞。"},{"w":"technical","p":"adj.","d":"related to practical skills, machines, science, or technology.","c":"技術的","s":"He has a technical background in computer science.","t":"他在計算機科學方面有技術背景。"},{"w":"technician","p":"n.","d":"a person trained to repair or work with technical equipment.","c":"技術人員","s":"The technician repaired the computer quickly.","t":"技術人員迅速修好了電腦。"},{"w":"assist","p":"v.","d":"to help someone do something.","c":"協助","s":"He agreed to assist with the project.","t":"他同意協助這個項目。"},{"w":"assistant","p":"n.","d":"a person whose job is to help another person.","c":"助理","s":"She hired an assistant to help with administrative tasks.","t":"她聘請了一名助理來幫忙行政工作。"},{"w":"device","p":"n.","d":"a tool, machine, or piece of equipment made for a purpose.","c":"裝置","s":"The new device helps monitor heart rate.","t":"這個新裝置幫助監測心率。"},{"w":"devise","p":"v.","d":"to invent or plan a method, system, or solution.","c":"設計發明","s":"They devise a plan to increase sales.","t":"他們設計了一個增加銷售的計劃。"},{"w":"imitate","p":"v.","d":"to copy the way someone or something looks, sounds, or acts.","c":"模仿","s":"She can imitate any accent perfectly.","t":"她可以完美地模仿任何口音。"},{"w":"imitation","p":"n.","d":"a copy of someone or something.","c":"模仿","s":"The artist's painting was a brilliant imitation of nature.","t":"這位藝術家的畫作是對自然的精彩模仿。"},{"w":"imitator","p":"n.","d":"a person who copies another person, often as a skill or performance.","c":"模仿者","s":"He was known as a skilled imitator of famous actors.","t":"他以模仿著名演員而聞名。"},{"w":"further","p":"adj.","d":"additional or more advanced.","c":"進一步的","s":"They need to conduct further research on the topic.","t":"他們需要對這個主題進行進一步的研究。"},{"w":"research","p":"v.","d":"to study a subject carefully to discover new information.","c":"研究","s":"They plan to research the effects of climate change.","t":"他們計劃研究氣候變化的影響。"},{"w":"research","p":"n.","d":"careful study done to discover new information.","c":"研究","s":"Her research focuses on environmental sustainability.","t":"她的研究集中在環境可持續性上。"},{"w":"researcher","p":"n.","d":"a person who studies a subject carefully to discover new information.","c":"研究人員","s":"The researcher published a groundbreaking paper.","t":"這位研究人員發表了一篇開創性的論文。"},{"w":"combine","p":"v.","d":"to join two or more things together.","c":"結合","s":"They decided to combine their efforts for the project.","t":"他們決定結合他們的力量來完成這個項目。"},{"w":"combination","p":"n.","d":"two or more things joined or used together.","c":"結合","s":"The combination of flavors created a unique dish.","t":"各種風味的結合創造了一道獨特的菜肴。"},{"w":"practical","p":"adj.","d":"useful, sensible, and easy to do in real situations.","c":"實際的","s":"His advice is always practical and easy to implement.","t":"他的建議總是實用且易於實施的。"},{"w":"impractical","p":"adj.","d":"not sensible or not easy to do in real situations.","c":"不切實際的","s":"Their plan seemed impractical given the time constraints.","t":"他們的計劃在時間限制下顯得不切實際。"},{"w":"fashionable","p":"adj.","d":"popular or stylish at a particular time.","c":"流行的","s":"She always wears the most fashionable clothes.","t":"她總是穿著最時尚的衣服。"},{"w":"fashion","p":"n.","d":"a popular style of clothes, behavior, or design.","c":"時尚","s":"The latest fashion trends were showcased at the event.","t":"最新的時尚趨勢在活動中展示。"},{"w":"educate","p":"v.","d":"to teach or train someone.","c":"教育","s":"The government aims to educate children on environmental issues.","t":"政府旨在教育兒童有關環境問題。"},{"w":"education","p":"n.","d":"the process of teaching, learning, or being trained.","c":"教育","s":"She has a degree in early childhood education.","t":"她有一個兒童早期教育的學位。"},{"w":"educative","p":"adj.","d":"helping people learn something.","c":"教育的","s":"The documentary was both entertaining and educative.","t":"這部紀錄片既有趣又富有教育意義。"},{"w":"educator","p":"n.","d":"a teacher or someone who works in education.","c":"教育工作者","s":"She works as an educator at a local school.","t":"她在一所當地學校擔任教育工作者。"},{"w":"entertain","p":"v.","d":"to amuse people or make them enjoy themselves.","c":"娛樂","s":"The magician's tricks entertain the audience.","t":"魔術師的戲法使觀眾娛樂。"},{"w":"entertaining","p":"adj.","d":"enjoyable and fun to watch, hear, or do.","c":"娛樂的","s":"The movie was entertaining from start to finish.","t":"這部電影從頭到尾都很有趣。"},{"w":"entertainment","p":"n.","d":"activities, shows, or performances that people enjoy.","c":"娛樂","s":"The theme park offers various forms of entertainment.","t":"這個主題公園提供各種形式的娛樂。"},{"w":"entertainer","p":"n.","d":"a person who performs to amuse an audience.","c":"藝人","s":"The entertainer captivated the audience with his performance.","t":"這位藝人以他的表演吸引了觀眾。"},{"w":"growth","p":"n.","d":"the process of becoming bigger, stronger, or more developed.","c":"成長","s":"The company has experienced steady growth.","t":"公司經歷了穩定的成長。"},{"w":"grow","p":"v.","d":"to become bigger, older, or more developed.","c":"成長","s":"Plants grow best in sunlight.","t":"植物在陽光下生長得最好。"},{"w":"promote","p":"v.","d":"to support or encourage something so it grows or improves.","c":"促進","s":"The campaign aims to promote awareness of recycling.","t":"這個活動旨在促進回收意識。"},{"w":"promote","p":"v.","d":"to support or encourage something so it grows or improves.","c":"升遷","s":"He was promoted to a managerial position last year.","t":"他去年被升遷到管理職位。"},{"w":"promotion","p":"n.","d":"an act of moving someone to a higher job or encouraging something.","c":"促進","s":"Her hard work earned her a well-deserved promotion.","t":"她的努力工作為她贏得了應得的升遷。"},{"w":"gadget","p":"n.","d":"a small useful machine or electronic tool.","c":"小器具","s":"He loves to collect the latest gadgets.","t":"他喜歡收集最新的小器具。"}]},{"unit":2,"theme":"handy – wrinkle","cards":[{"w":"handy","p":"adj.","d":"useful and convenient.","c":"方便的","s":"A Swiss Army knife is handy for camping trips.","t":"瑞士軍刀在露營旅行中很方便。"},{"w":"come in handy","p":"phr.","d":"to be useful when needed.","c":"派上用場","s":"His expertise in coding will come in handy during the project.","t":"他的編碼專業知識在項目進行中會派上用場。"},{"w":"microwave","p":"n.","d":"an oven that cooks or heats food very quickly.","c":"微波爐","s":"She heated the soup in the microwave.","t":"她在微波爐中加熱湯。"},{"w":"microwavable","p":"adj.","d":"safe or suitable to be heated in a microwave.","c":"可放入微波爐的","s":"The microwavable container is safe for reheating.","t":"這個可放入微波爐的容器是安全的用來加熱。"},{"w":"extra","p":"adj.","d":"more than usual or more than needed.","c":"額外的","s":"He ordered extra cheese on his pizza.","t":"他在披薩上加了額外的奶酪。"},{"w":"extra","p":"n.","d":"an additional thing or person.","c":"額外的事物","s":"The hotel provides complimentary extras like toiletries.","t":"這家酒店提供免費的額外物品，如洗漱用品。"},{"w":"extraordinary","p":"adj.","d":"very unusual, special, or impressive.","c":"非凡的","s":"Her performance was extraordinary and captivated the audience.","t":"她的表演非凡，吸引了觀眾。"},{"w":"go the extra mile","p":"phr.","d":"to make more effort than expected.","c":"額外努力","s":"He always goes the extra mile to ensure customer satisfaction.","t":"他總是額外努力確保客戶滿意度。"},{"w":"typical","p":"adj.","d":"usual or normal for a person, thing, or situation.","c":"典型的","s":"The typical breakfast includes eggs and toast.","t":"典型的早餐包括雞蛋和吐司。"},{"w":"design","p":"v.","d":"to plan how something will look, work, or be made.","c":"設計","s":"He helped design the new logo for the company.","t":"他幫助設計了公司的新標誌。"},{"w":"design","p":"n.","d":"a plan, drawing, or style for how something looks or works.","c":"設計","s":"The design of the building is modern and sleek.","t":"這座建築的設計現代而流暢。"},{"w":"fashion design","p":"n.","d":"the art or work of creating clothing styles.","c":"服裝設計","s":"She studied fashion design at a prestigious art school.","t":"她在一所著名的藝術學校學習服裝設計。"},{"w":"graphic design","p":"n.","d":"the art or work of creating visual designs.","c":"平面設計","s":"The company hired a graphic design firm to redesign their website.","t":"公司聘請了一家平面設計公司重新設計他們的網站。"},{"w":"motivate","p":"v.","d":"to make someone want to do something.","c":"激勵","s":"His coach's words motivate him to do better.","t":"他的教練的話激勵他做得更好。"},{"w":"motivated","p":"adj.","d":"having a strong reason or desire to do something.","c":"有動力的","s":"She was motivated to start her own business.","t":"她有動力開始自己的生意。"},{"w":"motivation","p":"n.","d":"the reason or desire that makes someone act.","c":"激勵","s":"Money was not his motivation for joining the team.","t":"金錢不是他加入團隊的激勵。"},{"w":"motivational","p":"adj.","d":"making people feel encouraged to act or improve.","c":"激勵的","s":"The motivational speaker inspired the audience.","t":"這位激勵性演講者激勵了觀眾。"},{"w":"ideal","p":"adj.","d":"perfect or most suitable.","c":"理想的","s":"This is the ideal place for a family vacation.","t":"這是一個理想的家庭度假地點。"},{"w":"task","p":"v.","d":"to give someone a job or responsibility.","c":"任務","s":"They need to task the new employees quickly.","t":"他們需要迅速地分配新員工的任務。"},{"w":"task","p":"n.","d":"a piece of work that must be done.","c":"任務","s":"Her daily tasks include answering emails and calls.","t":"她的日常任務包括回答郵件和電話。"},{"w":"drag","p":"v.","d":"to pull something along a surface.","c":"拖","s":"Don't drag your feet; we need to leave now.","t":"別拖延了，我們現在要走了。"},{"w":"drag","p":"n.","d":"something boring or unpleasant to do.","c":"無聊的活動","s":"Cleaning the garage was a tedious drag.","t":"清理車庫是一個繁瑣的工作。"},{"w":"drag one's feet","p":"phr.","d":"to delay doing something because you do not want to do it.","c":"拖延","s":"He's dragging his feet about making a decision.","t":"他在做出決定上拖延不決。"},{"w":"sticky","p":"adj.","d":"able to stick to things; covered with something that sticks.","c":"黏的","s":"The tape was sticky and difficult to remove.","t":"膠帶很黏，難以撕下來。"},{"w":"stick","p":"n.","d":"a thin piece of wood or a similar object.","c":"棍子","s":"He used a long stick to reach the top shelf.","t":"他用一根長棍子夠到了頂層。"},{"w":"stick","p":"v.","d":"to attach to something or stay attached.","c":"黏住","s":"The paper sticks to the wall.","t":"紙張黏在牆上。"},{"w":"stick to","p":"phr.","d":"to continue doing or believing something.","c":"堅持","s":"She always sticks to her principles.","t":"她總是堅持自己的原則。"},{"w":"dust","p":"n.","d":"fine dry powder made of tiny particles of dirt.","c":"灰塵","s":"He wiped the dust off the shelves.","t":"他擦掉了書架上的灰塵。"},{"w":"dusty","p":"adj.","d":"covered with dust.","c":"塵土飛揚的","s":"The attic was dusty and filled with cobwebs.","t":"閣樓灰塵飛揚，佈滿了蜘蛛網。"},{"w":"keyboard","p":"n.","d":"a set of keys used to type on a computer or play music.","c":"鍵盤","s":"He typed quickly on the keyboard.","t":"他在鍵盤上快速打字。"},{"w":"polish","p":"v.","d":"to rub something until it shines.","c":"擦亮","s":"She polishes her shoes before the interview.","t":"她在面試前擦亮了鞋子。"},{"w":"polish","p":"v.","d":"to rub something until it shines.","c":"改善","s":"He wants to polish his English skills.","t":"他想要改善他的英語能力。"},{"w":"polish one's skills","p":"phr.","d":"to improve skills through practice.","c":"改進技能","s":"She practiced daily to polish her piano skills.","t":"她每天練習以提高鋼琴技巧。"},{"w":"polish nail","p":"n.","d":"colored liquid put on fingernails or toenails.","c":"指甲油","s":"She applied nail polish in a bold red color.","t":"她塗上了一層大膽的紅色指甲油。"},{"w":"nail polish remover","p":"n.","d":"a liquid used to remove nail polish.","c":"指甲油卸妝水","s":"She used nail polish remover to take off the old nail polish.","t":"她用指甲油卸妝水卸掉舊的指甲油。"},{"w":"tell something apart","p":"phr.","d":"to recognize the difference between two similar things.","c":"分辨","s":"Can you tell the twins apart?","t":"你能分辨出這對雙胞胎嗎？"},{"w":"keep something apart","p":"phr.","d":"to keep things separated from each other.","c":"使...分開","s":"It's important to keep the chemicals apart from food.","t":"重要的是將化學物質與食物分開。"},{"w":"set something apart from something else","p":"phr.","d":"to make something clearly different from others.","c":"將某物與另一物分開","s":"Her unique style sets her apart from others.","t":"她獨特的風格使她的藝術品與其他人區分開來。"},{"w":"distribute","p":"v.","d":"to give things to several people or places.","c":"分發","s":"Volunteers will distribute food and blankets to the homeless.","t":"志願者將向無家可歸者分發食物和毛毯。"},{"w":"distribution","p":"n.","d":"the act of giving or delivering things to many people or places.","c":"分發","s":"The distribution of resources was handled efficiently.","t":"資源的分配處理得非常有效。"},{"w":"combine A with B","p":"phr.","d":"to join one thing with another thing.","c":"將A與B結合","s":"She likes to combine different flavors with in her cooking.","t":"她喜歡在烹飪中將不同的風味結合在一起。"},{"w":"combination","p":"n.","d":"two or more things joined or used together.","c":"結合","s":"The combination of colors in the painting was striking.","t":"繪畫中顏色的結合非常鮮明。"},{"w":"handle","p":"n.","d":"the part of an object that you hold.","c":"把手","s":"The suitcase had a sturdy handle for easy carrying.","t":"這個手提箱有一個堅固的把手，方便攜帶。"},{"w":"handle","p":"v.","d":"to deal with or manage a person, problem, or situation.","c":"處理","s":"She knew how to handle difficult customers effectively.","t":"她知道如何有效地處理困難的客戶。"},{"w":"cope with","p":"phr.","d":"to deal successfully with a difficult situation.","c":"應對","s":"He needed to cope with the stress of his new job.","t":"他需要應對新工作帶來的壓力。"},{"w":"baggage / luggage","p":"n.","d":"bags and suitcases used when traveling.","c":"行李","s":"Passengers waited at baggage claim to retrieve their bags.","t":"乘客在行李提領區等待取回他們的行李。"},{"w":"baggage claim","p":"n.","d":"the place at an airport where passengers collect their bags.","c":"行李提領區","s":"She couldn't find her luggage at baggage claim.","t":"她找不到她的行李在行李提領區。"},{"w":"life hack","p":"n.","d":"a simple trick that makes everyday life easier.","c":"生活技巧","s":"She shared a life hack for cleaning with vinegar and baking soda.","t":"她分享了一個使用醋和小蘇打清潔的生活技巧。"},{"w":"wrinkle","p":"v.","d":"to make lines or folds in skin, cloth, or paper.","c":"使起皺紋","s":"He wrinkles his forehead in confusion.","t":"他因為困惑而皺起了眉頭。"},{"w":"wrinkle","p":"n.","d":"a small line or fold in skin, cloth, or paper.","c":"皺紋","s":"She noticed a few wrinkles around his eyes.","t":"她注意到他眼睛周圍有幾條皺紋。"}]},{"unit":3,"theme":"invention – all thumbs","cards":[{"w":"invention","p":"n.","d":"a completely new tool or process designed by study.","c":"發明、發明物","s":"The invention of the telephone changed the way people communicated and made the world feel much smaller.","t":"電話的發明改變了人們溝通的方式，讓世界感覺小了許多。"},{"w":"invent","p":"v.","d":"to create a brand new machine, design, or system.","c":"發明、創造","s":"She worked for ten years to invent a device that could turn salt water into clean drinking water.","t":"她花了十年時間發明一種能將鹽水轉化為乾淨飲用水的裝置。"},{"w":"inventor","p":"n.","d":"a person who creates or designs new things.","c":"發明家","s":"The young inventor presented his solar-powered bicycle at the science fair, and the judges were very impressed.","t":"這位年輕的發明家在科學展上展示了他的太陽能腳踏車，評審們印象深刻。"},{"w":"brilliant","p":"adj.","d":"extremely clever, intelligent, or talented.","c":"聰穎的、傑出的","s":"My chemistry teacher is so brilliant that she can explain the most difficult concepts in a way everyone understands.","t":"我的化學老師非常聰穎，她能以每個人都能理解的方式解釋最困難的概念。"},{"w":"brilliant","p":"adj.","d":"very bright and radiant in color or light.","c":"明亮的、璀璨的","s":"The fireworks burst into brilliant colours against the dark night sky, and the crowd cheered with excitement.","t":"煙火在漆黑的夜空中綻放出璀璨的色彩，人群興奮地歡呼。"},{"w":"brilliantly","p":"adv.","d":"in an extremely intelligent, successful, or bright way.","c":"輝煌地、卓越地","s":"The pianist performed brilliantly at the concert last night, and the audience gave her a standing ovation.","t":"這位鋼琴家昨晚在音樂會上表現得卓越出色，觀眾起立鼓掌喝采。"},{"w":"brilliance","p":"n.","d":"exceptional talent, wisdom, or intense brightness.","c":"才華橫溢、耀眼","s":"Everyone admired the brilliance of the young scientist, who solved a problem that had puzzled experts for decades.","t":"每個人都欽佩這位年輕科學家的才華，他解決了困擾專家數十年的問題。"},{"w":"complete","p":"adj.","d":"having all the necessary parts; whole and total.","c":"完全的、完整的","s":"The puzzle is not complete because three pieces are missing, so we cannot see the full picture.","t":"這拼圖並不完整，因為少了三塊，所以我們看不到完整的圖案。"},{"w":"complete","p":"adj.","d":"finished; brought to an end or conclusion.","c":"完工的、結束的","s":"The construction of the new library is finally complete, and students can start using it next Monday.","t":"新圖書館的建設終於完工了，學生們下週一就可以開始使用。"},{"w":"complete","p":"v.","d":"to finish making, doing, or filling out something.","c":"完成、結束","s":"Please complete the application form carefully and submit it before the deadline this Friday.","t":"請仔細填妥申請表，並在本週五截止日期前提交。"},{"w":"completely","p":"adv.","d":"totally or perfectly; in every single way.","c":"完全地、徹底地","s":"After the heavy rain, the road was completely blocked by fallen trees, so we had to take a different route.","t":"大雨過後，道路被倒塌的樹木完全封堵，我們不得不改道而行。"},{"w":"completion","p":"n.","d":"the state or process of finishing a task or project.","c":"完成、完工","s":"Upon completion of the training program, each participant will receive an official certificate from the organization.","t":"培訓課程完成後，每位參加者將獲得該組織頒發的正式證書。"},{"w":"total","p":"adj.","d":"absolute; comprising the whole number or degree.","c":"總共的、完全的","s":"The total cost of the school trip, including transport and meals, came to about three thousand dollars.","t":"這次學校旅遊的總費用，包括交通和餐費，大約是三千元。"},{"w":"total","p":"n.","d":"the full amount calculated after adding parts.","c":"總數、總計","s":"After counting all the votes, the total showed that the environmental club won by a large margin.","t":"統計所有選票後，總數顯示環保社團以大幅優勢獲勝。"},{"w":"whole","p":"adj.","d":"entire; all of something without exception.","c":"全部的、整整的","s":"She spent the whole afternoon in the library preparing for her history exam, and she felt very confident afterwards.","t":"她花了整個下午在圖書館準備歷史考試，之後她感到非常有信心。"},{"w":"all","p":"n.","d":"the complete amount or general number of things.","c":"所有、全部的","s":"All of the students in the class passed the final exam, which made the teacher very proud.","t":"班上所有學生都通過了期末考試，這讓老師感到非常自豪。"},{"w":"accident","p":"n.","d":"a sudden unfortunate vehicle crash causing damage.","c":"車禍","s":"There was a serious accident on the highway this morning, so traffic was delayed for more than two hours.","t":"今天早上高速公路上發生了一起嚴重的車禍，導致交通延誤了兩個多小時。"},{"w":"accident","p":"n.","d":"an unplanned event that happens unexpectedly.","c":"意外、偶然事件","s":"Dropping the phone in the sink was a complete accident, and luckily the screen was not damaged at all.","t":"把手機掉進水槽完全是個意外，幸好螢幕完全沒有損壞。"},{"w":"accidental","p":"adj.","d":"happening entirely by chance; non-intentional.","c":"偶然的、意外的","s":"The discovery of penicillin was largely accidental, but it went on to save millions of lives around the world.","t":"青黴素的發現在很大程度上是偶然的，但它後來拯救了全世界數百萬人的生命。"},{"w":"accidentally","p":"adv.","d":"by chance; without any purpose or meaning.","c":"意外地、不小心地","s":"He accidentally sent the wrong file to his teacher, so he had to email the correct version right away.","t":"他不小心把錯誤的檔案發給了老師，因此不得不立刻再發一封正確版本的電郵。"},{"w":"by accident","p":"phr.","d":"unintentionally; via random good or bad luck.","c":"意外地、偶然地","s":"She found her lost wallet by accident when she was cleaning her room and moved the old boxes.","t":"她在打掃房間移動舊箱子時，偶然發現了遺失的錢包。"},{"w":"incident","p":"n.","d":"an event, especially one that is bad or strange.","c":"事件、插曲","s":"The school reported the bullying incident to the parents immediately and held a meeting to solve the problem.","t":"學校立即向家長報告了這起霸凌事件，並召開會議以解決問題。"},{"w":"material","p":"n.","d":"physical matter from which things can be made.","c":"材料、原料","s":"The engineer chose a lightweight but strong material for the bridge so that it could last for over one hundred years.","t":"工程師為橋樑選擇了一種輕巧但堅固的材料，使其能使用超過一百年。"},{"w":"material","p":"n.","d":"cloth or fabric used for making garments.","c":"布料","s":"The dress is made from a soft, silky material that feels very comfortable to wear on hot summer days.","t":"這件洋裝由柔軟絲滑的布料製成，在炎熱的夏天穿起來非常舒適。"},{"w":"material","p":"adj.","d":"physical, physical-world, rather than spiritual.","c":"物質的、肉體的","s":"She believed that material possessions could never bring true happiness, and she donated most of her wealth to charity.","t":"她相信物質財富永遠無法帶來真正的幸福，並將大部分財富捐給了慈善機構。"},{"w":"materialism","p":"n.","d":"an obsession with keeping physical possessions.","c":"物質主義","s":"Materialism has become a serious problem in modern society, as many people judge success only by the things they own.","t":"物質主義已成為現代社會的嚴重問題，許多人僅以擁有的物品來衡量成功。"},{"w":"raw material","p":"phr.","d":"basic substances used in manufacturing processes.","c":"原料","s":"The factory needs to import raw material from overseas because local supplies are no longer sufficient for production.","t":"這家工廠需要從海外進口原料，因為本地供應已不足以應付生產需求。"},{"w":"explode","p":"v.","d":"to burst out violently with a sudden loud noise.","c":"爆炸","s":"The old gas pipe in the basement began to explode, causing windows to shatter throughout the entire building.","t":"地下室的舊瓦斯管道開始爆炸，導致整棟建築的窗戶都震碎了。"},{"w":"explode","p":"v.","d":"to increase suddenly and rapidly in number or size.","c":"暴增、激增","s":"The population of the city began to explode after the new technology companies moved in and created thousands of jobs.","t":"在新科技公司進駐並創造數千個就業機會後，這座城市的人口開始急速暴增。"},{"w":"explosion","p":"n.","d":"a violent shattering or blowing up of an object.","c":"爆炸、暴發","s":"The loud explosion at the construction site could be heard from several kilometres away, and it startled many residents.","t":"建築工地的巨大爆炸聲在數公里外都能聽到，嚇到了許多居民。"},{"w":"explosive","p":"adj.","d":"able or highly likely to cause an explosion.","c":"爆炸性的、易爆的","s":"Workers must follow strict safety rules when handling explosive chemicals to prevent dangerous accidents in the lab.","t":"處理易爆化學品時，工人必須遵守嚴格的安全規定，以防止實驗室發生危險事故。"},{"w":"control","p":"v.","d":"to order, limit, manage, or rule an entity.","c":"控制、支配、掌管","s":"The government introduced new laws to control the spread of misinformation on social media platforms.","t":"政府制定了新法律，以控制錯誤訊息在社群媒體平台上的散播。"},{"w":"control","p":"n.","d":"the actual power to influence or dictate behavior.","c":"控制權、克制力","s":"The experienced pilot kept full control of the aircraft even when there was severe turbulence over the mountains.","t":"即使在山區上空遭遇嚴重亂流，這位經驗豐富的飛行員仍完全掌控著飛機。"},{"w":"controlled","p":"adj.","d":"kept within set limits; highly organized.","c":"受控制的、克制的","s":"Scientists ran a controlled experiment to test whether the new medicine was safe and effective for treating the disease.","t":"科學家進行了一項受控實驗，以測試這種新藥物治療該疾病是否安全有效。"},{"w":"uncontrolled","p":"adj.","d":"outside of bounds; not managed or restricted.","c":"未受控制的、放任的","s":"The uncontrolled forest fire spread rapidly because of the strong wind, and firefighters struggled to contain the flames.","t":"失控的森林大火因強風迅速蔓延，消防員努力控制火勢。"},{"w":"uncontrollably","p":"adv.","d":"in an extreme way that cannot be managed.","c":"無法控制地","s":"When she heard the sad news about her pet, she began to cry uncontrollably and could not stop for a long time.","t":"當她聽到關於寵物的悲傷消息時，她開始無法控制地哭泣，很長時間都無法停下來。"},{"w":"control freak","p":"n.","d":"a person who obsessively wants to dictate events.","c":"控制狂","s":"My older brother is a real control freak; he insists on planning every single detail of our family holidays himself.","t":"我哥哥是個真正的控制狂；他堅持要自己規劃家庭假期的每一個細節。"},{"w":"under control","p":"phr.","d":"being handled or dealt with successfully.","c":"在控制中、情況穩定","s":"The doctor assured the family that the patient's fever was under control and that she would recover very soon.","t":"醫生向家屬保證，病人的發燒已在控制中，她很快就會康復。"},{"w":"out of control","p":"phr.","d":"wild; unable to be regulated or stopped.","c":"失去控制","s":"The argument between the two students got completely out of control, so the teacher had to step in immediately.","t":"兩名學生之間的爭吵完全失去控制，老師不得不立即介入。"},{"w":"take control of","p":"phr.","d":"to assume management or command over.","c":"接管、控制","s":"When the manager fell ill, the deputy had to take control of the project and ensure everything was completed on time.","t":"當經理生病時，副手不得不接管這個項目，確保一切按時完成。"},{"w":"manner","p":"n.","d":"the specific way in which work is conducted.","c":"方式、方法","s":"The teacher explained the difficult grammar rule in a clear and patient manner so that all students could understand.","t":"老師以清晰耐心的方式解釋了這條困難的語法規則，讓所有學生都能理解。"},{"w":"manner","p":"n.","d":"a person's outward behavior or attitude.","c":"態度、神態","s":"The doctor had a warm and friendly manner that made the nervous patients feel much more comfortable and relaxed.","t":"這位醫生態度親切友善，讓緊張的病人感到舒適放鬆許多。"},{"w":"manners","p":"n.","d":"polite ways of treating other people socially.","c":"禮貌、風度","s":"Her parents taught her good manners from a young age, so she always says please and thank you to everyone.","t":"她的父母從小就教她良好的禮貌，所以她總是對每個人說請和謝謝。"},{"w":"all manner of","p":"phr.","d":"many different types of items or ideas.","c":"各種各樣的","s":"The market sold all manner of goods, from fresh vegetables and handmade crafts to antique furniture and rare books.","t":"這個市場出售各種各樣的商品，從新鮮蔬菜和手工藝品到古董家具和珍本書籍。"},{"w":"in a manner of speaking","p":"phr.","d":"true in some way or from a certain perspective.","c":"算是在某種程度上、可以說是","s":"In a manner of speaking, he is the heart of the team, because without his energy, everyone loses motivation.","t":"可以說，他是團隊的核心，因為沒有他的活力，每個人都會失去動力。"},{"w":"amateur","p":"adj.","d":"participating in an activity for fun, not a job.","c":"業餘的","s":"Although he is just an amateur photographer, his pictures are so beautiful that they have won several awards.","t":"雖然他只是一名業餘攝影師，但他的照片非常漂亮，已獲得了好幾個獎項。"},{"w":"amateur","p":"n.","d":"a person who does work without being paid.","c":"業餘愛好者","s":"As a complete amateur in cooking, she still managed to prepare a delicious three-course meal for her family.","t":"作為一個完全的業餘愛好者，她仍然成功地為家人準備了一頓美味的三道菜。"},{"w":"professional","p":"adj.","d":"relating to work that needs specific training.","c":"專業的、職業的","s":"You should seek professional advice from a qualified doctor before taking any new medication or changing your diet.","t":"在服用任何新藥物或改變飲食習慣之前，你應該向有資格的醫生尋求專業建議。"},{"w":"professional","p":"n.","d":"a person who earns high wages in a specialized field.","c":"專家、職業選手","s":"She trained for fifteen years before becoming a professional and now plays for one of the best tennis teams in the country.","t":"她訓練了十五年才成為職業選手，現在效力於全國最頂尖的網球隊之一。"},{"w":"burst / burst / burst","p":"v.","d":"to break open suddenly from internal pressure.","c":"爆裂、破裂","s":"The water pipe burst during the cold winter night, and water flooded the entire kitchen before morning.","t":"水管在寒冷的冬夜爆裂，到早晨之前整個廚房都被水淹沒了。"},{"w":"burst / burst / burst","p":"v.","d":"to move suddenly and fast into an area.","c":"闖、衝","s":"The excited puppy burst through the front door and jumped on everyone as soon as they arrived home.","t":"興奮的小狗一衝進前門，就在大家一到家時跳到每個人身上。"},{"w":"burst","p":"n.","d":"a sudden outbreak of short duration.","c":"爆發、突發","s":"There was a sudden burst of applause from the audience when the performer finished her final song on stage.","t":"當表演者在台上唱完最後一首歌時，觀眾席爆發出一陣掌聲。"},{"w":"outburst","p":"n.","d":"a sudden violent release of strong emotion.","c":"（情緒的）爆發、發作","s":"His angry outburst during the meeting shocked everyone in the room, and the manager asked him to step outside.","t":"他在會議期間的憤怒爆發震驚了室內所有人，經理要求他出去冷靜一下。"},{"w":"burst into","p":"phr.","d":"to suddenly begin to burn, cry, or laugh.","c":"突然開始（哭/笑）、陷入","s":"When she heard the surprise birthday song, she burst into tears of joy and hugged all her friends tightly.","t":"當她聽到驚喜生日歌時，她突然喜極而泣，緊緊地擁抱了所有朋友。"},{"w":"burst out","p":"phr.","d":"to suddenly say something or laugh out loud.","c":"突然開始（笑/大叫）","s":"The children could not help but burst out laughing when the clown tripped over his own enormous shoes.","t":"當小丑被自己的大鞋子絆倒時，孩子們忍不住突然大笑起來。"},{"w":"flame","p":"n.","d":"a hot bright stream of burning gas; fire.","c":"火焰","s":"The candle flame flickered gently in the breeze, casting a warm and golden glow across the dining table.","t":"燭焰在微風中輕柔地搖曳，在餐桌上投下溫暖的金色光芒。"},{"w":"inflame","p":"v.","d":"to provoke or intensify strong emotional feelings.","c":"激怒、煽動","s":"The politician's careless remarks only served to inflame the tension between the two communities even further.","t":"這位政治人物不謹慎的言論只會進一步激化兩個社群之間的緊張關係。"},{"w":"inflamed","p":"adj.","d":"red, painful, and swollen from an infection.","c":"發炎的、紅腫的","s":"Her throat became so inflamed after the infection that she could barely swallow water without feeling sharp pain.","t":"感染後她的喉嚨變得非常發炎，幾乎無法吞嚥水而不感到劇烈疼痛。"},{"w":"fan the flames","p":"phr.","d":"to make a bad social scenario or feeling worse.","c":"助長火勢、煽風點火","s":"Posting negative comments online will only fan the flames and make the conflict between the two groups much worse.","t":"在網路上發表負面評論只會煽風點火，使兩組之間的衝突更加惡化。"},{"w":"go up in flames","p":"phr.","d":"to be destroyed by fire or fail completely.","c":"化為烏有、付諸東流","s":"Years of hard work seemed to go up in flames when the company suddenly announced it was closing down.","t":"當公司突然宣布關閉時，多年的努力似乎付諸東流了。"},{"w":"prosper","p":"v.","d":"to be highly successful, especially with wealth.","c":"繁榮、興旺、成功","s":"Small businesses began to prosper after the government reduced taxes and improved the local transport infrastructure.","t":"政府減稅並改善當地交通基礎設施後，小型企業開始興旺起來。"},{"w":"prosperity","p":"n.","d":"the stable state of being rich and successful.","c":"繁榮、興旺","s":"The country enjoyed a long period of prosperity after signing a free trade agreement with its neighbouring nations.","t":"這個國家在與鄰國簽署自由貿易協定後，享受了一段長期的繁榮時期。"},{"w":"prosperous","p":"adj.","d":"rich, affluent, and highly successful.","c":"繁榮的、富裕的","s":"The once prosperous city fell into poverty after the main factory closed and thousands of workers lost their jobs.","t":"這座曾經富裕的城市在主要工廠關閉、數千名工人失業後陷入了貧困。"},{"w":"universally","p":"adv.","d":"by absolutely everyone in a group or the world.","c":"全體地、普遍地","s":"The new school policy was universally welcomed by students and parents, as it reduced unnecessary homework on weekends.","t":"新的校規受到學生和家長的普遍歡迎，因為它減少了週末不必要的家庭作業。"},{"w":"universal","p":"adj.","d":"existing everywhere or involving all individuals.","c":"普遍的、全世界的","s":"Access to clean drinking water should be a universal right, but millions of people around the world still lack it.","t":"獲得乾淨飲用水應是普遍的權利，但全世界仍有數百萬人缺乏這項資源。"},{"w":"ray","p":"n.","d":"a narrow, straight beam of light or energy.","c":"光線、射線","s":"A single ray of sunlight broke through the dark clouds and lit up the wet street in a beautiful way.","t":"一道陽光穿透烏雲，以美麗的方式照亮了濕潤的街道。"},{"w":"X-ray","p":"n.","d":"a high-energy radiation scan to check bones.","c":"X光、X射線照片","s":"The doctor ordered an X-ray to check whether the patient had broken any bones after the fall.","t":"醫生要求拍X光片，以檢查病人摔倒後是否有骨折。"},{"w":"a ray of hope","p":"phr.","d":"a tiny sign that a scenario might improve.","c":"一線希望","s":"The new treatment offered a ray of hope to patients who had been told there was nothing more doctors could do.","t":"這種新療法為被告知醫生已無能為力的病人帶來了一線希望。"},{"w":"object","p":"n.","d":"a physical, solid thing that can be touched.","c":"物體","s":"A small round object fell from the shelf and rolled under the table before anyone could see what it was.","t":"一個小圓形物體從架子上掉下來，在任何人看清它是什麼之前就滾到桌子下面了。"},{"w":"object","p":"n.","d":"a goal, target, or purpose of an activity.","c":"目標、目的","s":"The object of the game is to collect as many points as possible before the timer runs out in the final round.","t":"遊戲的目標是在最後一輪計時結束前盡可能多地收集分數。"},{"w":"object","p":"v.","d":"to feel or express disapproval or opposition.","c":"反對","s":"Several residents objected to the plan to build a car park next to the school, citing concerns about traffic noise.","t":"幾位居民反對在學校旁邊建停車場的計劃，理由是擔心交通噪音問題。"},{"w":"objective","p":"adj.","d":"based completely on facts rather than feelings.","c":"客觀的","s":"A good journalist must remain objective and report the facts fairly without letting personal opinions affect the story.","t":"一位好記者必須保持客觀，公正地報導事實，不讓個人意見影響報導。"},{"w":"objective","p":"n.","d":"a goal or milestone you plan to achieve.","c":"目標、目的","s":"Our main objective this semester is to improve our English speaking skills by joining the debate club every week.","t":"我們這學期的主要目標是每週參加辯論社，提升英語口說能力。"},{"w":"objection","p":"n.","d":"an expression or feeling of disapproval.","c":"反對、異議","s":"The lawyer raised an objection to the witness's statement, arguing that it was not relevant to the case at all.","t":"律師對證人的陳述提出異議，認為這與案件完全無關。"},{"w":"contribution","p":"n.","d":"money, ideas, or help given to achieve a goal.","c":"貢獻、捐款","s":"Her contribution to the research project was so significant that she was listed as the second author of the paper.","t":"她對這個研究項目的貢獻如此重大，以至於她被列為論文的第二作者。"},{"w":"contribute","p":"v.","d":"to give funds, assistance, or ideas to a cause.","c":"貢獻、捐助","s":"Many local businesses agreed to contribute money to the new community centre so that everyone could benefit from it.","t":"許多本地企業同意捐款資助新的社區中心，讓所有人都能從中受益。"},{"w":"contribute","p":"v.","d":"to write articles or stories for a magazine.","c":"投稿","s":"She was proud to contribute an article about ocean conservation to the popular science magazine for young readers.","t":"她很自豪能向這本面向年輕讀者的科普雜誌投稿一篇關於海洋保育的文章。"},{"w":"make contributions to","p":"phr.","d":"to do actions that help a cause succeed.","c":"對…做出貢獻","s":"He has made contributions to medical science by discovering a faster way to identify dangerous viruses in blood samples.","t":"他透過發現在血液樣本中更快速識別危險病毒的方法，對醫學科學做出了貢獻。"},{"w":"medal","p":"n.","d":"a flat metal award given for bravery or sports.","c":"獎牌、勳章","s":"The firefighter was awarded a medal for bravery after he rescued a family from their burning house at great personal risk.","t":"這名消防員冒著巨大個人危險從火災房屋中救出一家人，因此獲頒勇敢勳章。"},{"w":"medallist","p":"n.","d":"a sports athlete who wins a medal in a contest.","c":"獎牌獲得者","s":"The Olympic gold medallist returned home to a hero's welcome, with thousands of fans cheering in the streets.","t":"這位奧運金牌得主返回故鄉受到英雄式的歡迎，數千名粉絲在街上歡呼。"},{"w":"gold medal","p":"n.","d":"an award given strictly to first-place winners.","c":"金牌","s":"She trained every single day for four years and finally won a gold medal at the international swimming championships.","t":"她每天訓練了四年，終於在國際游泳錦標賽上贏得了金牌。"},{"w":"silver medal","p":"n.","d":"an award given strictly to second-place winners.","c":"銀牌","s":"Although he only won a silver medal, his family was incredibly proud of his performance at the national competition.","t":"雖然他只獲得了銀牌，但他的家人對他在全國比賽中的表現感到無比自豪。"},{"w":"bronze medal","p":"n.","d":"an award given strictly to third-place winners.","c":"銅牌","s":"Winning a bronze medal at her first major competition gave the young athlete confidence to keep training hard.","t":"在她首次重大賽事中贏得銅牌，給了這位年輕運動員繼續努力訓練的信心。"},{"w":"earnings","p":"n.","d":"total money obtained from work or investments.","c":"收入、利潤、收益","s":"Her monthly earnings increased significantly after she completed the advanced coding course and got a promotion.","t":"完成進階程式設計課程並獲得晉升後，她的每月收入大幅增加。"},{"w":"earn","p":"v.","d":"to get money or praise by working for it.","c":"賺得、贏得","s":"He worked two part-time jobs on weekends to earn enough money to buy his mother a birthday present.","t":"他週末做兩份兼職工作，賺足夠的錢給媽媽買生日禮物。"},{"w":"net earnings","p":"n.","d":"clear business profit left after paying all costs.","c":"淨收益、淨利","s":"After paying all the staff salaries and bills, the company's net earnings for the quarter were lower than expected.","t":"支付所有員工薪資和帳單後，公司本季的淨收益低於預期。"},{"w":"deserted","p":"adj.","d":"completely empty of people; abandoned.","c":"荒無人煙的、被遺棄的","s":"The town centre was completely deserted at midnight, with not a single car or person visible on the dark streets.","t":"午夜時分，市中心完全荒無人煙，黑暗的街道上看不到任何車輛或行人。"},{"w":"desert","p":"v.","d":"to leave a person or post without permission.","c":"拋棄、遺棄、逃兵","s":"He felt terrible about having to desert his friends when they needed him most, but he had no other choice.","t":"他對在朋友最需要他時不得不拋棄他們感到非常內疚，但他別無選擇。"},{"w":"desert","p":"n.","d":"a massive, dry area of land with little water.","c":"沙漠","s":"Crossing the Sahara desert on foot is one of the most dangerous and challenging journeys anyone can attempt.","t":"徒步穿越撒哈拉沙漠是任何人都能嘗試的最危險、最具挑戰性的旅程之一。"},{"w":"dessert","p":"n.","d":"a sweet dish eaten at the end of a meal.","c":"甜點","s":"For dessert, the chef prepared a warm chocolate cake with a scoop of vanilla ice cream on the side.","t":"甜點是主廚準備的溫熱巧克力蛋糕，旁邊配上一球香草冰淇淋。"},{"w":"culture","p":"n.","d":"the unique way of life or art of a specific group.","c":"文化","s":"Studying abroad gave her a deeper understanding of Japanese culture, including its traditions, food, and customs.","t":"留學讓她對日本文化有了更深入的了解，包括其傳統、食物和風俗習慣。"},{"w":"culture","p":"n.","d":"a cluster of bacteria grown for scientific testing.","c":"培養菌、組織培養","s":"The scientists grew a culture of the bacteria in the lab to study how it responded to different antibiotic treatments.","t":"科學家在實驗室中培養了一批細菌，以研究它對不同抗生素治療的反應。"},{"w":"culture dish","p":"n.","d":"a shallow container used for growing bacteria.","c":"培養皿","s":"The biology student carefully placed a sample of the soil into a culture dish and left it in the warm incubator overnight.","t":"生物學學生小心地將土壤樣本放入培養皿中，並將其放置在溫暖的培育箱中過夜。"},{"w":"cultured","p":"adj.","d":"well-educated, well-mannered, and refined.","c":"有教養的、有文化的","s":"She was known as a cultured and sophisticated woman who could hold an intelligent conversation on any topic.","t":"她以有教養、有品味著稱，能就任何話題進行智性的對話。"},{"w":"cultured","p":"adj.","d":"grown or produced under artificial conditions.","c":"人工養殖的（珍珠等）","s":"Cultured pearls are created by inserting a small bead into an oyster and waiting for layers of nacre to form around it.","t":"人工養殖珍珠是通過將小珠子插入牡蠣中，等待珍珠質層在其周圍形成而製成的。"},{"w":"apparently","p":"adv.","d":"according to what seems true on the surface.","c":"顯然地、表面上看來","s":"Apparently, the famous restaurant has a six-month waiting list, so we should make a reservation as soon as possible.","t":"顯然，這家著名餐廳有六個月的候位名單，所以我們應該盡快訂位。"},{"w":"apparent","p":"adj.","d":"incredibly easy to see or clearly understood.","c":"明顯的、表面上的","s":"It was apparent from the student's confused expression that he had not understood the teacher's explanation at all.","t":"從這名學生困惑的表情可以明顯看出，他完全沒有理解老師的解釋。"},{"w":"modestly","p":"adv.","d":"in a quiet, humble way without boasting.","c":"謙虛地","s":"When asked about her award, she modestly said that she could not have done it without the support of her whole team.","t":"當被問及她的獎項時，她謙虛地說，若沒有整個團隊的支持，她是不可能做到的。"},{"w":"modestly","p":"adv.","d":"to a limited, moderate, or small degree.","c":"適度地、樸素地","s":"The apartment was modestly furnished with just the basics, but it was clean, comfortable, and perfectly suited for students.","t":"這間公寓陳設簡樸，只有基本家具，但乾淨舒適，非常適合學生居住。"},{"w":"modest","p":"adj.","d":"humble; not showing off or having too much pride.","c":"謙虛的","s":"Despite becoming the most popular student in school, she remained very modest and always treated everyone with respect.","t":"儘管成為學校最受歡迎的學生，她仍然非常謙虛，始終以尊重的態度對待每個人。"},{"w":"modest","p":"adj.","d":"moderate or relatively small in size or amount.","c":"適度的、不多的","s":"They lived in a modest house on the edge of town, but they were happy with what they had and asked for nothing more.","t":"他們住在城鎮邊緣一棟樸素的房子裡，但他們對自己擁有的一切感到滿足，別無所求。"},{"w":"modesty","p":"n.","d":"the virtue of being humble about your talents.","c":"謙遜、端莊","s":"His modesty was one of the qualities people admired most about him, even after he became a world-famous scientist.","t":"即使在他成為世界著名科學家之後，他的謙遜仍是人們最欣賞他的品質之一。"},{"w":"clumsy","p":"adj.","d":"moving awkwardly or breaking things easily.","c":"笨手笨腳的、笨拙的","s":"He is so clumsy in the kitchen that he always knocks things over and spills water every time he cooks.","t":"他在廚房裡非常笨手笨腳，每次做飯都會碰倒東西、灑出水來。"},{"w":"clumsiness","p":"n.","d":"the trait of lacking physical coordination.","c":"笨拙、手腳不靈活","s":"Her clumsiness on the dance floor made everyone laugh kindly, but she kept practising and eventually improved a lot.","t":"她在舞池上的笨拙讓大家善意地笑了起來，但她持續練習，最終進步了很多。"},{"w":"all thumbs","p":"phr.","d":"extremely awkward or clumsy with one's hands.","c":"笨手笨腳的","s":"When it comes to wrapping gifts, I am completely all thumbs — I always use too much tape and the paper never looks neat.","t":"說到包裝禮物，我完全笨手笨腳——我總是用太多膠帶，紙也從來都不整齊。"}]},{"unit":8,"theme":"resist – reluctantly","cards":[{"w":"resist","p":"v.","d":"to fight against or refuse to yield to something.","c":"抵抗、抗拒、忍住","s":"It is hard to resist eating another slice of cake when it smells so good and everyone around you is having one.","t":"當蛋糕聞起來如此誘人，而且周圍的人都在吃時，很難忍住不再吃一片。"},{"w":"resist chocolate","p":"phr.","d":"to turn away from sweets despite a strong craving.","c":"拒絕巧克力的誘惑","s":"She was on a strict diet, but she found it almost impossible to resist chocolate when her colleague brought some to work.","t":"她在嚴格節食，但當同事帶巧克力來上班時，她發現自己幾乎無法抗拒誘惑。"},{"w":"can't resist","p":"phr.","d":"to be completely helpless against a temptation.","c":"無法抗拒、忍不住","s":"He can't resist buying new books whenever he visits a bookshop, even though his shelves at home are already overflowing.","t":"每次逛書店他都忍不住買新書，儘管家裡的書架早已塞得滿滿的。"},{"w":"couldn't resist","p":"phr.","d":"was unable to stop oneself from taking an item.","c":"當時忍不住","s":"She couldn't resist taking a photo of the breathtaking sunset over the ocean, even though her phone battery was nearly dead.","t":"她當時忍不住拍下那片令人屏息的海上夕陽，儘管她的手機電量已快耗盡。"},{"w":"resistance","p":"n.","d":"the act of fighting off or blocking an action.","c":"抵抗力、反抗","s":"The government's new policy met strong resistance from local residents who were worried about the impact on their community.","t":"政府的新政策遭到當地居民的強烈抵抗，他們擔心這會對社區造成影響。"},{"w":"resistant","p":"adj.","d":"not easily harmed or entered by an external force.","c":"具抵抗力的、防…的","s":"This special coating makes the surface water-resistant, so spills can be wiped off easily without leaving any stain.","t":"這種特殊塗層使表面具有防水性，因此液體灑出後可以輕鬆擦拭而不留下任何污漬。"},{"w":"ingredient","p":"n.","d":"one of the foods or items that a mixture contains.","c":"原料、成分、配料","s":"She checked the label carefully to make sure none of the ingredients in the sauce would trigger her nut allergy.","t":"她仔細查看標籤，確保醬料中沒有任何會引發她堅果過敏的成分。"},{"w":"important ingredient","p":"phr.","d":"a crucial baseline item required inside a formula.","c":"重要原料","s":"Trust is the most important ingredient in any healthy relationship, whether it is between friends, family members, or colleagues.","t":"信任是任何健康關係中最重要的原料，無論是朋友、家人還是同事之間。"},{"w":"key ingredient","p":"phr.","d":"the central piece that ensures a project works.","c":"關鍵要素","s":"Hard work and consistency are the key ingredient to success, but having a clear goal also makes a huge difference.","t":"努力工作和持之以恆是成功的關鍵要素，但擁有明確的目標也會帶來巨大的差異。"},{"w":"differ","p":"v.","d":"to be unique or different from something else.","c":"不同、相異","s":"Opinions on the new school uniform policy differ greatly among students, with some supporting it and others opposing it.","t":"學生們對新校服政策的看法差異很大，有些人支持，有些人反對。"},{"w":"differ from","p":"phr.","d":"to showcase distinct features compared to another.","c":"與…不同","s":"The culture in southern Taiwan differs from the north in many ways, including food, festivals, and daily customs.","t":"台灣南部的文化在許多方面與北部不同，包括飲食、節慶和日常習俗。"},{"w":"different","p":"adj.","d":"not the same; separate or distinct.","c":"不同的","s":"Although they are twins, their personalities are completely different — one is very outgoing while the other is quite shy.","t":"雖然他們是雙胞胎，但個性截然不同——一個非常外向，另一個則相當害羞。"},{"w":"difference","p":"n.","d":"a point or way in which entities are not identical.","c":"相異之處、差別","s":"Can you spot the difference between these two photographs? One was taken in summer and the other was taken in winter.","t":"你能找出這兩張照片的差別嗎？一張攝於夏天，另一張攝於冬天。"},{"w":"make a difference","p":"phr.","d":"to cause an impactful change on a status.","c":"產生影響、改善","s":"Even small actions like recycling and saving water can make a difference to the environment if everyone does their part.","t":"即使是回收和節水這樣的小舉動，如果每個人都盡一份力，也能對環境產生影響。"},{"w":"differentiate","p":"v.","d":"to recognize or express the gap between items.","c":"區分、辨別","s":"Young children often find it difficult to differentiate between fantasy and reality when they watch animated films or cartoons.","t":"幼兒在觀看動畫電影或卡通時，常常難以區分幻想和現實。"},{"w":"considerably","p":"adv.","d":"by a large, notable, or significant amount.","c":"相當地、非常地","s":"The temperature dropped considerably overnight, so everyone had to put on extra layers of clothing the next morning.","t":"氣溫在一夜之間大幅下降，所以每個人第二天早上都必須多穿幾層衣服。"},{"w":"considerable","p":"adj.","d":"large or important enough to notice.","c":"相當大/多的、值得考慮的","s":"It takes a considerable amount of practice to become fluent in a foreign language, so you must be patient with yourself.","t":"要流利地掌握一門外語需要相當多的練習，所以你必須對自己有耐心。"},{"w":"considerably taller","p":"phr.","d":"higher by a very obvious and visible measure.","c":"拔尖許多、高出很多","s":"When she visited her primary school again as an adult, everything seemed so small — she was now considerably taller than the desks.","t":"當她成年後再次回到小學時，一切都顯得那麼小——她現在比桌子高出許多。"},{"w":"smooth","p":"adj.","d":"having an even surface; without issues or bumps.","c":"光滑的、平穩的、順利的","s":"The road through the mountain was surprisingly smooth, making the long drive much more comfortable than we expected.","t":"穿越山區的道路出乎意料地平穩，讓漫長的車程比我們預期的舒適許多。"},{"w":"smooth","p":"v.","d":"to press down or flatten out wrinkles.","c":"使平整、撫平","s":"She used her hands to smooth the tablecloth before placing the dishes down so that everything looked neat and tidy.","t":"她用手撫平桌布，然後再擺放餐具，讓一切看起來整齊乾淨。"},{"w":"smooth shirt","p":"phr.","d":"to flatten out garment folds using your hands.","c":"撫平襯衫","s":"He quickly smoothed his shirt before his job interview began, wanting to make the best possible first impression.","t":"面試開始前他迅速撫平襯衫，希望留下最好的第一印象。"},{"w":"smooth trip","p":"phr.","d":"a vacation or transit tracking zero delays.","c":"順利的旅程","s":"Despite our worries about traffic and weather, we had a very smooth trip and arrived at the destination right on time.","t":"儘管我們擔心交通和天氣，這次旅程非常順利，我們準時抵達了目的地。"},{"w":"smoothly","p":"adv.","d":"flawlessly; without any problem or complication.","c":"順利地、平穩地","s":"The event ran very smoothly thanks to the careful planning of the organizing committee, and everyone had a great time.","t":"由於籌備委員會的周密規劃，活動進行得非常順利，每個人都玩得非常開心。"},{"w":"smooth out","p":"phr.","d":"to remove challenges or wrinkles from an item.","c":"消除（問題）、使平滑","s":"The team held several extra meetings to smooth out the remaining issues before the product launch next month.","t":"團隊舉行了幾次額外的會議，在下個月產品發布前消除剩餘的問題。"},{"w":"liquid","p":"n.","d":"a substance that flows freely like pure water.","c":"液體","s":"The doctor advised her to drink plenty of liquid every day to stay hydrated and help her body recover faster.","t":"醫生建議她每天多喝液體，以保持水分充足，幫助身體更快恢復。"},{"w":"liquid","p":"adj.","d":"in a fluid form; easily converted into fast cash.","c":"液態的、流動性的","s":"The financial advisor suggested keeping some liquid assets so that the money could be accessed quickly in an emergency.","t":"財務顧問建議保留一些流動資產，以便在緊急情況下能夠迅速動用資金。"},{"w":"liquid in the glass","p":"phr.","d":"an unknown fluid held inside a drinking vessel.","c":"杯中的液體","s":"No one was sure what the liquid in the glass was, but it had a strange dark colour and an unusual sweet smell.","t":"沒有人確定杯中的液體是什麼，但它呈奇怪的深色，並散發出一股不尋常的甜味。"},{"w":"fold","p":"v.","d":"to bend something over so one part covers another.","c":"折疊、對折","s":"Please fold the letter neatly and place it inside the envelope before sealing it and writing the address on the front.","t":"請將信紙整齊折好，放入信封後封口，再在正面寫上地址。"},{"w":"fold","p":"n.","d":"a bent line or layer created inside cloth or paper.","c":"摺線、摺痕、褶皺","s":"She noticed a fold in the map where it had been creased so many times that the paper was beginning to tear.","t":"她注意到地圖上有一條摺痕，由於被反覆折疊多次，紙張已開始破裂。"},{"w":"fold clothing","p":"phr.","d":"to stack garments neatly before storage.","c":"折衣服","s":"Her mother taught her to fold clothing properly and put it away in the drawer as soon as it came out of the dryer.","t":"她媽媽教她在衣物從烘乾機取出後，立即將衣服折好並放入抽屜。"},{"w":"fold of the curtain","p":"phr.","d":"a natural wave or layered flap inside hanging cloth.","c":"窗簾的褶皺","s":"The sunlight filtered through the fold of the curtain and cast long golden stripes across the wooden floor of the room.","t":"陽光透過窗簾的褶皺照射進來，在房間的木地板上投下長長的金色光條。"},{"w":"folder","p":"n.","d":"a cover used to hold loose sheets of paper.","c":"資料夾","s":"She kept all her important documents in a clearly labelled folder so that she could find them quickly when needed.","t":"她將所有重要文件放在標示清楚的資料夾中，以便在需要時能快速找到。"},{"w":"unfold","p":"v.","d":"to open out from a folded state; to develop.","c":"展開、呈現","s":"We watched the dramatic rescue unfold live on the news and held our breath until everyone was confirmed safe.","t":"我們在新聞直播中觀看了這場戲劇性的救援行動展開，屏息等待直到所有人都確認安全。"},{"w":"gain","p":"v.","d":"to obtain something useful or increase in an asset.","c":"獲得、增加、贏得","s":"Travelling to different countries allows you to gain a broader perspective and a deeper understanding of the world.","t":"前往不同國家旅行讓你能獲得更廣闊的視野和對世界更深刻的理解。"},{"w":"gain","p":"n.","d":"an increase in benefit, wealth, or general weight.","c":"獲益、好處、增長","s":"The company reported a significant gain in profits this year, largely due to the success of its new product line.","t":"公司報告今年利潤大幅增長，這主要歸功於其新產品線的成功。"},{"w":"gain skills","p":"phr.","d":"to master practical abilities through work.","c":"獲得技能","s":"Volunteering at a local hospital is a great way to gain skills in communication, teamwork, and problem-solving.","t":"在當地醫院擔任義工是獲得溝通、團隊合作和解決問題技能的好方法。"},{"w":"gain weight","p":"phr.","d":"to become heavier in total physical body mass.","c":"體重增加、變胖","s":"She noticed she had started to gain weight after switching to a desk job that required very little physical activity.","t":"她注意到自己換了一份幾乎不需要體力活動的坐辦公室工作後，開始體重增加。"},{"w":"gain ground","p":"phr.","d":"to make steady progress or win popular support.","c":"取得進展、前進","s":"The new political party began to gain ground quickly after its leader gave a powerful speech that resonated with voters.","t":"這個新政黨在其領袖發表了引起選民共鳴的有力演講後，迅速取得進展。"},{"w":"attention","p":"n.","d":"the act of watching, listening, or caring carefully.","c":"注意力、關注","s":"The teacher clapped her hands twice to get the class's attention before explaining the instructions for the next activity.","t":"老師拍了兩下手以吸引全班的注意力，然後再說明下一個活動的指示。"},{"w":"keep attention","p":"phr.","d":"to hold a group's focus on a single speaker.","c":"保持注意力","s":"A skilled presenter uses stories and visuals to keep attention and prevent the audience from losing interest or focus.","t":"有技巧的演講者會運用故事和視覺效果來保持注意力，防止觀眾失去興趣或專注力。"},{"w":"pay attention","p":"phr.","d":"to direct your sight or mind fully to a task.","c":"注意、留心","s":"If you pay attention during the cooking demonstration, you will be able to follow the recipe at home with no trouble.","t":"如果你在烹飪示範時留心，回家後就能輕鬆地照著食譜做。"},{"w":"pay attention to someone","p":"phr.","d":"to listen closely to an individual's speech.","c":"注意某人","s":"She felt ignored at the meeting because nobody seemed to pay attention to her when she was sharing her ideas.","t":"她在會議中感到被忽視，因為當她分享想法時，似乎沒有人注意她說話。"},{"w":"attract attention","p":"phr.","d":"to draw eyes and minds to your setup.","c":"吸引注意","s":"The street performer began juggling fire to attract attention from the large crowd passing through the busy square.","t":"街頭表演者開始耍火把，以吸引穿越繁忙廣場的大批人群的注意。"},{"w":"throughout","p":"n.","d":"in every single part of a place; during a whole time.","c":"遍及、在各處、自始至終","s":"She remained calm and professional throughout the entire interview, even when the questions became very challenging.","t":"整個面試過程中，她始終保持冷靜和專業，即使問題變得非常具有挑戰性。"},{"w":"throughout the city","p":"phr.","d":"echoing or existing across all neighborhoods.","c":"遍及全城","s":"Colourful banners and decorations were hung throughout the city to celebrate the upcoming national holiday next week.","t":"為慶祝下週即將到來的國定假日，彩色橫幅和裝飾物懸掛遍及全城。"},{"w":"throughout the meeting","p":"phr.","d":"across the entire duration of a presentation.","c":"整個會議期間","s":"He took detailed notes throughout the meeting so that he could write an accurate summary report for those who were absent.","t":"他在整個會議期間做了詳細的筆記，以便為缺席者撰寫準確的摘要報告。"},{"w":"properly","p":"adv.","d":"correctly, in a right way, or suitably.","c":"正確地、妥善地、適當地","s":"Make sure you wash your hands properly with soap for at least twenty seconds before touching any food in the kitchen.","t":"確保在接觸廚房任何食物之前，用肥皂正確洗手至少二十秒。"},{"w":"proper","p":"adj.","d":"correct or acceptable for a specific scenario.","c":"適當的、正當的","s":"It is important to wear proper safety equipment when cycling on busy roads to protect yourself from accidents.","t":"在繁忙的道路上騎自行車時，穿戴適當的安全裝備以保護自己免受意外傷害是很重要的。"},{"w":"dressed properly","p":"phr.","d":"wearing garments fitting a specific social rule.","c":"穿著得體的","s":"All guests were expected to be dressed properly for the formal dinner, so the invitation clearly stated the dress code.","t":"所有賓客在正式晚宴上都需穿著得體，因此邀請函上清楚說明了著裝要求。"},{"w":"content","p":"n.","d":"the elements or objects held inside a container.","c":"內容物、目錄","s":"The customs officer asked her to remove all the contents from her bag so that everything could be inspected carefully.","t":"海關官員要求她取出包包裡的所有內容物，以便仔細檢查每一件物品。"},{"w":"content","p":"adj.","d":"happy and satisfied with what you already have.","c":"滿意的、滿足的","s":"She was perfectly content with her small apartment and simple lifestyle, and never felt the need for anything more.","t":"她對自己的小公寓和簡單的生活方式完全感到滿足，從不覺得需要更多。"},{"w":"content","p":"v.","d":"to make someone feel satisfied or pacified.","c":"使滿足、使滿意","s":"A warm bowl of soup and a good book was enough to content her after a long and exhausting day at the office.","t":"在辦公室度過漫長疲憊的一天後，一碗熱湯和一本好書足以讓她感到滿足。"},{"w":"contents of the box","p":"phr.","d":"the specific items kept inside a closed pack.","c":"箱中物品","s":"Nobody knew what the contents of the box were until the children tore off the wrapping paper on Christmas morning.","t":"直到孩子們在聖誕節早上撕開包裝紙，沒有人知道箱中的物品是什麼。"},{"w":"content to stay","p":"phr.","d":"happy to remain at base instead of traveling.","c":"滿足於留守","s":"While her friends went hiking on the weekend, she was perfectly content to stay at home and read her favourite novels.","t":"當朋友們週末去健行時，她完全滿足於留在家中閱讀她最喜愛的小說。"},{"w":"to one's heart's content","p":"phr.","d":"doing an activity as much as your mind wants.","c":"盡情地、心滿意足地","s":"On the last day of the holiday, the children played at the beach to their hearts' content until the sun went down.","t":"假期最後一天，孩子們在海灘上盡情地玩耍，直到太陽下山。"},{"w":"contented","p":"adj.","d":"showing happiness or stable peace of mind.","c":"滿足的、心安的","s":"The old farmer looked contented as he sat on his porch watching the sun set over the fields he had worked for decades.","t":"老農夫坐在門廊上，望著他耕作了數十年的田野上的落日，臉上流露出心滿意足的神情。"},{"w":"contentment","p":"n.","d":"a stable state of feeling satisfied and glad.","c":"滿足、知足","s":"True contentment comes not from owning more things, but from appreciating the simple and meaningful moments in life.","t":"真正的滿足感不來自擁有更多東西，而是來自珍惜生活中簡單而有意義的時刻。"},{"w":"discontent","p":"n.","d":"a feeling of unhappiness or lack of satisfaction.","c":"不滿、不平","s":"The workers expressed their discontent by staging a peaceful protest outside the headquarters of the company.","t":"工人們在公司總部外進行和平抗議，表達他們的不滿情緒。"},{"w":"desirable","p":"adj.","d":"worth having or causing people to want it.","c":"值得嚮往的、討人喜歡的","s":"Living close to public transport and good schools makes a neighbourhood highly desirable for families with young children.","t":"靠近大眾運輸和優良學校使一個社區對有小孩的家庭極具吸引力。"},{"w":"desirable pets","p":"phr.","d":"animal companions that are cleanly and highly valued.","c":"理想的寵物","s":"Cats and small dogs are considered the most desirable pets in city apartments because they need less space to move around.","t":"貓和小型犬被認為是城市公寓中最理想的寵物，因為它們需要的活動空間較少。"},{"w":"desire","p":"n.","d":"a strong hope or pull for an object.","c":"渴望、慾望","s":"Her deep desire to help others motivated her to volunteer at the food bank every single Saturday morning without fail.","t":"她幫助他人的強烈渴望驅使她每週六早上毫無例外地在食物銀行做義工。"},{"w":"undesirable","p":"adj.","d":"not wanted; causing problems or negative feedback.","c":"不受歡迎的、令人討厭的","s":"Bullying is a deeply undesirable behaviour that causes lasting emotional harm to victims and damages school culture overall.","t":"霸凌是一種極不受歡迎的行為，會對受害者造成持久的情感傷害，並全面破壞學校文化。"},{"w":"preferably","p":"adv.","d":"ideally; if possible, rather than another option.","c":"最好是、更精準地說","s":"Please submit your assignment in digital format, preferably as a PDF file, before midnight on the due date.","t":"請在截止日期午夜前以數位格式提交作業，最好是PDF檔案。"},{"w":"preferably by a window","p":"phr.","d":"picking a table position right next to glass.","c":"最好選在窗邊","s":"When the waiter asked where they would like to sit, they requested a table preferably by a window to enjoy the view.","t":"當服務生詢問他們想坐在哪裡時，他們要求一張最好在窗邊的桌子，以便欣賞風景。"},{"w":"preference","p":"n.","d":"a greater liking for one alternative over another.","c":"偏好、優先權","s":"Each student has different learning preferences, so the teacher tries to mix different activities in every lesson.","t":"每個學生有不同的學習偏好，所以老師嘗試在每堂課中融入不同的活動。"},{"w":"preferable","p":"adj.","d":"more attractive or suitable; chosen over options.","c":"更可取的、更合適的","s":"Taking the train is often more preferable than driving in the city, since you avoid traffic jams and parking fees.","t":"在城市裡搭火車通常比開車更可取，因為可以避免塞車和停車費。"},{"w":"prefer","p":"v.","d":"to like one specific item better than another.","c":"偏好、更喜歡","s":"Most students in the class prefer group projects to individual assignments because they enjoy working with their peers.","t":"班上大多數學生比起個人作業更偏好小組專題，因為他們喜歡與同學合作。"},{"w":"numerous","p":"adj.","d":"existing in a huge amount; many.","c":"許多的、無數的","s":"She received numerous job offers after graduating, but she carefully chose the one that matched her long-term career goals.","t":"畢業後她收到了無數的工作邀約，但她仔細選擇了符合長遠職涯目標的那一份。"},{"w":"numerous bills","p":"phr.","d":"a stack of separate payment sheets due at once.","c":"數不清的帳單","s":"After the holiday season, he was overwhelmed by numerous bills for gifts, travel, and restaurant meals all arriving together.","t":"假期結束後，他被禮物、旅行和餐廳消費等數不清的帳單同時湧來而感到不知所措。"},{"w":"preparation","p":"n.","d":"the process of getting ready for an event.","c":"準備、籌備","s":"Months of careful preparation went into organising the school's annual charity concert, and the hard work clearly paid off.","t":"學校年度慈善音樂會的籌備花費了數月的細心準備，這些努力明顯獲得了回報。"},{"w":"preparation of the meal","p":"phr.","d":"the time spent cooking food before dining.","c":"準備餐點","s":"The preparation of the meal took over two hours, but the family agreed that the delicious results were absolutely worth it.","t":"準備餐點花了兩個多小時，但家人一致認為美味的成果絕對值得。"},{"w":"in preparation for","p":"phr.","d":"completing work beforehand to receive an entry.","c":"為…做準備","s":"She practised her speech every evening in preparation for the national public speaking competition next month.","t":"她每天晚上練習演講，為下個月的全國演講比賽做準備。"},{"w":"prepare","p":"v.","d":"to make ready or build beforehand.","c":"準備、打算","s":"The chef began to prepare the ingredients at seven in the morning so that lunch service could start exactly at noon.","t":"主廚在早上七點開始準備食材，以便午餐服務能在正午準時開始。"},{"w":"arrange","p":"v.","d":"to position items neatly or organize a plan.","c":"排列、安排、佈置","s":"The librarian spent the morning carefully arranging the new books on the shelves in alphabetical order by author.","t":"圖書館員花了整個早上按作者姓名字母順序，將新書仔細排列在書架上。"},{"w":"arrange flowers","p":"phr.","d":"to style cut plants inside a decorative vase.","c":"插花、排列鮮花","s":"She learned how to arrange flowers beautifully after taking a weekend course at the community centre last spring.","t":"去年春天在社區中心上了一個週末課程後，她學會了如何漂亮地插花。"},{"w":"arrange for","p":"phr.","d":"to manage logistics or book a transit vehicle.","c":"安排、為…做準備","s":"Could you please arrange for a taxi to pick us up from the hotel at six tomorrow morning before our early flight?","t":"你能否安排一輛計程車明天早上六點到飯店接我們，趕我們的早班機？"},{"w":"arrangement","p":"n.","d":"a plan or the order in which items sit.","c":"安排、排列、約定","s":"The seating arrangement at the wedding reception was carefully planned so that guests from different groups could mix easily.","t":"婚宴的座位安排經過精心規劃，讓來自不同群體的賓客能夠輕鬆交流。"},{"w":"occasionally","p":"adv.","d":"sometimes but not very often.","c":"偶爾、有時","s":"She occasionally treats herself to a fancy dinner at a nice restaurant, but most evenings she prefers to cook at home.","t":"她偶爾會在高級餐廳享用一頓豐盛的晚餐，但大多數晚上她更喜歡在家煮飯。"},{"w":"occasional","p":"adj.","d":"happening or done from time to time.","c":"偶爾的","s":"Apart from the occasional heavy rain, the weather during our camping trip was mostly warm, sunny, and very pleasant.","t":"除了偶爾的大雨外，我們露營旅行期間的天氣大多溫暖晴朗，非常宜人。"},{"w":"occasion","p":"n.","d":"a special social event or an explicit moment.","c":"場合、時機、重大節日","s":"Her grandmother's ninetieth birthday was a very special occasion, celebrated with family members from across the country.","t":"她祖母的九十歲生日是一個非常特別的場合，與來自全國各地的家庭成員共同慶祝。"},{"w":"on occasion","p":"phr.","d":"once in a while; during sporadic breaks.","c":"偶爾","s":"He is usually very quiet in class, but on occasion he surprises everyone by asking a really thoughtful question.","t":"他在課堂上通常非常安靜，但偶爾他會提出一個非常有深度的問題，讓所有人都感到驚喜。"},{"w":"delight","p":"n.","d":"a feeling of great happiness or a source of joy.","c":"欣喜、令人高興的事物","s":"The children squealed with delight when they saw the enormous pile of gifts waiting for them under the Christmas tree.","t":"當孩子們看到聖誕樹下等待他們的大堆禮物時，高興地尖叫起來。"},{"w":"delight","p":"v.","d":"to give huge joy or entertainment to a group.","c":"使高興、使欣喜","s":"The magician's tricks never failed to delight the audience, and the children in the front row laughed and clapped non-stop.","t":"魔術師的把戲總是讓觀眾欣喜不已，前排的孩子們笑個不停、掌聲連連。"},{"w":"look of delight","p":"phr.","d":"a facial reflection showcasing high inner joy.","c":"欣喜的表情","s":"A wide look of delight spread across her face the moment she opened the box and saw the puppy inside.","t":"當她打開盒子看到裡面的小狗時，一臉欣喜的表情立刻浮現在她臉上。"},{"w":"a delight to see","p":"phr.","d":"an active joy to witness or watch play out.","c":"令人高興的一幕","s":"The way the two old friends reunited after thirty years apart was truly a delight to see and moved everyone present.","t":"兩位老友分別三十年後重聚的那一幕，真的是令人高興的一幕，感動了所有在場的人。"},{"w":"delight his friends","p":"phr.","d":"to make companions glad via entertainment.","c":"逗樂他的朋友們","s":"He always knew how to delight his friends by telling funny stories and doing silly impressions at every gathering.","t":"他總是知道如何在每次聚會中講有趣的故事和模仿搞笑的動作來逗樂他的朋友們。"},{"w":"delightful","p":"adj.","d":"causing a huge wave of pleasure; charming.","c":"令人愉快的、討人喜歡的","s":"The small seaside town was absolutely delightful, with its colourful boats, fresh seafood, and friendly local residents.","t":"這個小海濱小鎮絕對令人愉快，有著色彩繽紛的船隻、新鮮的海鮮和友善的當地居民。"},{"w":"delighted","p":"adj.","d":"feeling incredibly glad or pleased about an event.","c":"感到高興的、滿心歡喜的","s":"She was absolutely delighted when she found out she had been selected to represent her school at the national science fair.","t":"當她得知自己被選中代表學校參加全國科學展覽時，她感到非常高興。"},{"w":"digest","p":"v.","d":"to break down food inside the stomach.","c":"消化（食物）","s":"It is a good idea to take a short walk after a big meal to help your body digest the food more easily and comfortably.","t":"大餐後短暫散步是個好主意，幫助身體更輕鬆舒適地消化食物。"},{"w":"digest","p":"v.","d":"to fully understand complex data after review.","c":"領會、吸收（資訊）","s":"After the long lecture, she needed some quiet time to sit down and digest all the new information she had just received.","t":"漫長的課堂結束後，她需要一些安靜的時間坐下來消化所有剛接收到的新資訊。"},{"w":"hard to digest","p":"phr.","d":"tough for the stomach to break down easily.","c":"難以消化的","s":"Fried and greasy food is often hard to digest, especially for people who have sensitive stomachs or digestive problems.","t":"油炸和油膩的食物通常難以消化，尤其對腸胃敏感或有消化問題的人來說更是如此。"},{"w":"digest information","p":"phr.","d":"to unpack and learn massive lines of text data.","c":"消化/吸收資訊","s":"Students often find it easier to digest information when it is presented through diagrams, videos, and real-life examples.","t":"當資訊透過圖表、影片和現實生活中的例子呈現時，學生通常發現更容易吸收資訊。"},{"w":"digestive","p":"adj.","d":"relating to the body's track for breaking food.","c":"消化的","s":"Eating too quickly without chewing properly can cause serious digestive problems and discomfort after every meal.","t":"吃東西太快、咀嚼不充分可能會導致嚴重的消化問題和每餐後的不適感。"},{"w":"digestive system","p":"phr.","d":"the internal network that moves and filters food.","c":"消化系統","s":"A healthy diet rich in fibre and water supports the digestive system and helps prevent common problems like constipation.","t":"富含纖維和水分的健康飲食有助於消化系統，並幫助預防便秘等常見問題。"},{"w":"description","p":"n.","d":"words that tell what something looks or feels like.","c":"描述、描寫","s":"The witness gave a detailed description of the suspect to the police, including his height, hair colour, and clothing.","t":"目擊者向警方提供了嫌疑人的詳細描述，包括他的身高、髮色和衣著。"},{"w":"give a description","p":"phr.","d":"to state details to outline a target object.","c":"提供描述","s":"The tour guide asked everyone to give a description of their ideal holiday destination to help plan the perfect itinerary.","t":"導遊請每個人提供他們理想假期目的地的描述，以幫助規劃完美的行程。"},{"w":"describe","p":"v.","d":"to use adjectives and nouns to sketch an event.","c":"描述、形容","s":"Can you describe exactly what you saw at the scene of the accident so that we can write an accurate police report?","t":"你能準確描述你在事故現場看到的情況嗎？這樣我們才能撰寫準確的警方報告。"},{"w":"beyond description","p":"phr.","d":"so amazing or terrible that words cannot paint it.","c":"無法言喻的","s":"The natural beauty of the northern lights was truly beyond description, and no photograph could ever capture its full magic.","t":"北極光的自然美景真的無法言喻，沒有任何照片能夠捕捉到它完整的魔力。"},{"w":"reluctant","p":"adj.","d":"unwilling and hesitant to perform an action.","c":"不情願的、勉強的","s":"He was reluctant to admit that he had made a mistake, but eventually he apologised and promised to do better.","t":"他不情願承認自己犯了錯誤，但最終他道了歉，並承諾會做得更好。"},{"w":"reluctant to lend","p":"phr.","d":"tracking zero desire to pass cash over to a peer.","c":"勉予借出、不願出借","s":"She was very reluctant to lend her expensive camera to her classmate because he had a reputation for being careless.","t":"她非常不願意把昂貴的相機借給同學，因為他以粗心大意著稱。"},{"w":"reluctance","p":"n.","d":"an inner hesitation or lack of willingness.","c":"勉強、不情願","s":"Despite her obvious reluctance, she agreed to give a short speech at the school assembly when the teacher asked her.","t":"儘管明顯不情願，當老師請求時，她還是同意在學校集會上發表簡短的演講。"},{"w":"reluctantly","p":"adv.","d":"handling an assignment despite intense distaste.","c":"不情願地、勉強地","s":"He reluctantly agreed to join the dance performance after his friends spent three days convincing him it would be fun.","t":"在朋友們花了三天說服他這會很有趣之後，他勉強同意參加舞蹈演出。"}]},{"unit":9,"theme":"saying – wealth","cards":[{"w":"saying","p":"n.","d":"a well-known wise statement or traditional proverb.","c":"諺語、格言、俗話","s":"There is a popular saying that goes 'actions speak louder than words,' and it is still very true in everyday life.","t":"有句廣為人知的諺語說「行動勝於言辭」，在日常生活中仍非常真實。"},{"w":"folksy saying","p":"phr.","d":"a casual regional expression packed with old roots.","c":"民間諺語","s":"My grandmother always quoted a folksy saying whenever we faced a problem, and her words always seemed to help somehow.","t":"每當我們面對問題時，祖母總是引用一句民間諺語，而她的話總是以某種方式有所幫助。"},{"w":"as the saying goes","p":"phr.","d":"echoing a classic piece of old wisdom.","c":"常言道、正如俗話所說","s":"As the saying goes, 'every cloud has a silver lining,' and losing that job eventually led to a much better opportunity.","t":"常言道「黑暗中必有曙光」，丟掉那份工作最終帶來了更好的機會。"},{"w":"old saying","p":"phr.","d":"a historic line of insight used across generations.","c":"古老諺語","s":"There is an old saying that warns us not to judge a book by its cover, and this advice is as wise today as ever.","t":"有一句古老諺語警告我們不要以貌取人，這個忠告至今仍然非常有智慧。"},{"w":"beggar","p":"n.","d":"a poor person who lives by asking peers for money.","c":"乞丐","s":"A tired beggar sat outside the station with a cardboard sign, hoping that commuters might spare some loose change.","t":"一個疲憊的乞丐坐在車站外，拿著一塊紙板，希望通勤者能給一些零錢。"},{"w":"beg","p":"v.","d":"to request cash or help in a desperate manner.","c":"乞討、懇求","s":"The stray dog sat by the table and began to beg for food scraps by pawing at the leg of the nearest chair.","t":"那隻流浪狗坐在桌旁，用爪子撥弄最近的椅腳，開始乞求食物殘渣。"},{"w":"beg for","p":"phr.","d":"to ask with massive emotion for mercy or food.","c":"乞求…","s":"The child begged for one more hour of screen time before bed, but his parents firmly said no and turned off the TV.","t":"孩子懇求睡前再多一小時的螢幕時間，但父母堅決說不並關掉了電視。"},{"w":"charity","p":"n.","d":"an organization set up to give free help to needy peers.","c":"慈善機構","s":"She volunteers for a local charity every weekend, helping to pack and deliver food boxes to elderly residents nearby.","t":"她每個週末為一家本地慈善機構做義工，幫忙打包並將食物箱送到附近的老年居民家中。"},{"w":"charity","p":"n.","d":"the act of giving funds or kindness to others.","c":"慈善、施捨、仁慈","s":"He believed strongly in charity and always made a point of donating a portion of his monthly salary to those in need.","t":"他強烈相信慈善，總是堅持將每月薪水的一部分捐給有需要的人。"},{"w":"give to charity","p":"phr.","d":"to donate excess assets to support poor teams.","c":"捐助慈善","s":"After winning the prize, she decided to give to charity rather than spend the money on herself or luxury items.","t":"獲獎後，她決定將獎金捐助慈善，而不是將錢花在自己或奢侈品上。"},{"w":"charity work","p":"phr.","d":"active duties completed to support local poor lines.","c":"慈善工作","s":"The school encouraged students to participate in charity work during the summer holidays to build empathy and community spirit.","t":"學校鼓勵學生在暑假期間參與慈善工作，以培養同理心和社區精神。"},{"w":"charitable","p":"adj.","d":"generous in giving help or tracking kind minds.","c":"慈善的、仁慈的","s":"The charitable businessman donated millions to build a new children's hospital in the city where he grew up.","t":"這位慈善商人捐出數百萬元，在他成長的城市建造一所新的兒童醫院。"},{"w":"needy","p":"adj.","d":"poor; lacking essential food, clothes, or support.","c":"貧困的、生活匱乏的","s":"The organisation collects second-hand clothing and distributes it to needy families in rural areas every winter.","t":"這個組織收集二手衣物，每年冬天分發給農村地區的貧困家庭。"},{"w":"needy families","p":"phr.","d":"family circles with limited revenue or assets.","c":"貧困家庭","s":"The government scheme provides monthly food vouchers to needy families who cannot afford basic groceries for their children.","t":"政府計劃向無法為孩子負擔基本食品雜貨的貧困家庭提供每月食品券。"},{"w":"the needy","p":"n.","d":"all citizens currently dealing with deep poverty.","c":"窮人、生活匱乏者","s":"The soup kitchen opened its doors every evening to feed the needy in the neighbourhood, regardless of their background.","t":"這家愛心廚房每晚開門，為社區中的窮人提供餐食，不論其背景如何。"},{"w":"need","p":"v.","d":"a requirement for an object or to want an asset.","c":"需要","s":"There is a real need for more affordable housing in the city, as many working families cannot pay the high rents.","t":"這座城市確實需要更多可負擔的住房，因為許多工薪家庭無法支付高昂的租金。"},{"w":"in terms of","p":"phr.","d":"in relation to a specific feature or angle.","c":"就…而言、在…方面","s":"In terms of academic results, this year's graduating class performed better than any group in the past ten years.","t":"就學業成績而言，今年的畢業班表現優於過去十年的任何一屆。"},{"w":"in terms of weather","p":"phr.","d":"focusing strictly on climate quality during review.","c":"就天氣而言","s":"In terms of weather, spring is the best season to visit the island because it is warm, dry, and rarely windy.","t":"就天氣而言，春天是遊覽這座島嶼的最佳季節，因為天氣溫暖乾燥，很少有風。"},{"w":"found","p":"v.","d":"to establish or start a company or institution.","c":"創立、創辦、奠定","s":"She used her life savings to found a small bakery that has now grown into a well-known chain across five cities.","t":"她用畢生積蓄創立了一家小烘焙坊，如今已發展成橫跨五座城市的知名連鎖店。"},{"w":"found a company","p":"phr.","d":"to invest initial cash to launch a new firm.","c":"創立公司","s":"At only twenty-five years old, he managed to found a company that specialised in developing affordable medical devices.","t":"他僅二十五歲就成功創立了一家專門開發經濟實惠醫療設備的公司。"},{"w":"school was founded","p":"phr.","d":"an academy set up its active campus via an agent.","c":"學校被創立","s":"The school was founded over one hundred years ago by a group of missionaries who wanted to provide education for local children.","t":"這所學校是一百多年前由一群希望為當地兒童提供教育的傳教士所創立的。"},{"w":"foundation","p":"n.","d":"the baseline base or the start of an agency.","c":"基金會、基礎、地基","s":"The billionaire set up a charitable foundation to fund medical research and provide scholarships for students from low-income families.","t":"這位億萬富翁設立了一個慈善基金會，資助醫學研究並為低收入家庭的學生提供獎學金。"},{"w":"founder","p":"n.","d":"the central individual who launched an organization.","c":"創辦人、奠基者","s":"The founder of the company returned as its CEO after years away, hoping to restore the brand's original vision and values.","t":"這家公司的創辦人在多年離開後重返擔任執行長，希望恢復品牌最初的願景和價值觀。"},{"w":"advertising","p":"n.","d":"the corporate business of making items popular.","c":"廣告業、廣告投放","s":"She decided to study advertising at university because she wanted a creative career that combined design, writing, and strategy.","t":"她決定在大學攻讀廣告學，因為她想要一份結合設計、寫作和策略的創意職業。"},{"w":"work in advertising","p":"phr.","d":"to hold a job position designing market ads.","c":"從事廣告業","s":"He always dreamed of working in advertising and spent years building a portfolio before finally landing his first agency job.","t":"他一直夢想從事廣告業，花費多年建立作品集，才終於獲得第一份廣告公司的工作。"},{"w":"advertising medium","p":"phr.","d":"the specific pipeline used to carry promotional lines.","c":"廣告媒介","s":"Television remains a powerful advertising medium for reaching older audiences, even as younger viewers shift to online platforms.","t":"即使年輕觀眾轉移到網路平台，電視仍是觸及年長受眾的強大廣告媒介。"},{"w":"online advertising","p":"phr.","d":"promotional banners run across internet spots.","c":"網路廣告","s":"Online advertising has completely transformed the marketing industry, allowing businesses to target specific audiences with great precision.","t":"網路廣告已徹底改變了行銷產業，使企業能夠以極高的精準度針對特定受眾進行投放。"},{"w":"advertise","p":"v.","d":"to tell the public about a product to drive sales.","c":"登廣告、做宣傳","s":"The restaurant decided to advertise its new lunch menu on social media, and bookings increased significantly within a week.","t":"這家餐廳決定在社群媒體上宣傳其新午餐菜單，一週內預訂量大幅增加。"},{"w":"advertisement","p":"n.","d":"a specific public note designed to move an item.","c":"廣告（簡稱ad）","s":"The colourful advertisement on the back of the bus caught her eye and made her want to try the new ice cream flavour.","t":"公車後方那則色彩鮮豔的廣告吸引了她的目光，讓她想嘗試新口味的冰淇淋。"},{"w":"advertiser","p":"n.","d":"a corporate firm that pays cash to display ads.","c":"廣告商、廣告主","s":"The popular YouTube channel attracted many major advertisers because its videos consistently reached millions of viewers worldwide.","t":"這個熱門YouTube頻道吸引了許多大型廣告商，因為其影片持續觸及全球數百萬觀眾。"},{"w":"opportunity","p":"n.","d":"a chance to do something or achieve a major goal.","c":"機會、時機","s":"Studying abroad gave her the opportunity to experience a new culture and become fluent in a second language.","t":"出國留學給了她體驗新文化並流利掌握第二語言的機會。"},{"w":"opportunity of a lifetime","p":"phr.","d":"an incredible open door that rarely repeats.","c":"一生一次的難得機會","s":"Being selected to perform at the national concert hall was truly an opportunity of a lifetime that she would never forget.","t":"被選中在國家音樂廳演出真的是她永生難忘的一生一次難得機會。"},{"w":"take this opportunity","p":"phr.","d":"to actively use a moment to express state or thanks.","c":"藉此機會","s":"I would like to take this opportunity to thank everyone who supported the project and made this achievement possible.","t":"我想藉此機會感謝所有支持這個專案並使這一成就成為可能的人。"},{"w":"job opportunity","p":"phr.","d":"a corporate opening allowing you to apply for work.","c":"工作機會","s":"He spotted an exciting job opportunity at a technology firm in the city and immediately updated his résumé to apply.","t":"他在城市一家科技公司發現了一個令人興奮的工作機會，立即更新履歷提出申請。"},{"w":"chance","p":"n.","d":"a casual opening or random luck factor.","c":"機會、機率","s":"She never had the chance to study piano as a child, so she enrolled in adult lessons and has loved it ever since.","t":"她小時候從來沒有機會學鋼琴，所以她報名了成人課程，此後一直非常喜歡。"},{"w":"exact","p":"adj.","d":"completely correct or precise in every single digit.","c":"精確的、確切的","s":"Could you tell me the exact time the train departs? I need to make sure I arrive at the station early enough.","t":"你能告訴我火車確切的出發時間嗎？我需要確保足夠早到達車站。"},{"w":"exact amount","p":"phr.","d":"the specific currency cost matching a billing line.","c":"確切金額","s":"Please pay the exact amount shown on the invoice, as the system does not accept rounded figures or partial payments.","t":"請支付發票上顯示的確切金額，因為系統不接受四捨五入的數字或部分付款。"},{"w":"precise","p":"adj.","d":"highly accurate; focusing on meticulous limits.","c":"精準的","s":"The surgeon's movements must be extremely precise during the operation to avoid causing any unnecessary damage to tissue.","t":"外科醫生在手術過程中的動作必須極為精準，以避免對組織造成任何不必要的損傷。"},{"w":"not exactly","p":"phr.","d":"a phrase indicating a reply is partially false.","c":"不完全是、不見得","s":"'Did you enjoy the concert?' 'Well, not exactly — the first half was great, but the second half was quite boring.'","t":"「你喜歡這場音樂會嗎？」「嗯，不完全是——上半場很棒，但下半場相當無聊。」"},{"w":"partner","p":"n.","d":"a person or firm you complete shared work with.","c":"夥伴、搭檔、合夥人","s":"She and her business partner have worked together for twelve years and have built the company into a regional success.","t":"她和她的商業夥伴已合作了十二年，將公司打造成一個區域性的成功企業。"},{"w":"partner","p":"v.","d":"to join forces with another agency to do a project.","c":"合作、結為夥伴","s":"The local school decided to partner with a nearby university to give students access to professional science laboratories.","t":"這所本地學校決定與附近一所大學合作，讓學生能夠使用專業的科學實驗室。"},{"w":"partner with","p":"phr.","d":"to form an official alliance with a separate firm.","c":"與…合作","s":"The charity decided to partner with a well-known supermarket chain to collect food donations at every checkout counter.","t":"這家慈善機構決定與一家知名連鎖超市合作，在每個收銀台收集食物捐款。"},{"w":"tennis partner","p":"phr.","d":"a peer who plays on your side of the court.","c":"網球拍檔","s":"She asked her tennis partner to practise with her every morning before school so that they could improve their doubles game.","t":"她請她的網球拍檔每天上學前與她一起練習，以便提升他們的雙打技術。"},{"w":"partnership","p":"n.","d":"an ongoing alliance relationship between units.","c":"合作關係、合夥企業","s":"The two companies announced a long-term partnership to jointly develop new software solutions for the healthcare industry.","t":"這兩家公司宣布建立長期合作關係，共同為醫療保健產業開發新的軟體解決方案。"},{"w":"assemble","p":"v.","d":"to come together or bring a group into one room.","c":"集合、聚集","s":"All staff members were asked to assemble in the main conference room at nine o'clock for an important company announcement.","t":"所有員工被要求在九點鐘在主要會議室集合，聆聽一項重要的公司公告。"},{"w":"assemble","p":"v.","d":"to fit separate machine parts together to form a unit.","c":"組裝（機器等）","s":"It took him over three hours to assemble the flat-pack furniture, but the finished bookshelf looked exactly as pictured.","t":"他花了超過三個小時組裝這件平板包裝家具，但完成後的書架看起來和圖片一模一樣。"},{"w":"assemble students","p":"phr.","d":"to herd pupils into a primary auditorium spot.","c":"集合學生","s":"The principal asked the teachers to assemble students in the gymnasium before making an important announcement about the schedule.","t":"校長要求老師們在宣布重要課程通知前，先在體育館集合學生。"},{"w":"assemble outside","p":"phr.","d":"to form active lines out on an open sports field.","c":"在室外集合","s":"When the fire alarm rang, all students and teachers were instructed to assemble outside on the school playground immediately.","t":"當火災警報響起時，所有學生和老師被指示立即在學校操場上集合。"},{"w":"assemble parts","p":"phr.","d":"to construct raw imports into finished products.","c":"組裝零件","s":"The factory workers were trained to assemble parts quickly and accurately so that production targets could always be met.","t":"工廠工人接受了快速準確地組裝零件的培訓，以確保生產目標始終能夠達成。"},{"w":"assembly line","p":"phr.","d":"a factory setup where items move past workers.","c":"流水線、組裝線","s":"The introduction of the assembly line in the early twentieth century made it possible to produce cars at a much lower cost.","t":"二十世紀初流水線的引入使以低得多的成本生產汽車成為可能。"},{"w":"suitable","p":"adj.","d":"right or acceptable for a specific scenario.","c":"合適的、適宜的","s":"The committee reviewed several venues before choosing one that was suitable for hosting both indoor and outdoor events.","t":"委員會審查了幾個場地，然後選擇了一個適合舉辦室內和戶外活動的地點。"},{"w":"suitable clothing","p":"phr.","d":"garments that perfectly match current weather.","c":"合適的衣著","s":"The school trip notice reminded parents to pack suitable clothing for the children, as the weather in the mountains can change quickly.","t":"學校旅行通知提醒家長為孩子準備合適的衣著，因為山區天氣變化很快。"},{"w":"suitable for","p":"phr.","d":"tracking matching specifications for a dynamic activity.","c":"適合…的","s":"This hiking trail is not suitable for young children because it involves steep sections and requires a lot of stamina.","t":"這條登山步道不適合年幼的孩子，因為它有陡峭的路段，需要大量體力。"},{"w":"suit","p":"v.","d":"to look right on someone or match their needs.","c":"適合、相配","s":"The blue jacket really suits you — it matches your eyes and makes you look very professional and confident.","t":"那件藍色夾克真的很適合你——它與你的眼睛相配，讓你看起來非常專業自信。"},{"w":"permission","p":"n.","d":"the official token or nod allowing an action.","c":"許可、准許","s":"Students must get written permission from a parent or guardian before they are allowed to join any off-campus school activity.","t":"學生在被允許參加任何校外學校活動之前，必須獲得父母或監護人的書面許可。"},{"w":"need permission","p":"phr.","d":"requiring a signature from a parent before transit.","c":"需要許可","s":"All visitors need permission from the front office before they can enter the school building during teaching hours.","t":"所有訪客在教學時間內進入學校建築之前，都需要獲得前台辦公室的許可。"},{"w":"permit","p":"v.","d":"to allow an action to play out legally.","c":"允許、准許","s":"The park rules do not permit visitors to feed the wild animals, as it can disrupt their natural diet and behaviour.","t":"公園規則不允許訪客餵食野生動物，因為這可能會擾亂牠們的自然飲食和行為。"},{"w":"permit","p":"n.","d":"a printed paper license showing an access right.","c":"許可證、執照","s":"You will need a valid fishing permit before you can cast a line in this protected lake or you risk a heavy fine.","t":"在這個受保護的湖泊垂釣之前，你需要有效的釣魚許可證，否則可能面臨高額罰款。"},{"w":"prohibition","p":"n.","d":"an official rule blocking an entry or activity.","c":"禁止、禁令","s":"The prohibition on smoking inside all public buildings has significantly improved air quality and reduced health risks.","t":"在所有公共建築內禁止吸菸的禁令顯著改善了空氣品質並降低了健康風險。"},{"w":"authority","p":"n.","d":"the corporate group in power; a government body.","c":"當局、官方（常用複數）","s":"The local authority approved the construction of a new cycle path to encourage more residents to commute by bicycle.","t":"當地當局批准建造一條新的自行車道，以鼓勵更多居民騎自行車通勤。"},{"w":"authority","p":"n.","d":"an expert packed with massive specialized insight.","c":"權威、專家","s":"Professor Chen is widely regarded as a leading authority on ancient Chinese history and is often invited to speak globally.","t":"陳教授被廣泛認為是中國古代史的頂尖權威，經常受邀在全球各地演講。"},{"w":"the authorities","p":"phr.","d":"the official police or management handling crime.","c":"警方、官方、當局","s":"The authorities were alerted immediately after witnesses reported seeing suspicious activity near the bank late at night.","t":"目擊者報告在銀行附近深夜發現可疑活動後，當局立即接獲通報。"},{"w":"authority on history","p":"phr.","d":"an ultimate academic source for an era track.","c":"歷史權威","s":"She became a recognised authority on history after publishing three highly praised books on the Ming Dynasty.","t":"在出版了三本廣受好評的明朝著作後，她成為公認的歷史權威。"},{"w":"poster","p":"n.","d":"a large printed picture displayed on a wall.","c":"海報","s":"The students designed a colourful poster to promote the school's annual charity bake sale happening next Friday.","t":"學生們設計了一張色彩繽紛的海報，宣傳學校下週五舉行的年度慈善烘焙義賣活動。"},{"w":"host","p":"v.","d":"to organize or provide the space for a social party.","c":"主辦、主持、招待","s":"Our school will host an international science competition next month, welcoming student teams from fifteen different countries.","t":"我們學校下個月將主辦一場國際科學競賽，歡迎來自十五個不同國家的學生團隊。"},{"w":"host","p":"n.","d":"a person who receives and takes care of guests.","c":"主人、主持人","s":"The host greeted every guest warmly at the door and made sure everyone had a drink and felt welcome at the party.","t":"主人在門口熱情地迎接每位賓客，確保每個人都有飲料喝並在派對上感到賓至如歸。"},{"w":"host parties","p":"phr.","d":"to throw a celebration inside your home space.","c":"舉辦派對","s":"She loves to host parties for her close friends, preparing homemade food and decorating her apartment beautifully.","t":"她喜歡為親密朋友舉辦派對，準備自製食物並將公寓裝飾得美麗動人。"},{"w":"party's host","p":"phr.","d":"the central manager standing at the arrival door.","c":"派對主人","s":"The party's host spent the whole afternoon setting up decorations and preparing snacks before the guests began to arrive.","t":"派對主人花了整個下午布置裝飾並準備點心，然後賓客才開始陸續到來。"},{"w":"play host to","p":"phr.","d":"acting as the explicit city welcoming an event.","c":"主辦…、充當…的主人","s":"Taipei will play host to the international film festival this year, attracting directors and actors from around the globe.","t":"台北今年將主辦國際電影節，吸引來自全球各地的導演和演員。"},{"w":"hostess","p":"n.","d":"a female agent welcoming arrivals at a dinner.","c":"女主人","s":"The hostess welcomed each guest personally and guided them to their seats with a warm smile and a kind word.","t":"這位女主人親自迎接每位賓客，帶著溫暖的微笑和親切的話語引導他們入座。"},{"w":"poverty","p":"n.","d":"the state of being extremely poor without resources.","c":"貧窮、貧困","s":"Millions of people around the world still live in poverty without access to clean water, food, or basic healthcare.","t":"全世界數百萬人仍生活在貧困中，無法獲得乾淨的水、食物或基本醫療保健。"},{"w":"live in poverty","p":"phr.","d":"spending daily cycles without basic food or safe beds.","c":"生活在貧困中","s":"Many children who live in poverty struggle to focus at school because they are hungry or tired most of the time.","t":"許多生活在貧困中的孩子很難在學校集中注意力，因為他們大部分時間都感到飢餓或疲倦。"},{"w":"impoverish","p":"v.","d":"to make an active region or peer extremely poor.","c":"使貧困","s":"Years of conflict and drought continued to impoverish the region, leaving thousands of families without enough food to survive.","t":"多年的衝突和乾旱持續使這個地區陷入貧困，讓數千個家庭無法獲得足夠的食物維持生存。"},{"w":"impoverished","p":"adj.","d":"describing a town or household hit by heavy loss.","c":"貧困的、赤貧的","s":"The charity set up free tutoring centres in several impoverished neighbourhoods to help children access quality education.","t":"這家慈善機構在幾個貧困社區設立了免費輔導中心，幫助孩子們獲得優質教育。"},{"w":"wealth","p":"n.","d":"a massive bundle of capital or available assets.","c":"財富","s":"He inherited great wealth from his family, but he chose to use most of it to fund scholarships for underprivileged students.","t":"他從家族繼承了巨大的財富，但他選擇將大部分用於資助弱勢學生的獎學金。"}]},{"unit":10,"theme":"vocabulary – in conclusion","cards":[{"w":"vocabulary","p":"n.","d":"all the words known or used by a person.","c":"字彙、詞彙量","s":"She tried to expand her English vocabulary by reading one new article every day and writing down unfamiliar words.","t":"她嘗試每天閱讀一篇新文章並記下不熟悉的單字，以擴充她的英語字彙量。"},{"w":"entry vocabulary","p":"phr.","d":"active base words listing inside an index book.","c":"檢索字彙","s":"The entry vocabulary of the dictionary helps readers quickly locate the words they need without flipping through every page.","t":"字典的檢索字彙幫助讀者快速找到所需的單字，而不必翻閱每一頁。"},{"w":"build vocabulary","p":"phr.","d":"to study and master more phrases systematically.","c":"擴充詞彙量","s":"One of the best ways to build vocabulary is to read widely and pay attention to how words are used in context.","t":"擴充詞彙量的最佳方法之一是廣泛閱讀，並注意單字在語境中的使用方式。"},{"w":"limited vocabulary","p":"phr.","d":"knowing only a very small count of foreign words.","c":"有限的字彙量","s":"His limited vocabulary made it difficult to express his ideas clearly during the job interview conducted entirely in English.","t":"他有限的字彙量使他很難在完全用英語進行的工作面試中清楚表達自己的想法。"},{"w":"theme","p":"n.","d":"the main subject or unifying concept of an event.","c":"主題、中心思想","s":"The theme of this year's school festival is environmental protection, so every activity will focus on saving the planet.","t":"今年校園節慶的主題是環境保護，因此每項活動都將聚焦於拯救地球。"},{"w":"theme","p":"n.","d":"a recurring melodic phrase in a music piece.","c":"主題曲、主旋律","s":"The orchestra played the famous theme from the film, and the audience immediately recognized the iconic melody.","t":"管弦樂團演奏了這部電影中著名的主題曲，觀眾立刻認出了這段標誌性的旋律。"},{"w":"themed","p":"adj.","d":"designed according to a specific style concept.","c":"特定主題的","s":"The restaurant is themed around the 1950s, with vintage posters, jukebox music, and waiters in retro uniforms.","t":"這家餐廳以1950年代為特定主題，有復古海報、點唱機音樂和穿著復古制服的服務生。"},{"w":"theme park","p":"phr.","d":"an amusement park based on a central historical story.","c":"主題樂園","s":"The family spent the whole day at the theme park and rode every attraction before watching the evening fireworks show.","t":"這家人在主題樂園玩了整整一天，乘坐了每一個遊樂設施，然後觀看了晚上的煙火表演。"},{"w":"theme song","p":"phr.","d":"a signature track representing a cinema film.","c":"主題曲","s":"The theme song of the animated film became so popular that children all over the country were singing it at school.","t":"這部動畫電影的主題曲變得非常流行，全國各地的孩子都在學校裡唱著它。"},{"w":"topic","p":"n.","d":"a specific matter discussed inside a conversation.","c":"話題、論題","s":"The teacher asked students to choose a topic they felt passionate about for their end-of-term research presentation.","t":"老師要求學生為期末研究報告選擇一個他們感興趣的話題。"},{"w":"circulation","p":"n.","d":"the movement of blood or air through a system.","c":"循環（血液、空氣等）","s":"Regular exercise improves blood circulation and helps keep the heart healthy throughout your entire life.","t":"規律運動可以改善血液循環，有助於在整個生命過程中保持心臟健康。"},{"w":"circulation","p":"n.","d":"the continuous flow or passing around of coins.","c":"流通（貨幣、消息等）","s":"After the new banknotes were released, the old ones were gradually removed from circulation by the central bank.","t":"新鈔票發行後，舊鈔票逐漸被中央銀行從流通中撤回。"},{"w":"circulation","p":"n.","d":"the total number of magazine copies sold.","c":"發行量（報紙、雜誌等）","s":"The magazine's weekly circulation dropped significantly after most readers switched to reading news online for free.","t":"大多數讀者轉而在網路上免費閱讀新聞後，這本雜誌的每週發行量大幅下降。"},{"w":"circulate","p":"v.","d":"to move around continuously within a system.","c":"循環、流通、散布","s":"Rumours began to circulate around the school that the principal was planning to cancel the annual sports day.","t":"謠言開始在學校流傳，說校長正計劃取消年度運動會。"},{"w":"in circulation","p":"phr.","d":"being actively passed around or publicly used.","c":"在流通中、傳播中","s":"Several counterfeit banknotes are currently in circulation, so shop owners are advised to check carefully before accepting cash.","t":"目前有幾張偽鈔在流通中，因此建議店主在收取現金前仔細查驗。"},{"w":"out of circulation","p":"phr.","d":"withdrawn from public use or hidden from view.","c":"退出流通、不問世事","s":"After his injury, the tennis champion was out of circulation for almost a year before making a remarkable comeback.","t":"受傷後，這位網球冠軍幾乎有一年的時間淡出了公眾視野，然後才驚人地復出。"},{"w":"situation","p":"n.","d":"a set of conditions or state of affairs at a time.","c":"情況、處境、局勢","s":"The rescue team assessed the situation carefully before deciding on the safest way to reach the trapped hikers.","t":"救援隊在決定抵達被困登山者的最安全方式之前，仔細評估了情況。"},{"w":"sit-com","p":"n.","d":"a funny television track based on daily events.","c":"情境喜劇","s":"The family gathered on the sofa every Friday night to watch their favourite sit-com and laugh together.","t":"這家人每週五晚上都聚在沙發上一起觀看他們最喜愛的情境喜劇，共同歡笑。"},{"w":"satisfy a situation","p":"phr.","d":"to settle down a complex social crisis easily.","c":"應對局勢","s":"The experienced manager was able to satisfy a situation quickly and calm everyone down before things got out of hand.","t":"這位經驗豐富的經理能夠迅速應對局勢，在事情失控之前讓所有人平靜下來。"},{"w":"financial situation","p":"phr.","d":"the current debt and cash balance of a firm.","c":"財務狀況","s":"The family sat down together to review their financial situation and decided to cut back on unnecessary expenses for a while.","t":"這家人坐在一起審視他們的財務狀況，決定暫時削減不必要的開支。"},{"w":"situate","p":"v.","d":"to build or place something in a specific spot.","c":"使位於、處於","s":"The new library is situated in the heart of the city, making it easily accessible to students and residents alike.","t":"新圖書館位於市中心，讓學生和居民都能輕鬆前往。"},{"w":"spread","p":"v.","d":"to open out, cover, or affect a wider area.","c":"傳播、散布、蔓延","s":"The wildfire began to spread rapidly across the hillside because the dry wind made it impossible to contain the flames.","t":"山火開始在山坡上迅速蔓延，因為乾燥的強風使火焰無法被控制。"},{"w":"spread","p":"n.","d":"the growth or development of something over an area.","c":"傳播、蔓延","s":"Health officials worked urgently to slow the spread of the disease by tracing contacts and issuing public warnings.","t":"衛生官員緊急工作，通過追蹤接觸者和發出公共警告來減緩疾病的蔓延。"},{"w":"prevent the spread","p":"phr.","d":"to block a virus track from entering new spaces.","c":"阻止蔓延、防止傳播","s":"Wearing a mask and washing hands regularly can help prevent the spread of respiratory infections in crowded places.","t":"在擁擠的地方佩戴口罩和定期洗手有助於防止呼吸道感染的傳播。"},{"w":"spread butter","p":"phr.","d":"to smooth a dairy layer across toasted bread slices.","c":"抹奶油","s":"She taught her daughter how to spread butter evenly on toast so that every bite would taste the same.","t":"她教女兒如何將奶油均勻抹在吐司上，讓每一口的味道都一樣。"},{"w":"widespread","p":"adj.","d":"existing or happening over a very large area.","c":"廣泛的、普遍的","s":"There was widespread support for the new environmental policy, with people from all backgrounds signing the online petition.","t":"新環保政策獲得了廣泛的支持，來自各行各業的人們都在網路上簽署了請願書。"},{"w":"contact","p":"n.","d":"communication, touch, or social connection.","c":"接觸、聯繫","s":"The doctor advised her to avoid close contact with anyone who had symptoms until she had fully recovered from the flu.","t":"醫生建議她在完全從流感中康復之前，避免與任何有症狀的人密切接觸。"},{"w":"contact","p":"n.","d":"a useful person you know in an industry field.","c":"社會關係、聯絡人","s":"She used a professional contact in the publishing industry to help get her first manuscript reviewed by a major editor.","t":"她利用出版業的專業聯絡人，幫助讓一位主要編輯審閱她的第一份手稿。"},{"w":"contact","p":"v.","d":"to call, write, or communicate with an agent.","c":"聯絡、與…接觸","s":"Please contact the customer service team directly if you have any problems with your order or delivery.","t":"如果您的訂單或配送有任何問題，請直接聯絡客戶服務團隊。"},{"w":"eye contact","p":"phr.","d":"looking directly into another individual's eyes.","c":"目光接觸、眼神交流","s":"Making steady eye contact during a job interview shows that you are confident, engaged, and listening carefully.","t":"在工作面試中保持穩定的眼神交流表明你充滿自信、全神貫注並認真傾聽。"},{"w":"make contact with","p":"phr.","d":"to successfully call or reach an elusive agent.","c":"與…取得聯繫","s":"The journalist spent weeks trying to make contact with the whistleblower before finally receiving an anonymous message.","t":"這位記者花了數週時間試圖與告密者取得聯繫，最終才收到一條匿名訊息。"},{"w":"have contact with","p":"phr.","d":"keeping an active link to a specific corporate peer.","c":"與…有聯繫","s":"She still have contact with her former colleagues from the university and meets them for coffee every few months.","t":"她仍然與大學的前同事保持聯繫，每隔幾個月就與他們見面喝咖啡。"},{"w":"keep in contact with","p":"phr.","d":"to regularly update old school companions.","c":"與…保持聯繫","s":"It can be difficult to keep in contact with old friends after moving abroad, but social media makes it much easier.","t":"搬到國外後與老朋友保持聯繫可能很困難，但社群媒體讓這件事容易許多。"},{"w":"lose contact with","p":"phr.","d":"to stop communication across multiple years.","c":"與…失去聯繫","s":"She lost contact with her childhood best friend after they moved to different cities and both became very busy.","t":"她與童年最好的朋友失去了聯繫，因為他們搬到了不同的城市，兩人都變得非常忙碌。"},{"w":"come in contact with","p":"phr.","d":"to physically touch a dangerous chemical element.","c":"接觸到…","s":"Workers must wear gloves to avoid coming in contact with the toxic chemicals stored in the laboratory storage room.","t":"工人必須戴手套，以避免接觸到實驗室儲藏室中存放的有毒化學品。"},{"w":"zone","p":"n.","d":"an explicit region set aside for precise reasons.","c":"區域、地區、地帶","s":"The school created a quiet zone near the library where students could study without being disturbed by noise.","t":"學校在圖書館附近設立了一個安靜區域，學生可以在不受噪音干擾的情況下學習。"},{"w":"zone","p":"v.","d":"to divide an urban city into distinct building areas.","c":"劃分區域","s":"The city council decided to zone the northern district for residential use only, banning all new factory construction.","t":"市議會決定將北部地區劃分為純住宅用途，禁止所有新工廠的建設。"},{"w":"time zone","p":"phr.","d":"a regional longitudinal strip tracking one standard clock.","c":"時區","s":"When scheduling an online meeting with colleagues in New York, remember to check the time zone difference carefully.","t":"與紐約同事安排網路會議時，請記得仔細確認時區差異。"},{"w":"comfort zone","p":"phr.","d":"a psychological state where an individual feels safe.","c":"舒適圈","s":"Joining the debate club pushed her out of her comfort zone and helped her develop confidence in public speaking.","t":"加入辯論社讓她走出舒適圈，幫助她培養了公開演講的自信心。"},{"w":"zone out","p":"phr.","d":"to completely stop paying attention; daydream.","c":"恍神、發呆","s":"He tends to zone out during long lectures and often misses important information that appears on the exam.","t":"他在長時間的課堂中容易恍神，經常錯過考試中出現的重要資訊。"},{"w":"recover","p":"v.","d":"to become healthy again after an illness or injury.","c":"康復、痊癒","s":"It took her nearly three months to fully recover from the knee surgery before she could return to playing football.","t":"她花了將近三個月才完全從膝蓋手術中康復，然後才能重新踢足球。"},{"w":"recover","p":"v.","d":"to find or get back a lost or deleted asset file.","c":"恢復、尋回（檔案等）","s":"The IT technician was able to recover the deleted files from the hard drive before they were permanently overwritten.","t":"IT技術人員在檔案被永久覆蓋之前，成功從硬碟中恢復了已刪除的檔案。"},{"w":"recover from","p":"phr.","d":"to successfully heal up after a shocking event.","c":"從…中恢復/康復","s":"It took the entire community a long time to recover from the devastating flood that destroyed hundreds of homes.","t":"整個社區花了很長時間才從摧毀數百個家庭的毀滅性洪水中恢復過來。"},{"w":"recovery","p":"n.","d":"the process of returning to normal health or state.","c":"痊癒、恢復、重獲","s":"The athlete's recovery from the broken leg was faster than expected, and she was back training within eight weeks.","t":"這位運動員腿骨骨折的康復速度比預期快，她在八週內就恢復了訓練。"},{"w":"recoverable","p":"adj.","d":"able to be found, fixed, or claimed back cleanly.","c":"可恢復的、可收回的","s":"The data expert confirmed that the corrupted files were still recoverable and promised to restore them by the next morning.","t":"數據專家確認損壞的檔案仍然可以恢復，並承諾在第二天早上之前將其還原。"},{"w":"strategy","p":"n.","d":"a detailed plan for achieving success in war or work.","c":"策略、戰略","s":"The coach developed a new strategy for the championship match that focused on fast counter-attacks and tight defence.","t":"教練為錦標賽制定了一個新策略，專注於快速反擊和嚴密防守。"},{"w":"corporate strategy","p":"phr.","d":"a long-term commercial blueprint run by directors.","c":"公司戰略","s":"The board of directors met for three days to review the corporate strategy and set new goals for the next five years.","t":"董事會開了三天會議，審查公司戰略並為未來五年制定新目標。"},{"w":"marketing strategy","p":"phr.","d":"a systematic scheme to advertise new inventory units.","c":"行銷策略","s":"The startup's marketing strategy focused on social media influencers rather than traditional TV advertisements to save money.","t":"這家新創公司的行銷策略專注於社群媒體網紅，而不是傳統電視廣告，以節省資金。"},{"w":"strategize","p":"v.","d":"to spend extensive time designing master plans.","c":"制定策略、擬定戰略","s":"The team gathered before the competition to strategize and figure out the best approach for defeating their strongest rivals.","t":"團隊在比賽前聚集在一起制定策略，找出擊敗最強對手的最佳方法。"},{"w":"strategic","p":"adj.","d":"carefully planned to achieve a specific long term goal.","c":"戰略性的、策略上的","s":"Placing the new store in the city centre was a very strategic decision, as it attracted far more customers than expected.","t":"將新店開在市中心是一個非常具有策略性的決定，因為它吸引了遠超預期的顧客。"},{"w":"passenger","p":"n.","d":"a person traveling in a car, bus, train, or plane.","c":"乘客、旅客","s":"Each passenger was asked to present a valid ticket and a form of identification before boarding the overnight train.","t":"每位乘客在登上夜間列車之前，被要求出示有效車票和一種身分證明文件。"},{"w":"passenger seat","p":"phr.","d":"the spot right next to a vehicle's driver.","c":"副駕駛座","s":"She sat in the passenger seat and helped navigate using the map app while her husband concentrated on driving.","t":"她坐在副駕駛座，用地圖應用程式幫忙導航，而她的丈夫專心駕駛。"},{"w":"flight passenger","p":"phr.","d":"a traveler holding an active airline ticket.","c":"機艙乘客","s":"Every flight passenger was reminded to switch their phone to airplane mode before the aircraft began its take-off run.","t":"每位機艙乘客被提醒在飛機開始起飛滑行之前將手機切換到飛航模式。"},{"w":"calculate","p":"v.","d":"to discover a number or cost using math data.","c":"計算、估算","s":"The students used a formula to calculate the area of each triangle before comparing their answers with a partner.","t":"學生們使用公式計算每個三角形的面積，然後與同伴比較答案。"},{"w":"calculator","p":"n.","d":"a small electronic device used for math tasks.","c":"計算機","s":"He forgot to bring his calculator to the exam and had to work out all the arithmetic problems by hand instead.","t":"他忘記帶計算機去考試，不得不用手算出所有算術題。"},{"w":"calculation","p":"n.","d":"the active process of working out a total sum.","c":"計算、估計","s":"After a quick calculation, the accountant realized the company had spent far more than its budget for the quarter.","t":"經過快速計算後，會計師意識到公司這個季度的支出遠超預算。"},{"w":"calculated","p":"adj.","d":"planned or intended to achieve a specific effect.","c":"蓄意的、精心計畫的","s":"His calm response to the criticism was clearly calculated to avoid conflict and keep the negotiation on a positive track.","t":"他對批評的冷靜回應顯然是精心計畫的，目的是避免衝突並讓談判保持積極走向。"},{"w":"be calculated to","p":"phr.","d":"deliberately designed to cause an explicit result.","c":"旨在…、蓄意要…","s":"The advertisement was calculated to appeal to young parents by showing children playing happily with the product.","t":"這則廣告旨在通過展示孩子們快樂地玩弄產品來吸引年輕父母。"},{"w":"whenever","p":"n.","d":"at any time that; no matter when an event occurs.","c":"每當、無論何時","s":"Whenever she feels stressed about exams, she goes for a long walk in the park to clear her mind and relax.","t":"每當她對考試感到壓力時，她就去公園長途散步，以清醒頭腦並放鬆心情。"},{"w":"whenever possible","p":"phr.","d":"completing a priority task at any open opportunity.","c":"只要有可能","s":"The doctor advised him to exercise outdoors whenever possible to get fresh air and benefit from natural sunlight.","t":"醫生建議他只要有可能就在戶外運動，以獲得新鮮空氣並從自然陽光中受益。"},{"w":"fever","p":"n.","d":"a high body temperature caused by being sick.","c":"發燒","s":"The child developed a high fever overnight and was taken to the emergency room early the next morning.","t":"孩子在一夜之間發起高燒，第二天一早就被送往急診室。"},{"w":"fever","p":"n.","d":"a state of intense public excitement or agitation.","c":"狂熱","s":"World Cup fever swept through the entire country, with fans painting their faces and gathering in public squares to watch.","t":"世界杯狂熱席捲了整個國家，球迷們彩繪臉龐，聚集在公共廣場觀看比賽。"},{"w":"fever reducer","p":"phr.","d":"a pharmaceutical pill taken to clear away heat.","c":"退燒藥","s":"The pharmacist recommended a mild fever reducer for the child and advised the parents to monitor her temperature closely.","t":"藥劑師為孩子推薦了一種溫和的退燒藥，並建議父母密切監測她的體溫。"},{"w":"cabin fever","p":"phr.","d":"distress caused by being stuck indoors too long.","c":"幽居病、因久困室內引起的煩躁","s":"After two weeks of rain and staying indoors, the whole family started to experience cabin fever and felt restless.","t":"兩週的雨天和待在室內後，全家人開始出現幽居病的症狀，感到坐立不安。"},{"w":"discover","p":"v.","d":"to find information, a place, or an item first.","c":"發現、發掘","s":"Scientists recently discovered a new species of deep-sea fish that had never been seen or recorded before this year.","t":"科學家最近發現了一種深海魚類新物種，這是今年之前從未見過或記錄過的。"},{"w":"discovery","p":"n.","d":"the active process or item found for the first time.","c":"發現、新發現的事物","s":"The archaeological discovery of ancient pottery in the field changed what historians believed about the region's early settlers.","t":"田野中古代陶器的考古發現改變了歷史學家對該地區早期定居者的認知。"},{"w":"rediscover","p":"v.","d":"to appreciate or locate a forgotten value again.","c":"重新發現","s":"After years of working long hours, she took a sabbatical to travel and rediscover her passion for painting and music.","t":"在多年長時間工作後，她休了一個學術假去旅行，重新發現了她對繪畫和音樂的熱情。"},{"w":"charge","p":"v.","d":"to ask for an amount of money as a price fee.","c":"收費、索價","s":"The repair shop charged a reasonable fee to fix the cracked screen, and the phone was ready within two hours.","t":"這家維修店收取了合理的費用來修理裂開的螢幕，手機在兩小時內就準備好了。"},{"w":"charge","p":"v.","d":"to officially accuse someone of committing a crime.","c":"控告、指控","s":"The suspect was charged with theft after security footage clearly showed him taking items from the store.","t":"在安全錄影明確顯示他從商店拿走物品後，嫌疑人被指控盜竊。"},{"w":"charge","p":"v.","d":"to pass electrical energy into a device battery.","c":"充電","s":"She remembered to charge her phone fully before the long flight so she could listen to music the entire journey.","t":"她記得在長途飛行前將手機充滿電，這樣她就可以在整個旅程中聽音樂。"},{"w":"charge","p":"n.","d":"the price asked for a service or commercial item.","c":"費用、價款","s":"There is an extra charge for checking in luggage at the airport, so she decided to travel with only a carry-on bag.","t":"在機場託運行李需要額外收費，所以她決定只帶一個隨身行李旅行。"},{"w":"be charged with","p":"phr.","d":"being brought to court for a specific felony act.","c":"被指控/控告…","s":"The executive was charged with fraud after investigators found evidence of falsified financial records in the company.","t":"在調查人員在公司發現偽造財務記錄的證據後，這名高管被指控詐欺。"},{"w":"free of charge","p":"phr.","d":"costing zero currency; completely free to claim.","c":"免費","s":"Children under the age of five can enter the museum free of charge, but adults must purchase a ticket in advance.","t":"五歲以下的兒童可以免費進入博物館，但成人必須提前購票。"},{"w":"in charge of","p":"phr.","d":"holding active management power over a department.","c":"負責…、掌管…","s":"She was put in charge of the entire project after her manager was called away on an unexpected business trip.","t":"在她的經理因臨時出差而離開後，她被任命負責整個專案。"},{"w":"permanent","p":"adj.","d":"lasting or intended to stay open across all eras.","c":"永久的、長久的","s":"After three years on a temporary contract, she was finally offered a permanent position with full employee benefits.","t":"在三年的臨時合約後，她終於獲得了一個享有完整員工福利的永久職位。"},{"w":"permanent damage","p":"phr.","d":"a severe loss that can never be healed or fixed.","c":"永久性損傷","s":"Wearing headphones at maximum volume for long periods can cause permanent damage to your hearing over time.","t":"長時間以最大音量佩戴耳機可能會隨著時間對您的聽力造成永久性損傷。"},{"w":"for good","p":"phr.","d":"permanently; completely ending an old habit line.","c":"永遠地、一勞永逸地","s":"After years of trying, he finally managed to quit smoking for good and has not touched a cigarette since.","t":"經過多年嘗試，他終於成功永遠戒菸，此後再也沒有碰過香菸。"},{"w":"conclude","p":"v.","d":"to judge or decide something after checking facts.","c":"斷定、推斷出","s":"After reviewing all the evidence, the investigators concluded that the fire had been caused by a faulty electrical wire.","t":"在審查所有證據後，調查人員得出結論，認為火災是由故障電線引起的。"},{"w":"conclude","p":"v.","d":"to bring a presentation or speech to an end finish.","c":"結束、終結","s":"The speaker concluded her talk by thanking the audience and inviting questions from anyone in the room.","t":"演講者通過感謝觀眾並邀請室內任何人提問來結束她的演講。"},{"w":"conclusion","p":"n.","d":"an ultimate decision or opinion reached at the end.","c":"結論、結尾","s":"The committee reached the conclusion that the proposed building project would cause too much disruption to local residents.","t":"委員會得出結論，認為擬議的建設項目將對當地居民造成太多干擾。"},{"w":"in conclusion","p":"phr.","d":"a closing phrase used to summarize a speech pack.","c":"總之、最後（演講結語）","s":"In conclusion, I would like to emphasize that teamwork and communication are the two most important factors for success.","t":"總之，我想強調團隊合作和溝通是成功最重要的兩個因素。"}]},{"unit":11,"theme":"native – endangered species","cards":[{"w":"native","p":"adj.","d":"relating to the place where you were born.","c":"本地的、原產的","s":"The documentary focused on the native plants and animals of the island, many of which exist nowhere else on earth.","t":"這部紀錄片聚焦於這座島嶼的本地動植物，其中許多在地球上其他地方都不存在。"},{"w":"native","p":"n.","d":"a person born in a specific city or region.","c":"本地人、土著","s":"As a native of the city, she knew every shortcut and hidden café that tourists would never find on their own.","t":"作為這座城市的本地人，她了解每條捷徑和遊客自己永遠找不到的隱藏咖啡館。"},{"w":"native to","p":"phr.","d":"describing a plant line organically from an area.","c":"原產於…的","s":"The kiwi bird is native to New Zealand and has become one of the most recognised national symbols of the country.","t":"奇異鳥原產於紐西蘭，已成為該國最具代表性的國家象徵之一。"},{"w":"native of","p":"phr.","d":"an individual tracking their birth root to a town.","c":"…的本地人","s":"As a native of Tainan, he took great pride in showing visitors the city's famous temples and traditional street food.","t":"作為台南的本地人，他非常自豪地帶訪客參觀這座城市著名的廟宇和傳統街頭美食。"},{"w":"native speaker","p":"phr.","d":"a peer who mastered a language inside early childhood.","c":"母語使用者","s":"Even though she is not a native speaker, her English pronunciation is so clear that most people assume she grew up abroad.","t":"儘管她不是母語使用者，但她的英語發音如此清晰，大多數人都以為她是在國外長大的。"},{"w":"weaken","p":"v.","d":"to make something less strong, firm, or powerful.","c":"使變弱、削弱","s":"Months of inactivity during recovery began to weaken her muscles, so the doctor recommended gentle physiotherapy.","t":"康復期間數個月的不活動開始削弱她的肌肉，因此醫生建議進行溫和的物理治療。"},{"w":"strength","p":"n.","d":"the physical power or durability of an object.","c":"力量、優勢","s":"It takes both physical strength and mental endurance to complete a marathon, especially in hot and humid weather.","t":"完成馬拉松需要體力和精神耐力，尤其是在炎熱潮濕的天氣中。"},{"w":"strengthen","p":"v.","d":"to build up structures to withstand massive impact.","c":"加強、鞏固","s":"Regular practice in speaking English will gradually strengthen your confidence and help you communicate more fluently.","t":"定期練習英語口語將逐漸鞏固你的自信心，幫助你更流利地溝通。"},{"w":"eliminate","p":"v.","d":"to completely remove or get rid of a baseline issue.","c":"消除、淘汰、移除","s":"The new filtration system was designed to eliminate harmful bacteria from the drinking water supply across the entire city.","t":"新的過濾系統旨在消除整個城市飲用水供應中的有害細菌。"},{"w":"elimination","p":"n.","d":"the complete removal or dropping of low entries.","c":"消除、淘汰","s":"The elimination of plastic straws from the restaurant menu was welcomed by environmental groups who praised the decision.","t":"從餐廳菜單中淘汰塑膠吸管受到了環保團體的歡迎，他們對這個決定給予讚揚。"},{"w":"eliminate bad smell","p":"phr.","d":"using charcoal packs to filter out generic room odors.","c":"消除異味","s":"She placed a bowl of baking soda in the fridge to help eliminate bad smell that had built up over several weeks.","t":"她在冰箱裡放了一碗小蘇打，幫助消除數週來積累的異味。"},{"w":"population","p":"n.","d":"the total number of people living in a country or town.","c":"人口（數量）","s":"The city's population has grown rapidly over the past decade as more young people move there in search of better jobs.","t":"過去十年來，隨著越來越多的年輕人搬到那裡尋求更好的工作，這座城市的人口迅速增長。"},{"w":"populate","p":"v.","d":"to move citizens into an area to live there.","c":"居住於、移民於","s":"Early settlers began to populate the coastal region centuries ago, building fishing villages that still exist today.","t":"早期定居者數百年前開始在沿海地區定居，建立了至今仍然存在的漁村。"},{"w":"dense population","p":"phr.","d":"a tiny city containing massive masses of residents.","c":"人口稠密","s":"Areas with a dense population tend to have higher demand for public transport, schools, and healthcare facilities.","t":"人口稠密的地區往往對公共交通、學校和醫療設施有更高的需求。"},{"w":"population explosion","p":"phr.","d":"a massive sudden spike in global human birth rates.","c":"人口激增","s":"The population explosion of the twentieth century put enormous pressure on natural resources, farmland, and urban infrastructure.","t":"二十世紀的人口激增對自然資源、農地和城市基礎設施造成了巨大壓力。"},{"w":"domestic","p":"adj.","d":"relating to the home, household, or family circle.","c":"家庭的、家務的","s":"She shared domestic responsibilities equally with her partner, taking turns cooking, cleaning, and looking after the children.","t":"她與伴侶平等分擔家務責任，輪流做飯、打掃和照顧孩子。"},{"w":"domestic","p":"adj.","d":"inside one's own country; not foreign international.","c":"國內的","s":"The airline increased the number of domestic flights to meet growing demand from travellers during the summer holiday season.","t":"這家航空公司增加了國內航班的數量，以滿足暑假旅行旺季不斷增長的旅客需求。"},{"w":"domestic","p":"adj.","d":"describing an animal kept on a farm or as a pet.","c":"馴養的、家養的","s":"Domestic animals such as dogs and cats have lived alongside humans for thousands of years and depend on people for care.","t":"狗和貓等馴養動物與人類共同生活了數千年，依賴人類照料。"},{"w":"domestic flights","p":"phr.","d":"airplane routes tracking transits within single borders.","c":"國內航班","s":"Domestic flights in Taiwan are very convenient and can get you from Taipei to Kaohsiung in just under an hour.","t":"台灣的國內航班非常方便，可以在不到一小時內將你從台北帶到高雄。"},{"w":"domestic violence","p":"phr.","d":"physical harm committed within a household setup.","c":"家暴、家庭暴力","s":"Hotlines for victims of domestic violence are available around the clock, providing confidential support and safety advice.","t":"家暴受害者的熱線全天候開放，提供保密的支持和安全建議。"},{"w":"introduce","p":"v.","d":"to present a person by name to another team.","c":"介紹","s":"The teacher asked each student to stand up and introduce themselves to the class on the first day of the new semester.","t":"老師要求每位學生在新學期第一天站起來向全班介紹自己。"},{"w":"introduce","p":"v.","d":"to bring a new plant line or idea into a region first.","c":"引進、傳入","s":"The government decided to introduce a new recycling programme that would reward households for sorting their waste correctly.","t":"政府決定引進一項新的回收計劃，獎勵正確分類垃圾的家庭。"},{"w":"introduction","p":"n.","d":"the starting chapter of an educational book item.","c":"介紹、引進、導論","s":"The introduction of the textbook provides a clear overview of the key topics students will study throughout the entire course.","t":"教科書的導論提供了學生在整個課程中將學習的關鍵主題的清晰概述。"},{"w":"settler","p":"n.","d":"a person who arrives in a new region to build homes.","c":"移居者、開拓者","s":"The early settlers faced incredibly harsh conditions, but they built communities that eventually became thriving towns.","t":"早期移居者面臨極其惡劣的條件，但他們建立了最終成為繁榮城鎮的社區。"},{"w":"settle","p":"v.","d":"to arrange a baseline deal or end an argument.","c":"解決、定居","s":"Both sides finally agreed to settle the dispute out of court, saving time and avoiding a lengthy legal battle.","t":"雙方最終同意庭外解決爭議，節省了時間並避免了漫長的法律訴訟。"},{"w":"settle down","p":"phr.","d":"to marry, buy a house, and stop traveling around.","c":"定居下來、安頓下來","s":"After years of travelling and working abroad, he finally decided to settle down and start a family in his hometown.","t":"在多年旅行和在國外工作之後，他終於決定定居下來，在家鄉建立家庭。"},{"w":"desperate","p":"adj.","d":"feeling a severe, hopeless need for an entry asset.","c":"絕望的、極其渴望的","s":"The family was desperate for financial help after the father lost his job and the bills began piling up rapidly.","t":"在父親失業、帳單開始迅速積累後，這家人迫切需要財務幫助。"},{"w":"desperate for help","p":"phr.","d":"crying out with zero safety options remaining.","c":"急需幫助的","s":"The injured hiker was desperate for help and sent an emergency signal from his watch when his phone battery died.","t":"受傷的登山者急需幫助，在手機電量耗盡後從手錶發送了緊急信號。"},{"w":"desperately","p":"adv.","d":"in an extreme, intense, or dangerous manner.","c":"絕望地、極其、拼命地","s":"She desperately wanted to pass the entrance exam, so she studied for twelve hours a day during the final two weeks.","t":"她極其渴望通過入學考試，因此在最後兩週每天學習十二個小時。"},{"w":"desperation","p":"n.","d":"a baseline state of panic driven by zero options.","c":"絕望、孤注一擲","s":"In a moment of desperation, he called an old friend he had not spoken to in years and asked for a small loan.","t":"在絕望之際，他打電話給一位多年未聯繫的老朋友，請求借一小筆錢。"},{"w":"get rid of","p":"phr.","d":"to throw away, destroy, or clear out useless items.","c":"除掉、擺脫、扔掉","s":"She decided to get rid of all the old clothes in her wardrobe and donate them to a local charity shop.","t":"她決定清除衣櫃裡所有舊衣服，並將它們捐給當地的慈善商店。"},{"w":"altogether","p":"adv.","d":"completely, entirely, or considering everything.","c":"完全地、總共、毫無疑問","s":"The meeting was cancelled altogether because the main speaker missed her connecting flight and could not arrive in time.","t":"會議被完全取消，因為主要演講者錯過了轉機航班，無法準時到達。"},{"w":"cattle","p":"n.","d":"cows, bulls, or oxen kept on farm fields for milk.","c":"牛群（總稱，複數）","s":"The farmer moved the cattle to a new field every few weeks to ensure they always had enough fresh grass to graze on.","t":"農夫每隔幾週就將牛群移到新的田地，以確保牠們始終有足夠的新鮮草可以吃。"},{"w":"feed the cattle","p":"phr.","d":"passing grain blocks to livestock inside farm pens.","c":"餵牛","s":"He woke up before sunrise every morning to feed the cattle and check that all the animals were healthy.","t":"他每天日出前就起床，去餵牛並檢查所有動物是否健康。"},{"w":"bull","p":"n.","d":"an adult male cattle unit tracking zero milk output.","c":"公牛","s":"The farmer kept one large bull in a separate pen to prevent it from becoming aggressive towards the other animals.","t":"農夫將一頭大公牛關在單獨的圍欄裡，以防止它對其他動物產生攻擊性。"},{"w":"cow","p":"n.","d":"an adult female cattle unit optimized for dairy.","c":"母牛","s":"Each cow on the farm is milked twice a day, and the fresh milk is collected and sent to the local dairy factory.","t":"農場上的每頭母牛每天被擠奶兩次，新鮮牛奶被收集並送往當地的乳製品工廠。"},{"w":"ox","p":"n.","d":"a massive castrated male cattle used for heavy pull.","c":"公牛、工作牛","s":"Before modern machinery, farmers relied on the ox to pull heavy ploughs through the hard soil of the fields.","t":"在現代機械出現之前，農夫依靠工作牛拉動沉重的犁穿過田地的堅硬土壤。"},{"w":"seriously","p":"adv.","d":"in a careful, severe, or truthful manner.","c":"嚴肅地、認真地、嚴重地","s":"He was seriously injured in the accident and had to spend three weeks in hospital before he was well enough to go home.","t":"他在事故中嚴重受傷，必須在醫院待三週才足夠康復可以回家。"},{"w":"serious","p":"adj.","d":"tracking zero jokes; critical or dangerous state.","c":"認真的、嚴重的","s":"The doctor warned that the infection was serious and that the patient needed to start treatment immediately without delay.","t":"醫生警告說感染情況嚴重，患者需要立即開始治療，不得拖延。"},{"w":"take something seriously","p":"phr.","d":"to treat a class project with extreme professional focus.","c":"認真對待某事","s":"Students who take seriously their study habits in the first year usually perform much better in final examinations.","t":"在第一年認真對待學習習慣的學生通常在期末考試中表現好得多。"},{"w":"positive","p":"adj.","d":"hopeful, constructive, or tracking high true values.","c":"積極的、正面的、陽性的","s":"The doctor gave them positive news after the test results came back, saying there were no signs of the disease spreading.","t":"在測試結果出來後，醫生給了他們積極的消息，說沒有疾病擴散的跡象。"},{"w":"positive influence","p":"phr.","d":"a model companion who drives you to study hard.","c":"正面影響","s":"Her older sister has been a huge positive influence in her life, encouraging her to work hard and never give up.","t":"她的姐姐對她的生活產生了巨大的正面影響，鼓勵她努力工作，永不放棄。"},{"w":"negative","p":"adj.","d":"tracking zero hope; destructive or critical lines.","c":"消極的、負面的、陰性的","s":"He tried hard not to let the negative comments on social media affect his confidence or his enjoyment of his work.","t":"他努力不讓社群媒體上的負面評論影響他的自信心或他對工作的熱情。"},{"w":"increase","p":"v.","d":"to make or become larger in size, value, or count.","c":"增加、增長","s":"The school decided to increase the number of English lessons per week after exam results showed students needed more practice.","t":"在考試成績顯示學生需要更多練習後，學校決定增加每週英語課的數量。"},{"w":"increase","p":"n.","d":"a rise or growth in value, scale, or metrics counts.","c":"增加、增長","s":"There has been a significant increase in the number of people choosing to cycle to work since the new bike lanes opened.","t":"自從新的自行車道開通以來，選擇騎自行車上班的人數大幅增加。"},{"w":"increase taxes","p":"phr.","d":"a legislative move raising corporate fee rules.","c":"提高稅收","s":"The government announced plans to increase taxes on luxury goods in order to fund new public hospitals and schools.","t":"政府宣布計劃提高對奢侈品的稅收，以資助新的公立醫院和學校。"},{"w":"decrease","p":"v.","d":"to shrink down or fall in baseline totals.","c":"減少、降低","s":"The number of students absent from school began to decrease after the new health and hygiene campaign was launched.","t":"在新的健康衛生運動推出後，缺課的學生人數開始減少。"},{"w":"increasingly","p":"adv.","d":"more and more over a continuous duration timeline.","c":"漸增地、越來越…","s":"It is becoming increasingly difficult to find affordable housing in the city as more people move there for work each year.","t":"隨著每年越來越多的人搬到城市工作，在城市找到負擔得起的住房變得越來越困難。"},{"w":"add","p":"v.","d":"to put elements together to calculate a grand total.","c":"增加、加、補充說","s":"She decided to add a pinch of chili to the soup to give it a little extra heat without making it too spicy.","t":"她決定在湯裡加一點辣椒，給它增添一點熱度，但不要讓它太辣。"},{"w":"plus","p":"n.","d":"added to; an extra advantage token in a review.","c":"加、加上、好處","s":"The apartment comes fully furnished, plus it is located just five minutes from the nearest train station.","t":"這間公寓提供全套家具，加上它距離最近的火車站只有五分鐘路程。"},{"w":"project","p":"n.","d":"a carefully planned piece of work or research task.","c":"計畫、專案、項目","s":"The students worked in groups of four to complete a science project that involved designing a small working model bridge.","t":"學生們以四人為一組完成一個科學專案，涉及設計一個小型工作模型橋樑。"},{"w":"project","p":"v.","d":"to estimate or calculate a future trend metric line.","c":"預測、推測","s":"Analysts projected that the company's profits would double within three years if the new product line performed well.","t":"分析師預測，如果新產品線表現良好，公司的利潤將在三年內翻倍。"},{"w":"projector","p":"n.","d":"an optical machine displaying slides onto walls.","c":"投影機","s":"The teacher connected her laptop to the projector and displayed the vocabulary list so everyone in the class could see.","t":"老師將筆記型電腦連接到投影機，顯示詞彙表，讓班上每個人都能看到。"},{"w":"current","p":"adj.","d":"happening or existing right now in the present era.","c":"現在的、當前的","s":"The current situation in the housing market makes it very difficult for young people to buy their first home.","t":"當前的房市狀況使年輕人很難購買他們的第一套住房。"},{"w":"current","p":"n.","d":"a continuous moving stream of ocean water or air.","c":"水流、氣流、電流","s":"The swimmer was caught in a strong underwater current that pulled her away from the shore faster than she could swim back.","t":"游泳者被一股強大的水下水流捲走，速度比她游回岸邊的速度還要快。"},{"w":"current job","p":"phr.","d":"the explicit firm you currently draw wages from.","c":"目前的工作","s":"Although she enjoys her current job, she is considering applying for a position at a larger company with better pay.","t":"儘管她喜歡目前的工作，但她正在考慮申請一家薪資更好的大公司的職位。"},{"w":"currently","p":"adv.","d":"at the present time; right now cleanly.","c":"目前、當前","s":"The library is currently closed for renovation but will reopen to the public at the start of next month.","t":"圖書館目前因裝修而關閉，但將於下個月初重新對公眾開放。"},{"w":"retirement","p":"n.","d":"the period after you stop working completely due to age.","c":"退休（生活）","s":"She planned to spend her retirement travelling the world and learning new skills she never had time for while working.","t":"她計劃在退休後環遊世界，學習工作時從來沒有時間學習的新技能。"},{"w":"retire","p":"v.","d":"to officially drop your corporate role at age 65.","c":"退休","s":"After forty years of teaching, the beloved professor finally decided to retire and was given a grand farewell party.","t":"在執教四十年後，這位備受愛戴的教授終於決定退休，並獲得了盛大的告別派對。"},{"w":"retired","p":"adj.","d":"describing an old expert who no longer works jobs.","c":"退休的","s":"The retired engineer still volunteers his expertise to help young students with their science and robotics projects.","t":"這位退休工程師仍然自願貢獻他的專業知識，幫助年輕學生完成科學和機器人項目。"},{"w":"acquire","p":"v.","d":"to obtain, buy, or master a new skill asset over time.","c":"獲得、取得、學得","s":"Living abroad for two years helped her acquire a much deeper understanding of the local culture and way of life.","t":"在國外生活兩年幫助她對當地文化和生活方式有了更深入的了解。"},{"w":"acquire an accent","p":"phr.","d":"naturally picking up a local tone after living there.","c":"染上…口音","s":"After spending three years in Ireland, he began to acquire an accent without even realising it was happening.","t":"在愛爾蘭待了三年後，他開始不知不覺地染上了當地口音。"},{"w":"acquirement","p":"n.","d":"a personal skill or asset gained through steady work.","c":"取得、學得、才藝","s":"The acquirement of a second language is one of the most valuable investments you can make in your personal development.","t":"學得第二語言是你在個人發展中所能做的最有價值的投資之一。"},{"w":"endangered","p":"adj.","d":"tracking a high risk of dying out completely soon.","c":"瀕臨絕滅的","s":"The wildlife reserve was set up to protect several endangered bird species that nest exclusively in this coastal wetland.","t":"這個野生動物保護區的設立是為了保護幾種專門在這片沿海濕地築巢的瀕危鳥類。"},{"w":"endangered species","p":"phr.","d":"animal groups flagged with critical survival rates.","c":"瀕危物種","s":"The new law bans the trade of products made from endangered species, including ivory, certain furs, and rare bird feathers.","t":"新法律禁止交易由瀕危物種製成的產品，包括象牙、某些毛皮和稀有鳥類羽毛。"}]},{"unit":12,"theme":"enthusiasm – make a difference","cards":[{"w":"enthusiasm","p":"n.","d":"a feeling of energetic interest or excitement for a task.","c":"熱情、熱忱","s":"Her enthusiasm for science was obvious from the way she asked questions and stayed after class to do extra experiments.","t":"她對科學的熱情從她提問的方式和課後留下來做額外實驗的行為中顯而易見。"},{"w":"enthusiastic","p":"adj.","d":"showing high excitement or eager interest in an event.","c":"熱情的、熱心的","s":"The crowd was incredibly enthusiastic during the concert, singing along to every song and cheering after each performance.","t":"音樂會期間，人群非常熱情，跟著每首歌一起唱，並在每次表演後歡呼喝彩。"},{"w":"tradition","p":"n.","d":"a custom or belief passed down across generations.","c":"傳統","s":"It is a family tradition to gather at the grandparents' house every Lunar New Year and share a big meal together.","t":"每逢農曆新年，全家聚集在祖父母家共享豐盛大餐是一個家庭傳統。"},{"w":"traditional","p":"adj.","d":"tracking old family baseline customs rather than new styles.","c":"傳統的","s":"The museum displayed traditional costumes from different Aboriginal tribes, each with its own unique patterns and colours.","t":"博物館展示了來自不同原住民部落的傳統服飾，每件都有其獨特的圖案和色彩。"},{"w":"unique","p":"adj.","d":"being the only one of its kind; highly unusual special.","c":"獨一無二的、獨特的","s":"Every snowflake has a unique pattern, meaning no two snowflakes in the world are ever exactly the same shape.","t":"每片雪花都有獨一無二的圖案，這意味著世界上沒有兩片雪花的形狀完全相同。"},{"w":"honor","p":"v.","d":"to show immense public respect or reward an expert.","c":"向…致敬、給予榮譽","s":"The community gathered to honor the retiring teacher with a special ceremony and a heartfelt thank-you card from students.","t":"社區聚集在一起，用特別儀式和學生們誠摯的感謝卡向即將退休的老師致敬。"},{"w":"honor","p":"n.","d":"high respect, reputation, or an award token entry.","c":"榮譽、光榮、誠實","s":"It is a great honor to be selected as the student representative to speak at the school's graduation ceremony.","t":"被選為學生代表在學校畢業典禮上發言是一份極大的榮譽。"},{"w":"in honor of","p":"phr.","d":"dedicated directly to reward a historic pioneer agent.","c":"為了紀念…、向…致敬","s":"A new park was named in honor of the scientist who discovered the cure that saved millions of lives worldwide.","t":"一座新公園以那位發現了拯救全球數百萬生命療法的科學家的名字命名，以紀念他。"},{"w":"honorable","p":"adj.","d":"tracking high moral standards; worthy of respect.","c":"可敬的、高尚的","s":"The soldier was praised for his honorable conduct during the mission and was awarded a medal for exceptional bravery.","t":"這位士兵因在任務中的高尚行為而受到表彰，並獲得了一枚英勇勛章。"},{"w":"fortune","p":"n.","d":"random chance or good luck impacting an individual.","c":"運氣、機運","s":"It was his fortune to be in the right place at the right time when the famous director was looking for a young actor.","t":"當著名導演在尋找年輕演員時，他恰好在正確的時間出現在正確的地方，這是他的運氣。"},{"w":"fortune","p":"n.","d":"a massive bundle of money, gold, or property assets.","c":"大筆財富","s":"She invested her savings wisely and managed to build a small fortune over thirty years by living modestly and saving regularly.","t":"她明智地投資了她的積蓄，通過節儉生活和定期儲蓄，在三十年內積累了一筆小財富。"},{"w":"make a fortune by","p":"phr.","d":"to successfully pile up millions via unique trade lines.","c":"靠…發大財","s":"He managed to make a fortune by selling handmade furniture online during the pandemic when demand suddenly increased.","t":"他在疫情期間需求突然增加時，靠在網上銷售手工家具成功發了大財。"},{"w":"misfortune","p":"n.","d":"a streak of terrible events or bad luck accidents.","c":"不幸、厄運","s":"Despite facing great misfortune in his early life, he never lost his optimism and eventually built a very successful career.","t":"儘管早年遭受了巨大的不幸，他從未失去樂觀精神，最終建立了非常成功的事業。"},{"w":"fortunate","p":"adj.","d":"lucky; tracking exceptional baseline outcomes.","c":"幸運的","s":"We were very fortunate that the typhoon changed direction at the last moment and did not cause serious damage to the city.","t":"我們非常幸運，颱風在最後一刻改變了方向，沒有對這座城市造成嚴重損害。"},{"w":"unfortunate","p":"adj.","d":"unlucky; hit by unexpected operational failures.","c":"不幸的","s":"It was very unfortunate that the main speaker fell ill the night before the conference and was unable to attend at all.","t":"主要演講者在會議前一晚生病，完全無法出席，這真的很不幸。"},{"w":"single","p":"adj.","d":"only one; separate; not married or combined.","c":"單一的、單身的","s":"She read every single page of the contract carefully before signing it to make sure she understood all the terms.","t":"她在簽署合約之前仔細閱讀了每一頁，確保她理解所有條款。"},{"w":"not a single","p":"phr.","d":"absolutely zero units matching a specific description.","c":"連一個也（沒有）","s":"After the storm, not a single tree in the orchard was left standing — the wind had knocked them all down overnight.","t":"暴風雨過後，果園裡連一棵樹都沒有剩下——風在一夜之間將它們全部吹倒了。"},{"w":"represent","p":"v.","d":"to speak or act officially on behalf of a team.","c":"代表、代理","s":"She was chosen to represent her school at the national debate competition and worked hard to prepare her arguments.","t":"她被選中代表學校參加全國辯論比賽，並努力準備她的論點。"},{"w":"represent","p":"v.","d":"to stand as a clear graphical sign or symbol for a concept.","c":"象徵、表示","s":"The dove has long been used to represent peace, and it appears on flags, artwork, and monuments around the world.","t":"鴿子長期以來被用來象徵和平，它出現在世界各地的旗幟、藝術品和紀念碑上。"},{"w":"representation","p":"n.","d":"the act of standing in for a major public body.","c":"代表、表現、描繪","s":"Many people feel that women's representation in leadership roles has improved significantly over the past twenty years.","t":"許多人認為女性在領導角色中的代表性在過去二十年中已顯著提升。"},{"w":"representative","p":"n.","d":"an agent picked to state opinions for a corporate base.","c":"代表、代理人","s":"A representative from the student council attended the school board meeting to share feedback about the new lunch menu.","t":"學生會的一名代表出席了學校董事會會議，分享有關新午餐菜單的意見。"},{"w":"wealth","p":"n.","d":"a large amount of money, land, or valuable goods.","c":"財富、富有","s":"The country's natural wealth includes vast forests, mineral deposits, and fertile farmland that support millions of people.","t":"這個國家的自然財富包括廣闊的森林、礦藏和肥沃的農地，養活了數百萬人。"},{"w":"wealthy","p":"adj.","d":"rich; holding deep capital reserves and assets.","c":"富裕的、有錢的","s":"Even though his family was not wealthy, he received a full scholarship and was able to attend one of the top universities.","t":"儘管他的家庭並不富裕，但他獲得了全額獎學金，能夠就讀頂尖大學之一。"},{"w":"whoever","p":"n.","d":"any person who; no matter who performs the task.","c":"無論誰、任何人","s":"Whoever finishes the assignment first can use the remaining class time to read freely or work on their own projects.","t":"無論誰先完成作業，都可以用剩餘的課堂時間自由閱讀或進行自己的項目。"},{"w":"whomever","p":"n.","d":"any person who receives an action (object role).","c":"無論誰（受格）","s":"The manager said she would give the promotion to whomever demonstrated the most initiative and dedication over the year.","t":"經理說她會將晉升機會給予這一年中表現出最多主動性和奉獻精神的任何人。"},{"w":"whatever","p":"n.","d":"anything or everything that plays out in a zone.","c":"無論什麼","s":"Whatever decision you make, make sure you have thought it through carefully and considered all the possible consequences.","t":"無論你做什麼決定，確保你已仔細考慮並考量了所有可能的後果。"},{"w":"whichever","p":"n.","d":"picking any unit cleanly out of a narrow set group.","c":"無論哪個","s":"You can order whichever dish you like from the menu, as tonight's dinner is being paid for by the company.","t":"你可以從菜單上點任何你喜歡的菜，因為今晚的晚餐由公司買單。"},{"w":"reward","p":"n.","d":"an item or cash given to thank someone for good work.","c":"報酬、獎賞","s":"The company offered a generous reward to anyone who could provide useful information leading to the recovery of the stolen data.","t":"公司向任何能提供有助於追回被盜數據的有用資訊的人提供豐厚的獎賞。"},{"w":"reward","p":"v.","d":"to give someone a token to thank them for help tasks.","c":"獎賞、回報","s":"The school rewarded students who showed consistent improvement with a special certificate at the end of each term.","t":"學校在每學期末用特別證書獎賞那些持續進步的學生。"},{"w":"reward with","p":"phr.","d":"gifting an explicit asset item to praise top metrics.","c":"用…來獎勵","s":"The manager decided to reward with a full day off and a catered lunch together.","t":"經理決定用一整天假期和一頓外燴午餐來獎勵表現最佳的團隊。"},{"w":"promise","p":"n.","d":"an explicit statement that you will definitely do a task.","c":"承諾、諾言","s":"She kept her promise to her younger brother and attended every one of his football matches throughout the entire season.","t":"她遵守了對弟弟的諾言，整個賽季出席了他的每一場足球比賽。"},{"w":"promise","p":"n.","d":"a clear sign of future success or high talent traits.","c":"（前途）希望、潛力","s":"The young musician showed great promise at such an early age that she was offered a place in the national youth orchestra.","t":"這位年輕音樂家在如此早的年齡就展現出巨大的潛力，以至於她獲得了加入國家青年管弦樂團的機會。"},{"w":"promise","p":"v.","d":"to state firmly that you will deliver an item target.","c":"答應、承諾","s":"He promised to help his classmate prepare for the exam and spent every evening that week reviewing difficult topics together.","t":"他答應幫助同學準備考試，那週每天晚上都和他一起複習困難的主題。"},{"w":"keep a promise","p":"phr.","d":"executing a duty exactly as stated across old talks.","c":"守信、履行諾言","s":"It is important to only make commitments you can realistically fulfil, because failing to keep a promise damages trust.","t":"只做你實際上能履行的承諾非常重要，因為無法守信會破壞信任。"},{"w":"full of promise","p":"phr.","d":"showcasing exceptional baseline potential to win fields.","c":"很有前途的、大有可為的","s":"The young athlete is full of promise and coaches believe she could become a world champion within the next five years.","t":"這位年輕運動員很有前途，教練們相信她在未來五年內可能成為世界冠軍。"},{"w":"promising","p":"adj.","d":"showing signs of future success or fine performance.","c":"有前途的、有希望的","s":"The research results are very promising and suggest that the new vaccine could be ready for clinical trials by next year.","t":"研究結果非常有希望，表明新疫苗可能在明年準備好進行臨床試驗。"},{"w":"delighted","p":"adj.","d":"incredibly happy and pleased about an outcome event.","c":"感到高興的、滿心歡喜的","s":"She was absolutely delighted when she found out she had passed all her exams with top marks and would receive a scholarship.","t":"當她得知自己以最高分通過了所有考試並將獲得獎學金時，她感到無比高興。"},{"w":"be delighted to","p":"phr.","d":"happily welcoming an opportunity to complete an action.","c":"很榮幸去…、很高興去…","s":"We are delighted to announce that this year's award for best new teacher goes to Ms Chen from the science department.","t":"我們很榮幸地宣布，今年最佳新教師獎授予科學部門的陳老師。"},{"w":"delightful","p":"adj.","d":"causing a huge wave of pleasure; highly charming.","c":"令人愉快的、討人喜歡的","s":"The children put on a truly delightful performance at the year-end concert that brought smiles to every parent in the audience.","t":"孩子們在年終音樂會上呈現了一場真正令人愉快的表演，讓觀眾席上的每位家長都面帶笑容。"},{"w":"delight","p":"v.","d":"a source of joy or to give massive amusement to peers.","c":"欣喜、使高興","s":"Watching the puppies play together was a pure delight, and everyone who saw them immediately felt happier and more relaxed.","t":"看著小狗們一起玩耍是純粹的欣喜，每個看到牠們的人都立刻感到更快樂、更放鬆。"},{"w":"approach","p":"v.","d":"to move closer to a place, time, or numerical metric.","c":"接近、靠近","s":"As the exam date began to approach, she increased her daily study time and started reviewing all her notes from the year.","t":"隨著考試日期的臨近，她增加了每日學習時間，並開始複習一整年的所有筆記。"},{"w":"approach","p":"n.","d":"a specific method or way of handling a complex problem.","c":"方法、途徑","s":"The teacher used a very creative approach to explain grammar rules, making the lessons fun and easy to remember.","t":"老師用一種非常有創意的方法來解釋語法規則，讓課程變得有趣且容易記憶。"},{"w":"approachable","p":"adj.","d":"friendly and incredibly easy to talk to in person.","c":"親切的、易接近的","s":"The new headmaster is very approachable, and students feel comfortable going to his office whenever they need guidance.","t":"新校長非常親切易接近，學生們在需要指導時很自在地去他的辦公室。"},{"w":"symbol","p":"n.","d":"a visual shape or sign that represents an idea concept.","c":"象徵、符號","s":"The red cross is an internationally recognised symbol of medical aid and emergency assistance across the world.","t":"紅十字是全球公認的醫療援助和緊急救助象徵。"},{"w":"symbolic","p":"adj.","d":"serving as an expression or sign of an invisible value.","c":"象徵性的","s":"Planting a tree together at the start of the school year has become a symbolic gesture representing growth and learning.","t":"在學年開始時一起種樹已成為一種象徵成長與學習的象徵性姿態。"},{"w":"symbolize","p":"v.","d":"to stand as a clear baseline indicator for an aura theme.","c":"象徵","s":"The white flag has long been used to symbolize surrender or a request for a ceasefire on the battlefield.","t":"白旗長期以來被用來象徵在戰場上的投降或停火請求。"},{"w":"plentiful","p":"adj.","d":"existing in very large amounts; more than enough.","c":"豐富的、充足的","s":"Food was plentiful at the harvest festival, with long tables covered in freshly grown vegetables, fruits, and homemade dishes.","t":"豐收節的食物非常豐富，長桌上擺滿了新鮮種植的蔬菜、水果和自製菜餚。"},{"w":"plenty","p":"n.","d":"a massive count of units ensuring zero scarcity flaws.","c":"豐富、充足、大量","s":"There is plenty of time before the deadline, so take a short break and come back to the assignment feeling refreshed.","t":"截止日期前還有大量時間，所以休息一下，精神煥發地回來繼續完成作業。"},{"w":"historical","p":"adj.","d":"connected with studying or recording human past eras.","c":"歷史的、史學的","s":"The historical records found in the archive provided new evidence that changed how scholars understood the ancient trade route.","t":"在檔案館中發現的歷史記錄提供了新的證據，改變了學者對古代貿易路線的理解。"},{"w":"historical novel","p":"phr.","d":"a fictional book built directly over real past timelines.","c":"歷史小說","s":"She spent two years researching before writing the historical novel, ensuring every detail about the era was accurate.","t":"她在寫這部歷史小說之前花了兩年時間進行研究，確保每個關於那個時代的細節都是準確的。"},{"w":"historic","p":"adj.","d":"highly important or famous in human history records.","c":"具歷史意義的、著名的","s":"The signing of the peace agreement was a truly historic moment that brought an end to decades of conflict in the region.","t":"和平協議的簽署是一個真正具有歷史意義的時刻，結束了該地區數十年的衝突。"},{"w":"female","p":"adj.","d":"relating to the sex that can lay eggs or give birth.","c":"女性的、雌性的","s":"The wildlife researcher studied the behaviour of female lions and found that they do most of the hunting for the pride.","t":"野生動物研究員研究了雌獅的行為，發現牠們為獅群完成了大部分的狩獵工作。"},{"w":"female","p":"n.","d":"a female person, animal, or wild plant organism unit.","c":"女性、雌性動植物","s":"The study found that females in the programme were significantly more likely to complete their degree within four years.","t":"研究發現，參與該計劃的女性在四年內完成學位的可能性顯著更高。"},{"w":"male","p":"adj.","d":"relating to the sex that fertilizes eggs outputs.","c":"男性的、雄性的","s":"The male penguin takes turns with his partner to keep the egg warm during the bitterly cold Antarctic winter months.","t":"雄企鵝在嚴寒的南極冬季與伴侶輪流保持蛋的溫暖。"},{"w":"dive","p":"v.","d":"to jump headfirst into deep water channels.","c":"跳水、潛水、俯衝","s":"The young swimmer learned to dive from the three-metre board after weeks of practice with her coach at the pool.","t":"這位年輕游泳選手在教練的指導下經過數週練習，學會了從三公尺跳板跳水。"},{"w":"scuba dive","p":"phr.","d":"exploring deep ocean zones using oxygen gas packs.","c":"水肺潛水","s":"They decided to scuba dive in the coral reef area to see the colourful fish and marine life up close.","t":"他們決定在珊瑚礁區域水肺潛水，近距離觀看色彩繽紛的魚類和海洋生物。"},{"w":"scuba diving","p":"n.","d":"the active leisure sport of underwater traversal.","c":"水肺潛水（名詞）","s":"Scuba diving is a popular activity in southern Taiwan, where the warm clear water is home to beautiful coral reefs.","t":"水肺潛水在台灣南部是一項受歡迎的活動，那裡溫暖清澈的海水是美麗珊瑚礁的家園。"},{"w":"freezing","p":"adj.","d":"extremely cold; at or below the temperature water turns to ice.","c":"極冷的、冰凍的","s":"The mountain summit was absolutely freezing when they reached it, and they immediately put on every layer of clothing they had.","t":"當他們到達山頂時，天氣極度寒冷，他們立刻穿上了所有帶來的衣物。"},{"w":"freeze","p":"v.","d":"to turn into ice via extreme exposure to cold winds.","c":"結冰、冷凍、凍結","s":"The pond began to freeze overnight as temperatures dropped well below zero, and children could skate on it by morning.","t":"隨著氣溫大幅降至零度以下，池塘在一夜之間開始結冰，到早上孩子們就能在上面溜冰了。"},{"w":"frozen food","p":"phr.","d":"factory meals kept solid inside cold room racks.","c":"冷凍食品","s":"She keeps a stock of frozen food in the freezer for busy weeknights when there is no time to cook from scratch.","t":"她在冰箱裡存放了一些冷凍食品，供繁忙的工作日晚上沒有時間從頭烹飪時使用。"},{"w":"similar","p":"adj.","d":"sharing matching features but not completely identical.","c":"相似的、類似的","s":"The twins have very similar personalities, but one enjoys outdoor sports while the other prefers reading indoors.","t":"這對雙胞胎有非常相似的個性，但一個喜歡戶外運動，而另一個更喜歡在室內閱讀。"},{"w":"similarity","p":"n.","d":"a specific matching point shared between distinct items.","c":"相似處","s":"Despite growing up in different countries, the two friends discovered a surprising similarity in their childhood experiences.","t":"儘管在不同國家長大，這兩位朋友發現了他們童年經歷中令人驚訝的相似之處。"},{"w":"difference","p":"n.","d":"a point or way in which entities are not identical.","c":"相異之處、差別","s":"The difference between the two paintings is subtle — you have to look very closely at the brushwork to notice it.","t":"這兩幅畫之間的差別很微妙——你必須非常仔細地觀察筆觸才能注意到。"},{"w":"make a difference","p":"phr.","d":"to cause an impactful change on a status line tracker.","c":"產生影響、改善局勢","s":"Even donating just a small amount of money to a food bank can make a difference to a family struggling to eat.","t":"即使只向食物銀行捐贈少量金錢，也能對掙扎溫飽的家庭產生影響。"}]},{"unit":13,"theme":"magnificent – adulthood","cards":[{"w":"magnificent","p":"adj.","d":"extremely beautiful, elaborate, or impressive.","c":"壯麗的、宏偉的、極好的","s":"The view from the top of the mountain was absolutely magnificent, and no photograph could truly capture its beauty.","t":"山頂的景色絕對壯麗，沒有任何照片能真正捕捉到其美麗。"},{"w":"magnificence","p":"n.","d":"the quality of being grand, large, or beautiful.","c":"壯麗、宏偉、華麗","s":"Tourists were left speechless by the magnificence of the ancient palace, which had stood for over eight hundred years.","t":"遊客們被這座已矗立八百多年的古老宮殿的宏偉所震撼，說不出話來。"},{"w":"magnify","p":"v.","d":"to make something look larger than it really is.","c":"放大、誇大","s":"The microscope can magnify objects up to a thousand times, allowing scientists to study tiny cells in detail.","t":"顯微鏡能將物體放大多達一千倍，讓科學家能詳細研究微小細胞。"},{"w":"magnitude","p":"n.","d":"the great size, scale, or importance of something.","c":"巨大、重大、震級","s":"The magnitude of the earthquake surprised everyone — it measured 7.2 on the Richter scale and was felt across the region.","t":"這場地震的震級讓所有人感到驚訝——它在芮氏規模達7.2，整個地區都有震感。"},{"w":"mystery","p":"n.","d":"something strange that cannot be explained or understood.","c":"神秘的事物、謎","s":"The disappearance of the old lighthouse keeper remains a complete mystery that no one has been able to solve.","t":"老燈塔看守人的失蹤至今仍是一個完整的謎，沒有人能夠解開。"},{"w":"mysterious","p":"adj.","d":"strange, unknown, or difficult to understand.","c":"神秘的、不可思議的","s":"A mysterious package arrived at her door with no return address and no note explaining what it was or who sent it.","t":"一個神秘的包裹送到她門口，沒有回寄地址，也沒有說明它是什麼或是誰寄來的。"},{"w":"mysteriously","p":"adv.","d":"in a way that is strange or secret.","c":"神秘地、不可思議地","s":"The keys mysteriously vanished from the table overnight, and nobody in the house could explain where they had gone.","t":"鑰匙神秘地在一夜之間從桌上消失了，家裡沒有人能解釋它們去了哪裡。"},{"w":"unusual","p":"adj.","d":"different from what is normal or common; rare.","c":"不尋常的、獨特的","s":"It is quite unusual for it to snow in this part of Taiwan, so children were very excited when it happened last winter.","t":"在台灣這個地方下雪相當不尋常，所以去年冬天下雪時孩子們都非常興奮。"},{"w":"unusually","p":"adv.","d":"in a way that is modern, rare, or remarkable.","c":"異常地、非常","s":"The weather was unusually warm for January, and many people went to the beach to enjoy the sunshine.","t":"對一月來說天氣異常溫暖，許多人去海灘享受陽光。"},{"w":"usual","p":"adj.","d":"normal; happening in the regular way.","c":"通常的、慣常的","s":"She arrived at work earlier than usual because she had an important presentation to prepare before the morning meeting.","t":"她比平常更早到達公司，因為她需要在早上的會議前準備一個重要的簡報。"},{"w":"unexpected","p":"adj.","d":"surprising because you did not think it would happen.","c":"出乎意料的","s":"The unexpected visit from her old university friend made her day, and they stayed up talking until almost midnight.","t":"老大學朋友的出乎意料造訪讓她喜出望外，他們聊天聊到將近午夜。"},{"w":"existence","p":"n.","d":"the state of being real or living in the world.","c":"存在、生存","s":"The discovery of the ancient ruins provided the first solid proof of the civilisation's existence over two thousand years ago.","t":"這些古代遺跡的發現提供了兩千多年前該文明存在的第一個確鑿證明。"},{"w":"exist","p":"v.","d":"to be real; to live or be found in a place.","c":"存在、生存","s":"Some scientists believe that life may exist on other planets, but no solid proof has been found yet.","t":"一些科學家相信其他星球上可能存在生命，但目前尚未找到確切的證明。"},{"w":"existent","p":"adj.","d":"currently real or existing right now.","c":"現存的、存在的","s":"The committee reviewed all existent policies before deciding which ones needed to be updated or removed entirely.","t":"委員會審查了所有現存的政策，然後決定哪些需要更新或完全廢除。"},{"w":"coexistence","p":"n.","d":"living peacefully together at the same time.","c":"共存","s":"The nature reserve promotes the coexistence of different wildlife species by protecting their habitats from human activity.","t":"這個自然保護區通過保護各種野生動物的棲息地免受人類活動影響，促進不同物種的共存。"},{"w":"come into existence","p":"phr.","d":"to begin to be real or start being made.","c":"開始存在、成立","s":"The organization came into existence in 1998, when a group of volunteers decided to help homeless youth in the city.","t":"這個組織於1998年成立，當時一群義工決定幫助城市中無家可歸的青少年。"},{"w":"live a quiet existence","p":"phr.","d":"to spend your days in a peaceful, simple way.","c":"過著清靜的生活","s":"After retiring from the busy city, he chose to live a quiet existence in a small village near the mountains.","t":"從繁忙的城市退休後，他選擇在山區附近的一個小村莊過著清靜的生活。"},{"w":"curled","p":"adj.","d":"formed into a twisted, spiral, or curved shape.","c":"捲曲的","s":"The cat lay in a curled position at the end of the bed, fast asleep with its tail wrapped around its nose.","t":"貓蜷縮在床尾，熟睡著，尾巴繞在鼻子周圍。"},{"w":"curl","p":"v.","d":"to twist or bend into a curve or loop.","c":"使捲曲、蜷縮","s":"Her hair naturally tends to curl in humid weather, so she always keeps a small bottle of anti-frizz serum in her bag.","t":"在潮濕的天氣裡，她的頭髮自然地捲曲，所以她總是在包包裡放一小瓶防毛躁精華液。"},{"w":"curl up","p":"phr.","d":"to sit or lie with your arms and legs close to you.","c":"蜷縮、身體抱成團","s":"On cold winter evenings, she loves to curl up on the sofa with a warm blanket and a cup of hot cocoa.","t":"在寒冷的冬夜，她喜歡蜷縮在沙發上，裹著溫暖的毯子，喝著一杯熱可可。"},{"w":"tiny","p":"adj.","d":"extremely small in size, amount, or scale.","c":"極小的、微小的","s":"A tiny spider had built a beautiful web in the corner of the window, catching droplets of morning dew.","t":"一隻極小的蜘蛛在窗角織了一張美麗的網，捕捉著清晨的露珠。"},{"w":"micro","p":"adj.","d":"completely small; relating to electronic chips.","c":"微型的、微觀的","s":"The scientist used a micro camera to film the behaviour of insects underground without disturbing their natural habitat.","t":"科學家使用微型攝影機拍攝地下昆蟲的行為，而不打擾牠們的自然棲息地。"},{"w":"regularly","p":"adv.","d":"happening often or at the same time intervals.","c":"定期地、規律地、經常","s":"She visits her elderly grandmother regularly every Sunday afternoon and always brings fresh flowers from the market.","t":"她每週日下午定期拜訪年邁的祖母，總是從市場帶去新鮮的花朵。"},{"w":"regular","p":"adj.","d":"happening or done often; following a fixed pattern.","c":"規律的、定期的、普通的","s":"Getting enough sleep and having regular meals are two of the most important habits for maintaining good health.","t":"充足的睡眠和規律的飲食是保持良好健康最重要的兩個習慣。"},{"w":"regulate","p":"v.","d":"to control a process or speed with official rules.","c":"管制、調整、調節","s":"The government introduced new laws to regulate the use of social media platforms and protect users from harmful content.","t":"政府引入了新法律來管制社群媒體平台的使用，保護用戶免受有害內容的影響。"},{"w":"regulation","p":"n.","d":"an official rule made by a government or firm.","c":"規章、法規、管制","s":"The new food safety regulation requires all restaurants to display hygiene scores on their front door for customers to see.","t":"新的食品安全法規要求所有餐廳在前門展示衛生評分，供顧客查看。"},{"w":"direction","p":"n.","d":"the way or path along which something moves.","c":"方向、方位","s":"The wind changed direction suddenly during the race, which made it much harder for the sailors to control their boats.","t":"比賽中風向突然改變，讓水手們更難控制他們的船隻。"},{"w":"directions","p":"n.","d":"instructions on how to get to a place or do a job.","c":"指引、路線說明（常用複數）","s":"She asked a local shopkeeper for directions to the nearest bus stop because her phone had run out of battery.","t":"她的手機沒電了，於是向當地店主詢問前往最近公車站的路線說明。"},{"w":"direct","p":"adj.","d":"straight; going from point to point with no stops.","c":"直接的","s":"The most direct route to the airport takes only twenty minutes, but it involves paying a toll on the expressway.","t":"前往機場最直接的路線只需二十分鐘，但需要在高速公路上繳費。"},{"w":"direct","p":"v.","d":"to aim something at a target; to show the way.","c":"指引、導演、對準","s":"The police officer stood in the middle of the intersection to direct traffic after the traffic lights stopped working.","t":"在交通燈故障後，警察站在十字路口中間指揮交通。"},{"w":"directly","p":"adv.","d":"honestly; without any stops or delayed waiting.","c":"直接地、立刻","s":"After the concert, she went directly home without stopping anywhere because she had an early flight the next morning.","t":"音樂會結束後，她直接回家，沒有在任何地方停留，因為第二天早上有早班機。"},{"w":"director","p":"n.","d":"the manager of a company department or movie film.","c":"經理、主管、導演","s":"The film director spent three years developing the script before finally finding the right cast for each role.","t":"這位電影導演花了三年時間開發劇本，才最終為每個角色找到合適的演員。"},{"w":"balloon","p":"n.","d":"a small rubber bag that becomes large when filled with air.","c":"氣球","s":"The children decorated the room with colourful balloons and streamers to celebrate their friend's birthday party.","t":"孩子們用彩色氣球和彩帶裝飾房間，慶祝朋友的生日派對。"},{"w":"balloon","p":"v.","d":"to quickly become very large or swell out.","c":"激增、如氣球般膨脹","s":"The project's budget ballooned to twice its original amount after several unexpected delays and material cost increases.","t":"在幾次意外延誤和材料成本增加後，該項目的預算膨脹到原來金額的兩倍。"},{"w":"weave / wove / woven","p":"v.","d":"to make cloth by crossing threads over and under each other.","c":"編織","s":"The skilled craftwoman could weave a beautiful pattern into the fabric without even looking at what her hands were doing.","t":"這位技藝精湛的工匠甚至不需要看自己的手，就能將美麗的圖案編織進布料中。"},{"w":"weave strings into","p":"phr.","d":"to twist colorful hair threads together into styles.","c":"將線編入…中","s":"She learned how to weave strings into her daughter's braids to create a traditional style.","t":"她學會了如何將彩色線條編入女兒的辮子中，創造出傳統風格。"},{"w":"weaver","p":"n.","d":"a craft person who specializes in making cloth garments.","c":"織布工、編織者","s":"The weaver worked at a traditional wooden loom for hours each day, producing beautiful handmade scarves and shawls.","t":"這位織布工每天在傳統木製織布機上工作數小時，製作美麗的手工圍巾和披肩。"},{"w":"shoot / shot / shot","p":"v.","d":"to fire a bullet from a gun or kick a sports ball.","c":"發射、射擊、投籃","s":"The basketball player shot the ball from the three-point line and it went straight through the hoop without touching the rim.","t":"籃球運動員從三分線投籃，球直接穿過籃框而沒有碰到框。"},{"w":"shoot / shot / shot","p":"v.","d":"to film a scene or make a music video.","c":"拍攝、攝影","s":"The director decided to shoot the final scene at sunrise to capture the golden light reflecting off the ocean.","t":"導演決定在日出時拍攝最後一幕，捕捉金色陽光在海洋上的倒影。"},{"w":"shoot / shot / shot","p":"v.","d":"to move past someone very quickly and suddenly.","c":"衝過、飛馳而過","s":"The sports car shot past the traffic lights so fast that nobody could even read the number plate on its bumper.","t":"那輛跑車以如此快的速度飛馳過交通燈，以至於沒有人能讀出車牌號碼。"},{"w":"shooting star","p":"phr.","d":"a meteor that makes a bright line across the sky.","c":"流星","s":"They lay on the grass and waited patiently until they finally saw a shooting star streak across the dark sky.","t":"他們躺在草地上耐心等待，直到終於看到一顆流星劃過黑暗的天空。"},{"w":"shoot out","p":"phr.","d":"to suddenly explode or send fire lines out of a slot.","c":"噴出、射出","s":"Sparks began to shoot out from the damaged electrical panel, so the technician cut the power immediately.","t":"受損的電氣面板開始噴出火花，技術人員立即切斷了電源。"},{"w":"shoot up","p":"phr.","d":"to rise or increase very fast in price or height.","c":"暴漲、猛增","s":"The price of vegetables shot up after the typhoon damaged most of the crops in the southern farming regions.","t":"颱風損壞了南部農業區大部分農作物後，蔬菜價格暴漲。"},{"w":"shoot down","p":"phr.","d":"to reject a plan or suggestion completely.","c":"否決（提議等）、擊落","s":"Her creative proposal was shot down by the manager without any explanation, which left her feeling very frustrated.","t":"她的創意提案被經理毫無解釋地否決，讓她感到非常沮喪。"},{"w":"shoot for","p":"phr.","d":"to set a major metric target as your top career goal.","c":"以…為目標、爭取","s":"The young athlete decided to shoot for a spot on the national team by training twice as hard as before.","t":"這位年輕運動員決定通過加倍努力訓練，以爭取國家隊的一個名額為目標。"},{"w":"force","p":"n.","d":"physical power, strength, or military soldiers group.","c":"力量、暴力、軍隊","s":"The force of the storm was so powerful that it knocked down trees and damaged dozens of buildings across the city.","t":"暴風雨的力量如此強大，它推倒了樹木並損壞了城市各地數十棟建築物。"},{"w":"force","p":"v.","d":"to make someone do something they do not want to do.","c":"強迫、迫使","s":"No one should be forced to work overtime without proper compensation, as it is both unfair and against the law.","t":"沒有人應該被強迫在沒有適當補償的情況下加班，因為這既不公平又違法。"},{"w":"forceful","p":"adj.","d":"expressing opinions with huge energy or power.","c":"有力的、強烈的、有說服力的","s":"The lawyer delivered a forceful argument in court that convinced the jury and led to the defendant being found innocent.","t":"律師在法庭上提出了有力的論點，說服了陪審團，最終被告被裁定無罪。"},{"w":"enforce","p":"v.","d":"to make sure that a law or rule is obeyed properly.","c":"執行、實施（法律等）","s":"The school hired additional staff to enforce the new mobile phone policy during lunch breaks and class time.","t":"學校聘請了額外的員工在午休和上課時間執行新的手機政策。"},{"w":"reinforce","p":"v.","d":"to make a material structure or army group stronger.","c":"加強、加固、增援","s":"The engineer recommended using steel beams to reinforce the old bridge so that it could safely carry heavier vehicles.","t":"工程師建議使用鋼梁加固舊橋，使其能夠安全地承載更重的車輛。"},{"w":"workforce","p":"n.","d":"all the available workers inside a country or plant.","c":"勞動力、全體員工","s":"The company invested in training to upskill its workforce and prepare employees for the challenges of new technology.","t":"公司投資於培訓，以提升員工技能，讓全體員工為新技術的挑戰做好準備。"},{"w":"sales force","p":"phr.","d":"the corporate department that sells goods directly.","c":"銷售團隊","s":"The company expanded its sales force by hiring twenty new representatives to cover the northern region of the country.","t":"公司通過聘請二十名新代表負責國家北部地區，擴大了其銷售團隊。"},{"w":"afterwards","p":"adv.","d":"at a later time; after something else has happened.","c":"之後、後來","s":"The ceremony lasted for two hours, and afterwards everyone was invited to the reception hall for food and drinks.","t":"典禮持續了兩個小時，之後每個人都被邀請到接待廳享用食物和飲料。"},{"w":"beforehand","p":"adv.","d":"earlier; before a specific event takes place.","c":"預先、事先","s":"Please make sure you read all the instructions beforehand so that you understand exactly what to do during the fire drill.","t":"請確保你事先閱讀所有指示，這樣你就能清楚地了解在消防演習中應該做什麼。"},{"w":"return","p":"v.","d":"to come or go back to a place; to give an item back.","c":"返回、歸還","s":"She promised to return the library books before the deadline to avoid paying a late fee for each overdue day.","t":"她承諾在截止日期前歸還圖書館的書籍，以避免為每個逾期日支付罰款。"},{"w":"return","p":"n.","d":"the act of coming back to a spot or a profit value.","c":"返回、收益、利潤","s":"His return to the stage after a three-year absence was met with a standing ovation from the delighted audience.","t":"他在三年缺席後重返舞台，受到欣喜若狂的觀眾起立鼓掌的歡迎。"},{"w":"in return","p":"phr.","d":"as a reaction, exchange, or reward for something.","c":"作為回報、作為交換","s":"She helped her neighbour with grocery shopping every week, and in return, he kept an eye on her apartment when she travelled.","t":"她每週幫助鄰居購物，作為回報，他在她旅行時幫忙看顧她的公寓。"},{"w":"difficulty","p":"n.","d":"a problem or a fact of being hard to complete.","c":"困難、難題","s":"She had great difficulty concentrating in the open office because of the constant noise from her colleagues nearby.","t":"她在開放式辦公室裡難以集中注意力，因為附近同事不斷發出的噪音。"},{"w":"difficult","p":"adj.","d":"tough to handle; tracking complex layers.","c":"困難的","s":"Learning to drive on the left side of the road was very difficult for her at first, but she eventually got used to it.","t":"最初在左側車道開車對她來說非常困難，但她最終習慣了。"},{"w":"hardship","p":"n.","d":"severe suffering or lacking basic life assets.","c":"艱苦、困苦","s":"Despite years of hardship and poverty, she never gave up her dream of becoming a doctor and helping her community.","t":"儘管多年艱苦和貧困，她從未放棄成為醫生並幫助社區的夢想。"},{"w":"adult","p":"n.","d":"a person or animal that is fully grown up.","c":"成人","s":"The programme is designed for adults who want to improve their literacy skills and return to education later in life.","t":"該計劃為希望提高識字技能並在以後的人生中重返教育的成人而設計。"},{"w":"adult","p":"adj.","d":"fully developed or suitable only for grown ups.","c":"成年的、成熟的","s":"The film carries an adult rating because it contains scenes of violence that are not suitable for younger viewers.","t":"這部電影帶有成人評級，因為它包含不適合年輕觀眾的暴力場景。"},{"w":"adulthood","p":"n.","d":"the period of time when you are a grown citizen.","c":"成年期","s":"The transition from childhood to adulthood can be challenging, especially when young people face big decisions about their future.","t":"從童年到成年期的轉變可能很具挑戰性，尤其是當年輕人面臨關於未來的重大決定時。"}]},{"unit":14,"theme":"assure – be guilty of","cards":[{"w":"assure","p":"v.","d":"to promise someone that something is definitely true.","c":"向…保證、使確信","s":"The doctor assured the patient that the operation was routine and that he would feel much better within a week.","t":"醫生向病人保證手術是例行性的，他在一週內就會感覺好多了。"},{"w":"assure","p":"v.","d":"to make a positive outcome certain to happen.","c":"確保、保障","s":"Hard work and careful planning can assure the success of a project, but unexpected challenges can still arise.","t":"努力工作和仔細規劃可以確保項目的成功，但意外的挑戰仍然可能出現。"},{"w":"reassure","p":"v.","d":"to say words to stop someone from worrying.","c":"使安心、使放心","s":"She called her parents right after landing to reassure them that she had arrived safely and that everything was fine.","t":"她一落地就打電話給父母，讓他們放心她已安全抵達，一切都很好。"},{"w":"assurance","p":"n.","d":"a firm promise or a high state of self confidence.","c":"保證、把握、自信","s":"Despite his assurance that the report would be ready by Friday, it was not submitted until the following Monday morning.","t":"儘管他保證報告將在週五前完成，但它直到下週一早上才提交。"},{"w":"assure someone that","p":"phr.","d":"to tell a peer clearly that a task will finish.","c":"向某人保證…","s":"The manager assured us that the project would be delivered on time and within the agreed budget.","t":"經理向團隊保證該項目將按時交付，並在商定的預算範圍內完成。"},{"w":"assure someone of","p":"phr.","d":"to make a manager feel fully safe about a trait.","c":"讓某人確信某事","s":"She tried to assure them of her full commitment to the role during the job interview by sharing specific examples.","t":"她在工作面試中通過分享具體例子，試圖讓面試官確信她對這個職位的完全承諾。"},{"w":"destroy","p":"v.","d":"to damage something so badly that it cannot be fixed.","c":"破壞、毀滅","s":"The fire completely destroyed three houses on the street before firefighters managed to bring it under control.","t":"火災完全摧毀了街上的三棟房子，然後消防員才設法將其控制住。"},{"w":"destruction","p":"n.","d":"the act or process of ruining an asset completely.","c":"破壞、毀滅","s":"The destruction caused by the flood left thousands of families without homes and forced the government to act quickly.","t":"洪水造成的破壞使數千個家庭無家可歸，迫使政府迅速採取行動。"},{"w":"destructive","p":"adj.","d":"causing a huge amount of deep damage or harm.","c":"破壞性的、毀滅性的","s":"The typhoon was one of the most destructive storms to hit the island in decades, damaging roads, bridges, and farmland.","t":"這場颱風是數十年來襲擊這個島嶼最具破壞性的風暴之一，損壞了道路、橋樑和農地。"},{"w":"damage","p":"v.","d":"to harm an item; a loss in value or beauty.","c":"損害、損壞","s":"Heavy rain damaged the roof of the school gymnasium, and repairs had to be completed before classes could resume.","t":"大雨損壞了學校體育館的屋頂，必須在課程恢復之前完成修繕。"},{"w":"ruin","p":"v.","d":"to completely spoil or destroy a plan or dish.","c":"毀掉、搞砸","s":"Leaving the milk out of the fridge overnight completely ruined it, and she had to throw the whole carton away.","t":"將牛奶在冰箱外放置一夜完全毀掉了它，她不得不把整個紙盒扔掉。"},{"w":"reliable","p":"adj.","d":"able to be trusted to work or behave well.","c":"可靠的、可信賴的","s":"She has always been the most reliable member of the team, always meeting deadlines and producing high-quality work.","t":"她一直是團隊中最可靠的成員，總是按時完成任務並產出高質量的工作。"},{"w":"rely","p":"v.","d":"to depend on or trust someone fully.","c":"依靠、信賴","s":"You cannot always rely on others to solve your problems — developing independence is an important life skill.","t":"你不能總是依靠別人來解決你的問題——培養獨立性是一項重要的生活技能。"},{"w":"rely on","p":"phr.","d":"to place your full success in a peer's hands.","c":"依賴…、信任…","s":"Farmers in this region still rely on seasonal rainfall to water their crops instead of using irrigation systems.","t":"這個地區的農民仍然依賴季節性降雨來灌溉他們的農作物，而不是使用灌溉系統。"},{"w":"reliance","p":"n.","d":"the state of needing or trusting an outside item.","c":"依賴、信任","s":"The country's heavy reliance on imported oil made it very vulnerable when global fuel prices suddenly increased.","t":"這個國家對進口石油的過度依賴使其在全球燃料價格突然上漲時非常脆弱。"},{"w":"search","p":"v.","d":"to look carefully across an area to find an item.","c":"搜尋、搜查","s":"Police officers searched the entire building for clues after a valuable painting was reported stolen from the gallery.","t":"在一幅珍貴的畫作被報告從畫廊失竊後，警察搜查了整棟建築尋找線索。"},{"w":"search","p":"n.","d":"an active process of hunting for a missing target.","c":"搜尋、搜查","s":"The search for the missing hiker lasted three days before he was finally found sheltering in a cave on the hillside.","t":"對失蹤登山者的搜尋持續了三天，最後終於在山坡上的一個洞穴中找到了他。"},{"w":"search for","p":"phr.","d":"to try to find a specific lost tool or person.","c":"尋找…","s":"She searched for her glasses for twenty minutes before realising she had left them on top of her own head.","t":"她尋找眼鏡找了二十分鐘，然後才意識到她把眼鏡放在了自己頭頂上。"},{"w":"search high and low","p":"phr.","d":"to look everywhere imaginable for a lost object.","c":"到處尋找、翻箱倒櫃","s":"He searched high and low for his passport the morning of the flight but could not find it anywhere in the house.","t":"他在飛行當天早上翻箱倒櫃地尋找護照，但在家裡任何地方都找不到。"},{"w":"in search of","p":"phr.","d":"traversing a zone with the goal of finding assets.","c":"尋找…","s":"Thousands of people left their villages in search of better opportunities in the rapidly growing capital city.","t":"數千人離開村莊，前往快速發展的首都尋找更好的機會。"},{"w":"search engine","p":"n.","d":"a computer program used to find websites online.","c":"搜尋引擎","s":"She typed the name of the restaurant into the search engine and found its menu, reviews, and opening hours instantly.","t":"她在搜尋引擎中輸入餐廳名稱，立即找到了其菜單、評論和營業時間。"},{"w":"clue","p":"n.","d":"a sign or fact that helps solve a crime puzzle.","c":"線索、提示","s":"The detective found a single clue at the scene — a muddy footprint near the back door — that broke the case open.","t":"偵探在現場發現了一個線索——後門附近的一個泥濘腳印——這打開了案件的突破口。"},{"w":"have no clue","p":"phr.","d":"to be completely ignorant about an event background.","c":"毫無頭緒、一無所知","s":"I have no clue how to fix this error in the code, so I asked my more experienced colleague for help.","t":"我對如何修復代碼中的這個錯誤毫無頭緒，所以我向更有經驗的同事尋求幫助。"},{"w":"clueless","p":"adj.","d":"tracking zero knowledge about a current topic task.","c":"毫無頭緒的、愚蠢的","s":"He felt completely clueless during the advanced mathematics lesson, as he had missed the previous week's foundational class.","t":"他在高等數學課上感到完全毫無頭緒，因為他錯過了上週的基礎課。"},{"w":"obtain","p":"v.","d":"to get something after an effort or official request.","c":"獲得、贏得、買到","s":"Students must obtain a special permit from the office before they are allowed to use the advanced science laboratory.","t":"學生必須從辦公室獲得特別許可，才能使用高級科學實驗室。"},{"w":"acquire","p":"v.","d":"to pick up a local habit or buy a property firm.","c":"獲得、學得","s":"She managed to acquire three new languages during her years of working overseas in Europe and South America.","t":"她在歐洲和南美洲工作的幾年裡，成功學得了三門新語言。"},{"w":"attain","p":"v.","d":"to reach a high milestone score after years of work.","c":"達到、實現","s":"After years of dedicated practice, she finally managed to attain the level of fluency needed to teach English professionally.","t":"經過多年的專注練習，她終於達到了專業教授英語所需的流利程度。"},{"w":"witness","p":"n.","d":"a person who saw a crime or accident happen.","c":"目擊者、證人","s":"A key witness came forward to give testimony after seeing the robbery take place from across the street.","t":"一位關鍵目擊者在從街對面看到搶劫發生後，站出來提供了證詞。"},{"w":"witness","p":"v.","d":"to see an event take place with your own eyes.","c":"目擊、看到","s":"She was lucky enough to witness the rare northern lights display while on a holiday trip to Iceland last winter.","t":"她去年冬天在冰島度假時，有幸親眼目睹了罕見的北極光表演。"},{"w":"bear witness to","p":"phr.","d":"to show clear proof that a baseline fact is true.","c":"證明、見證","s":"The ancient ruins bore witness to the incredible skill of the architects who built them thousands of years ago.","t":"這些古代遺跡見證了數千年前建造它們的建築師令人難以置信的技藝。"},{"w":"doubt","p":"n.","d":"a feeling of being unsure about a statement truth.","c":"懷疑、疑問","s":"There is some doubt about whether the project can be completed on time, given the number of issues encountered so far.","t":"考慮到目前遇到的問題數量，對於項目能否按時完成存在一些疑問。"},{"w":"doubt","p":"v.","d":"to think that something is unlikely or untrue.","c":"懷疑、不信","s":"She began to doubt her decision to move abroad after hearing negative stories from friends who had done the same thing.","t":"在聽到做了同樣事情的朋友的負面故事後，她開始懷疑自己移居海外的決定。"},{"w":"no doubt","p":"phr.","d":"certainly; tracking zero chance of being false.","c":"毫無疑問地、肯定","s":"She is, no doubt, one of the most talented writers of her generation and will be remembered for decades to come.","t":"她毫無疑問是她那一代最有才華的作家之一，將被銘記數十年。"},{"w":"doubtful","p":"adj.","d":"unlikely to be true; tracking low confidence values.","c":"懷疑的、不確定的","s":"It seems doubtful that the construction will be finished by the original deadline given the delays caused by bad weather.","t":"考慮到惡劣天氣造成的延誤，建設工程能否在原定截止日期前完成似乎令人懷疑。"},{"w":"suspect","p":"v.","d":"to think that someone is guilty of a major felony.","c":"懷疑、猜想（某人有罪）","s":"The investigators began to suspect that the fire had been started deliberately after finding traces of accelerant at the scene.","t":"調查人員在現場發現助燃劑的痕跡後，開始懷疑火災是故意放火引起的。"},{"w":"suspect","p":"n.","d":"a person whom the police think committed a crime.","c":"嫌疑犯","s":"Police arrested a suspect early this morning in connection with the robbery that took place at the bank last Friday.","t":"警方今天早上逮捕了一名與上週五銀行搶劫案有關的嫌疑犯。"},{"w":"assign","p":"v.","d":"to give someone a specific job, task, or duty.","c":"分派、指派、分配","s":"The teacher assigned each student a different country to research for the geography project due next Friday.","t":"老師為每位學生分派了一個不同的國家進行研究，以完成下週五到期的地理項目。"},{"w":"assignment","p":"n.","d":"a piece of work given to a student or employee.","c":"任務、功課、作業","s":"She spent the whole weekend working on her history assignment, which required her to analyse three primary source documents.","t":"她整個週末都在做她的歷史作業，這需要她分析三個主要來源文件。"},{"w":"aim","p":"v.","d":"to point a weapon at a target; to intend to win.","c":"對準、旨在、企圖","s":"The new education policy aims to reduce the gap between students from wealthy and low-income backgrounds.","t":"新教育政策旨在縮小來自富裕和低收入背景學生之間的差距。"},{"w":"aim","p":"n.","d":"a goal or purpose that you want to achieve.","c":"目標、目的","s":"The aim of the workshop is to help participants develop practical skills they can use immediately in the workplace.","t":"工作坊的目標是幫助參與者培養他們可以立即在職場中使用的實用技能。"},{"w":"aim to","p":"phr.","d":"setting up an internal milestone to learn a skill.","c":"旨在…、力求…","s":"She aim to finish her novel by the end of the year and has been writing for two hours every morning.","t":"她力求在年底前完成她的小說，每天早上已經寫了兩個小時。"},{"w":"aim at","p":"phr.","d":"pointing a camera or gun directly at an entity.","c":"瞄準…","s":"The campaign is aim at reducing plastic waste by encouraging shoppers to use reusable bags and containers.","t":"該活動旨在通過鼓勵購物者使用可重複使用的袋子和容器來減少塑膠廢棄物。"},{"w":"angle","p":"n.","d":"the space between two lines; a viewpoint angle.","c":"角度、觀點、立足點","s":"The photographer moved around the subject to find the perfect angle that would show off its best features.","t":"攝影師在被攝主體周圍移動，尋找能夠展示其最佳特色的完美角度。"},{"w":"from another angle","p":"phr.","d":"reviewing a social crisis using a fresh perspective.","c":"從另一個角度來看","s":"If you look at the problem from another angle, you might find that the solution is actually quite straightforward.","t":"如果你從另一個角度看這個問題，你可能會發現解決方案實際上相當簡單。"},{"w":"fate","p":"n.","d":"an outside power that controls what happens to you.","c":"命運","s":"She believed that meeting her best friend at that café was not an accident — it was fate bringing them together.","t":"她相信在那家咖啡館遇見她最好的朋友不是偶然——是命運將他們帶到了一起。"},{"w":"fatal","p":"adj.","d":"causing complete death or total operation failure.","c":"致命的","s":"The doctor confirmed that the injuries sustained in the crash were fatal and that there was nothing more they could do.","t":"醫生確認在撞車事故中受到的傷害是致命的，他們已無能為力。"},{"w":"innocent","p":"adj.","d":"not guilty of committing a specific crime.","c":"無罪的、清白的、天真的","s":"After ten years in prison, new DNA evidence finally proved that he was innocent and he was released immediately.","t":"在監獄待了十年後，新的DNA證據終於證明他是無罪的，他立即獲釋。"},{"w":"innocence","p":"n.","d":"the state of being clear of all generic charges.","c":"無罪、清白、天真","s":"The lawyer worked tirelessly to prove his client's innocence and spent months gathering new evidence for the appeal.","t":"律師不知疲倦地工作，以證明客戶的清白，並花了數月時間收集新的上訴證據。"},{"w":"prison","p":"n.","d":"a secure government building where criminals stay.","c":"監獄","s":"He was sentenced to five years in prison for his role in the financial fraud that affected thousands of investors.","t":"他因在影響數千名投資者的金融詐欺中的角色而被判入獄五年。"},{"w":"jail","p":"n.","d":"a short-term cell used to lock up local offenders.","c":"監獄、拘留所","s":"The suspect was held in jail overnight while investigators gathered more evidence before deciding whether to charge him.","t":"嫌疑犯被關押在拘留所過夜，調查人員在決定是否起訴他之前收集了更多證據。"},{"w":"prisoner","p":"n.","d":"a person locked up inside a cell room.","c":"囚犯、犯人","s":"The prisoner had been serving a twelve-year sentence and was finally granted early release for good behaviour.","t":"這名囚犯已服滿十二年的刑期，終於因表現良好而獲得提前釋放。"},{"w":"imprison","p":"v.","d":"to lock a citizen away behind iron bars legally.","c":"監禁、關押","s":"The activist was imprisoned for two years after publicly speaking out against the government's unfair housing policies.","t":"這名社運人士在公開反對政府不公平的住房政策後被監禁了兩年。"},{"w":"criminal","p":"n.","d":"a person who committed a major breaking of law.","c":"犯罪者、罪犯","s":"The police worked with international agencies to track down the criminal who had been operating across several countries.","t":"警方與國際機構合作，追蹤在幾個國家活動的罪犯。"},{"w":"criminal","p":"adj.","d":"relating to crime or illegal court matters.","c":"犯罪的、刑事的","s":"The company faced a criminal investigation after auditors discovered that millions of dollars had gone missing from its accounts.","t":"審計人員發現數百萬元從其帳戶中消失後，該公司面臨刑事調查。"},{"w":"crime","p":"n.","d":"an illegal act that is punishable by state courts.","c":"罪行、犯罪行為","s":"The neighbourhood watch programme helped reduce the rate of petty crime in the area by thirty percent last year.","t":"社區守望計劃幫助去年將該地區的輕微犯罪率降低了百分之三十。"},{"w":"guilty","p":"adj.","d":"responsible for breaking a law in a court room.","c":"有罪的","s":"The jury found the defendant guilty on all three counts after deliberating for less than two hours.","t":"陪審團在審議不到兩小時後，裁定被告三項罪名全部成立。"},{"w":"guilty","p":"adj.","d":"feeling bad because you did an incorrect action.","c":"內疚的、有罪惡感的","s":"She felt guilty about forgetting her friend's birthday and immediately went out to buy a belated card and gift.","t":"她對忘記朋友的生日感到內疚，立即出去買了一張遲到的卡片和禮物。"},{"w":"guilt","p":"n.","d":"a heavy mental load from doing wrong actions.","c":"罪責、內疚、罪惡感","s":"The guilt of having lied to his parents weighed on him for weeks until he finally sat down and told them the truth.","t":"對父母撒謊的內疚感困擾了他好幾週，直到他終於坐下來告訴他們真相。"},{"w":"feel guilty","p":"phr.","d":"tracking ongoing internal regret over an old choice.","c":"感到內疚","s":"She feel guilty about eating the last piece of cake when she realized her brother had been saving it for later.","t":"當她意識到弟弟一直在留著那塊蛋糕以後再吃時，她對吃掉最後一塊蛋糕感到內疚。"},{"w":"be guilty of","p":"phr.","d":"officially flagged for a specific bad behavior line.","c":"犯了…罪、對…感到內疚","s":"The report concluded that the company was guilty of misleading customers about the contents of its products.","t":"報告得出結論，該公司犯了誤導顧客關於其產品內容的罪行。"}]},{"unit":15,"theme":"prominent – significance","cards":[{"w":"prominent","p":"adj.","d":"highly important, famous, or easily seen in a spot.","c":"著名的、顯著的、突出的","s":"She is a prominent figure in the field of environmental science and has published over fifty research papers.","t":"她是環境科學領域的著名人物，已發表了五十多篇研究論文。"},{"w":"prominence","p":"n.","d":"the state of being important, famous, or noticeable.","c":"顯著、傑出、聲望","s":"The young chef rose to prominence after winning a national cooking competition that was broadcast on television.","t":"這位年輕廚師在贏得一個電視播出的全國烹飪比賽後聲名鵲起。"},{"w":"award","p":"v.","d":"to officially give a prize to reward top work.","c":"授予、頒發（獎項）","s":"The university awarded her an honorary degree for her outstanding contributions to medical research over forty years.","t":"大學因她四十年來對醫學研究的傑出貢獻而授予她榮譽學位。"},{"w":"award","p":"n.","d":"a prize or medal won in a specialized contest.","c":"獎、獎項","s":"Winning the national photography award at such a young age gave her the confidence to pursue it as a full-time career.","t":"在如此年輕的年齡贏得全國攝影獎給了她將其作為全職職業追求的信心。"},{"w":"reward","p":"v.","d":"token cash given to thank someone for casual help.","c":"報酬、獎賞","s":"The company offered a generous reward to anyone who could provide information leading to the recovery of the stolen laptop.","t":"公司向任何能提供有助於追回被盜筆記型電腦資訊的人提供豐厚的獎賞。"},{"w":"fictional","p":"adj.","d":"imaginary; appearing inside storybooks, not real.","c":"虛構的、小說中的","s":"The fictional town of Willowbrook was so vividly described in the novel that many readers felt it was a real place.","t":"這座虛構的柳溪鎮在小說中被描寫得如此生動，許多讀者感覺它是一個真實的地方。"},{"w":"fiction","p":"n.","d":"books and stories about imaginary people or events.","c":"小說、虛構故事","s":"She prefers reading fiction over factual books because she enjoys being transported to imaginary worlds and stories.","t":"她更喜歡讀小說而不是事實性書籍，因為她喜歡被帶入虛構的世界和故事中。"},{"w":"non-fiction","p":"n.","d":"books writing strictly about true historical events.","c":"非小說類寫實文學","s":"The bestselling non-fiction book explored the true story of a remarkable scientist whose work changed modern medicine.","t":"這本暢銷非小說類書籍探索了一位傑出科學家的真實故事，其工作改變了現代醫學。"},{"w":"mayor","p":"n.","d":"the elected political head of a city government.","c":"市長","s":"The mayor announced a new plan to build affordable housing units in the city centre to help low-income families.","t":"市長宣布了一項在市中心建設經濟適用房的新計劃，以幫助低收入家庭。"},{"w":"mayo","p":"n.","d":"short name for white egg spread used on toast.","c":"美乃滋","s":"She spread a thin layer of mayo on the sandwich before adding sliced tomatoes, lettuce, and grilled chicken.","t":"她在三明治上抹了一薄層美乃滋，然後加入切片番茄、生菜和烤雞肉。"},{"w":"responsible","p":"adj.","d":"having a duty to take care of a department task.","c":"負責的、具責任心的","s":"Each student is responsible for completing their own section of the group project and submitting it before the deadline.","t":"每個學生負責完成小組項目自己那部分，並在截止日期前提交。"},{"w":"responsibility","p":"n.","d":"a specific duty or burden that an agent must track.","c":"責任、職責","s":"It is the responsibility of every citizen to vote in elections and make sure their voice is heard by the government.","t":"每個公民有責任在選舉中投票，確保政府聽到他們的聲音。"},{"w":"irresponsibility","p":"n.","d":"a bad trait of tracking zero care for assignment rules.","c":"不負責任","s":"His irresponsibility in missing the deadline without any notice put the whole team under enormous last-minute pressure.","t":"他在沒有任何通知的情況下錯過截止日期的不負責任，給整個團隊帶來了巨大的最後一刻壓力。"},{"w":"fund","p":"n.","d":"an amount of money saved for a specific purpose.","c":"基金、資金","s":"The school set up a special fund to help students from low-income families pay for school trips and activities.","t":"學校設立了一個特別基金，幫助來自低收入家庭的學生支付學校旅行和活動的費用。"},{"w":"fund","p":"v.","d":"to provide the cash needed to run a project.","c":"資助、提供資金","s":"The government agreed to fund the research project with five million dollars over the next three years.","t":"政府同意在未來三年內以五百萬元資助這個研究項目。"},{"w":"funding","p":"n.","d":"money given by a university or corporate body.","c":"資金、資助（款項）","s":"The charity lost its main source of funding when the company that supported it was forced to cut its budget.","t":"當支持它的公司被迫削減預算時，這家慈善機構失去了其主要資金來源。"},{"w":"fundraising","p":"n.","d":"the active collection of cash to support charities.","c":"募款、籌款活動","s":"The school organised a fundraising event that raised enough money to buy new computers for the library.","t":"學校組織了一次募款活動，籌集了足夠的資金為圖書館購買新電腦。"},{"w":"publicity","p":"n.","d":"public attention or media coverage for an object.","c":"宣傳、知名度、公眾注意","s":"The unexpected controversy surrounding the film actually generated massive publicity and boosted ticket sales significantly.","t":"圍繞這部電影的意外爭議實際上產生了大量宣傳，並顯著提升了票房銷售。"},{"w":"publicize","p":"v.","d":"to give details to newspapers to attract attention.","c":"宣傳、公布、推廣","s":"The city council used social media to publicize the new recycling programme and encourage residents to participate.","t":"市議會使用社群媒體宣傳新的回收計劃，並鼓勵居民參與。"},{"w":"public","p":"adj.","d":"relating to ordinary citizens; the general masses.","c":"公眾的、大眾","s":"The new park will be open to the public free of charge seven days a week from six in the morning until midnight.","t":"新公園將每週七天、從早上六點到午夜免費向公眾開放。"},{"w":"require","p":"v.","d":"to need something or make it mandatory by rule.","c":"需要、要求、規定","s":"All participants are required to submit a completed entry form and a copy of their ID at least one week before the event.","t":"所有參與者都被要求在活動前至少一週提交填妥的報名表和身份證副本。"},{"w":"requirement","p":"n.","d":"a mandatory baseline spec needed to enter a club.","c":"必要條件、要求","s":"One of the key requirements for the scholarship is that applicants must have maintained a grade average above eighty percent.","t":"獎學金的關鍵要求之一是申請者必須保持平均成績在百分之八十以上。"},{"w":"receiver","p":"n.","d":"a person who gets a package or award prize.","c":"接收者、受獎人、聽筒","s":"The receiver of the community service award thanked her neighbours and volunteers who had supported her work over the years.","t":"社區服務獎的受獎人感謝了多年來支持她工作的鄰居和義工們。"},{"w":"receive","p":"v.","d":"to accept or take an item passed to you.","c":"收到、接受","s":"She was overjoyed when she received the acceptance letter from the university she had always dreamed of attending.","t":"當她收到她一直夢想就讀的大學的錄取通知書時，她欣喜若狂。"},{"w":"reveal","p":"v.","d":"to show or tell a secret fact that was hidden.","c":"透露、顯露、揭露","s":"The documentary revealed shocking facts about the food industry that most consumers had never been aware of before.","t":"這部紀錄片揭露了大多數消費者以前從未意識到的食品行業的驚人事實。"},{"w":"revelation","p":"n.","d":"a sudden shocking fact that is made public.","c":"揭露、啟示、被揭露的真相","s":"The revelation that the famous author had been secretly writing under a different name shocked the entire literary world.","t":"這位著名作家一直秘密以不同名字寫作的揭露震驚了整個文學界。"},{"w":"honoree","p":"n.","d":"a person who receives a special public award respect.","c":"領獎人、受勳者、應受尊敬的人","s":"As the evening's main honoree, she gave a moving speech about her journey and thanked everyone who had supported her.","t":"作為當晚的主要領獎人，她發表了感人的演講，講述了她的歷程，並感謝了所有支持她的人。"},{"w":"employee","p":"n.","d":"a worker who draws monthly wages from a company.","c":"員工、僱員","s":"Every employee at the company received a bonus at the end of the year as a reward for their hard work and dedication.","t":"公司的每位員工在年底收到獎金，作為對他們努力工作和奉獻精神的獎勵。"},{"w":"interviewee","p":"n.","d":"a candidate answering questions during a job test.","c":"受訪者、面試者","s":"The interviewee prepared thoroughly for the panel interview and was able to answer every question with confidence.","t":"受訪者為小組面試做了充分準備，能夠自信地回答每個問題。"},{"w":"addressee","p":"n.","d":"the explicit name listed on a postage envelope.","c":"收件人","s":"The parcel could not be delivered because the addressee had moved to a new address without updating her details.","t":"包裹無法送達，因為收件人已搬到新地址，但沒有更新她的詳細資訊。"},{"w":"exposure","p":"n.","d":"the fact of experiencing or being unprotected from air.","c":"暴露、接觸、曝曬","s":"Long-term exposure to strong sunlight without protection can cause serious skin damage and increase the risk of cancer.","t":"長期在沒有保護的情況下暴露在強烈陽光下可能會導致嚴重的皮膚損傷並增加癌症風險。"},{"w":"exposure","p":"n.","d":"public attention generated by news articles lines.","c":"曝光度、宣傳","s":"Winning the national award gave the small bakery enormous exposure and customers started queuing from all over the city.","t":"贏得全國獎項給這家小烘焙坊帶來了巨大的曝光度，顧客開始從城市各地排隊。"},{"w":"expose","p":"v.","d":"to remove a cover to reveal a hidden danger file.","c":"暴露、揭露、使接觸","s":"The investigative journalist risked her career to expose corruption within the city's planning department.","t":"這位調查記者冒著職業風險揭露了城市規劃部門內部的腐敗行為。"},{"w":"exposure to","p":"phr.","d":"being stuck next to loud sounds across long years.","c":"暴露於…、接觸…","s":"Regular exposure to English outside the classroom is one of the best ways to improve fluency and listening skills.","t":"在課堂外定期接觸英語是提高流利度和聽力技能的最佳方式之一。"},{"w":"promptly","p":"adv.","d":"quickly; immediately without any lazy delay.","c":"迅速地、準時地","s":"The hotel staff promptly replaced the broken air conditioner after the guest reported the problem at the front desk.","t":"客人在前台報告問題後，酒店員工迅速更換了損壞的空調。"},{"w":"prompt","p":"adj.","d":"done without delay; tracking swift clean action.","c":"迅速的、即時的","s":"Her prompt response to the emergency prevented the situation from becoming much worse than it already was.","t":"她對緊急情況的迅速反應阻止了局勢變得比已有的更加糟糕。"},{"w":"prompt","p":"v.","d":"to cause someone to make a sudden decision move.","c":"促使、激起、提示","s":"The news about rising sea levels prompted the local government to invest more money in coastal flood defences.","t":"關於海平面上升的消息促使當地政府在沿海防洪設施上投入更多資金。"},{"w":"individual","p":"n.","d":"a single person considered separate from a team.","c":"個人、個體","s":"Every individual in the community has a role to play in making the neighbourhood safer and more pleasant for everyone.","t":"社區中的每個個人都在使社區對所有人更安全、更愉快方面發揮著作用。"},{"w":"individual","p":"adj.","d":"given to or matching only one single citizen.","c":"個別的、獨特的","s":"The teacher gave individual feedback to each student after the presentation so they could all improve in different ways.","t":"老師在演講結束後給每位學生個別反饋，這樣他們都可以以不同方式進步。"},{"w":"individual serving","p":"phr.","d":"a food pack wrapped for exactly one diner unit.","c":"單人份","s":"The café offers individual serving options of each dessert so that customers can try different flavours without overeating.","t":"咖啡館提供每種甜點的單人份選項，讓顧客可以在不過量飲食的情況下嘗試不同口味。"},{"w":"individually","p":"adv.","d":"one by one; handled separately across steps.","c":"個別地、逐一地","s":"Each application will be reviewed individually by a panel of three judges who will score candidates based on set criteria.","t":"每份申請將由三位評審組成的小組個別審查，他們將根據既定標準對候選人進行評分。"},{"w":"label","p":"v.","d":"to attach a piece of paper listing names to a box.","c":"貼標籤於、歸類為","s":"She labeled each storage box with a clear description of its contents so that items could be found easily later.","t":"她在每個儲物箱上貼上清晰描述其內容的標籤，以便以後能夠輕鬆找到物品。"},{"w":"label","p":"n.","d":"a small tag on clothing tracking wash rules text.","c":"標籤、標牌","s":"Always check the care label on clothing before washing to avoid shrinking delicate fabrics in hot water.","t":"洗滌前請務必查看衣物上的護理標籤，以避免精緻面料在熱水中縮水。"},{"w":"steal / stole / stolen","p":"v.","d":"to take an asset without permission secretly.","c":"偷竊、竊取","s":"Someone stole her bicycle from outside the library while she was inside studying for her afternoon exam.","t":"她在圖書館內為下午的考試學習時，有人偷走了她停在外面的自行車。"},{"w":"rob","p":"v.","d":"to use force or guns to claim bank cash assets.","c":"搶劫、奪取","s":"Two masked men attempted to rob the jewellery store but were caught by police before they could escape.","t":"兩名蒙面男子試圖搶劫珠寶店，但在逃跑前被警察抓獲。"},{"w":"despite","p":"n.","d":"without being affected by; in spite of a risk.","c":"儘管、雖然","s":"Despite feeling nervous, she delivered her speech confidently and received warm applause from the entire audience.","t":"儘管感到緊張，她還是自信地發表了演講，並獲得了全場觀眾的熱烈掌聲。"},{"w":"in spite of","p":"phr.","d":"handling a wedding outside facing a rain warning.","c":"儘管、雖然","s":"In spite of the heavy rain forecast, the outdoor wedding ceremony went ahead and everyone had a wonderful time.","t":"儘管有大雨預報，戶外婚禮儀式仍然如期進行，每個人都度過了美好的時光。"},{"w":"despite the fact that","p":"phr.","d":"waking up early but still losing the transit race.","c":"儘管事實是…","s":"Despite the fact that she had studied hard, she did not pass the exam and decided to retake it the following month.","t":"儘管她努力學習，她還是沒有通過考試，並決定下個月重考。"},{"w":"temporarily","p":"adv.","d":"for a limited time only; not permanently fixed.","c":"暫時地","s":"The road was temporarily closed for repairs, so drivers were asked to use the alternative route through the town centre.","t":"道路因維修而暫時關閉，因此司機被要求使用通過市中心的替代路線。"},{"w":"temporary","p":"adj.","d":"lasting for a brief duration; tracking early ends.","c":"暫時的、臨時的","s":"She took a temporary job at the bookshop during the summer to earn some extra money before her university term started.","t":"她在暑假期間在書店做了一份臨時工作，在大學學期開始前賺些額外的錢。"},{"w":"remove","p":"v.","d":"to take something away or drop a virus block.","c":"移開、移除、脫掉","s":"Please remove your shoes before entering the house, as it is a family rule to keep the floors clean at all times.","t":"進屋前請脫掉鞋子，因為保持地板時刻清潔是家規。"},{"w":"removal","p":"n.","d":"the systemic clean dropping of old database entries.","c":"消除、移除","s":"The removal of the graffiti from the school wall took the maintenance team an entire afternoon to complete.","t":"清除學校牆壁上塗鴉的工作花了維護團隊整整一個下午才完成。"},{"w":"construction","p":"n.","d":"the active building of apartments or bridge spans.","c":"建造、建設、建築業","s":"The construction of the new metro line is expected to take five years and will create thousands of jobs in the city.","t":"新地鐵線的建設預計需要五年時間，將在城市創造數千個就業機會。"},{"w":"constructive","p":"adj.","d":"providing helpful ideas to fix operational bugs.","c":"建設性的、有助益的","s":"Her manager gave her some very constructive feedback after the presentation, which helped her improve significantly next time.","t":"她的經理在演講結束後給了她一些非常具有建設性的反饋，這幫助她下次大幅改進。"},{"w":"construct","p":"v.","d":"to build a large layout structure using concrete.","c":"建造、構成","s":"Engineers worked around the clock to construct the temporary bridge that would allow emergency vehicles to cross the river.","t":"工程師全天候工作，建造臨時橋樑，讓緊急車輛能夠跨越河流。"},{"w":"run for","p":"phr.","d":"to enter a political race to win a mayor role.","c":"競選","s":"She announced her decision to run for city council, promising to focus on improving public transport and green spaces.","t":"她宣布競選市議員的決定，承諾將重點放在改善公共交通和綠地上。"},{"w":"roughly","p":"adv.","d":"approximately; tracking minor number variances.","c":"大約、粗略地","s":"The journey from Taipei to Tainan by high-speed rail takes roughly ninety minutes, depending on which train you catch.","t":"從台北乘高鐵到台南大約需要九十分鐘，取決於你搭乘哪班列車。"},{"w":"rough","p":"adj.","d":"having an uneven surface; wild storm conditions.","c":"粗糙的、粗略的、艱難的","s":"The surface of the old stone wall felt extremely rough to the touch, with deep grooves carved in by centuries of weather.","t":"舊石牆的表面摸起來極為粗糙，上面有幾個世紀的風化侵蝕留下的深槽。"},{"w":"significant","p":"adj.","d":"highly important, large, or noticeable in scale.","c":"顯著的、重要的、有重大意義的","s":"There has been a significant improvement in air quality since the city introduced stricter vehicle emissions regulations last year.","t":"自去年城市引入更嚴格的車輛排放法規以來，空氣品質有了顯著改善。"},{"w":"value significance","p":"phr.","d":"the core deep meaning held inside an old token.","c":"重大意義","s":"Historians debated the value significance of the ancient coin, arguing about what it revealed about the civilization's trade.","t":"歷史學家們討論了這枚古代硬幣的重大意義，爭論它揭示了該文明貿易的什麼信息。"},{"w":"considerably","p":"adv.","d":"by a large, notable measure that changes status.","c":"相當地、非常","s":"The new highway has considerably reduced commuting time for thousands of workers who travel between the two cities daily.","t":"新高速公路大幅縮短了每天在兩座城市之間通勤的數千名工人的通勤時間。"},{"w":"significantly","p":"adv.","d":"in a way that is large enough to be clear value.","c":"顯著地、大幅地","s":"Sales figures increased significantly after the company launched its new marketing campaign on social media platforms.","t":"公司在社群媒體平台上推出新行銷活動後，銷售數字顯著增加。"},{"w":"significance","p":"n.","d":"the underlying importance or quality of an aura.","c":"重要性、意義","s":"Few people fully understood the significance of the discovery at the time, but it eventually changed the field of medicine.","t":"當時很少有人完全理解這項發現的重要性，但它最終改變了醫學領域。"}]},{"unit":16,"theme":"similar – economic depression","cards":[{"w":"similar","p":"adj.","d":"sharing matching features but not completely identical.","c":"相似的、類似的","s":"The two sisters have very similar tastes in music, often recommending the same songs to each other without knowing it.","t":"這對姐妹在音樂品味上非常相似，常常在不知情的情況下向對方推薦相同的歌曲。"},{"w":"similarity","p":"n.","d":"a specific matching point shared between distinct items.","c":"相似處、類似點","s":"Despite growing up in different cities, the two friends found a surprising similarity in their childhood experiences.","t":"儘管在不同的城市長大，這兩位朋友在童年經歷中發現了令人驚訝的相似之處。"},{"w":"A is similar to B","p":"phr.","d":"one object looks or behaves like a separate counterpart.","c":"A與B相似","s":"This new smartphone is similar to the previous model in design, but it has a much faster processor inside.","t":"這款新智慧型手機在設計上與舊款相似，但內部處理器速度快得多。"},{"w":"be similar in","p":"phr.","d":"sharing matching metrics within an explicit category.","c":"在…方面相似","s":"The two proposals are similar in budget requirements but differ greatly in their overall approach to the problem.","t":"這兩個提案在預算要求方面相似，但在解決問題的整體方法上差異很大。"},{"w":"fashion","p":"n.","d":"a specific style of clothes popular at a certain time.","c":"流行、時尚","s":"She has always been interested in fashion and dreams of one day designing her own clothing line for young women.","t":"她一直對時尚感興趣，夢想有一天能為年輕女性設計自己的服裝系列。"},{"w":"fashion","p":"n.","d":"a particular way or manner of doing something.","c":"方式、樣子","s":"He completed every task in a systematic fashion, carefully checking each step before moving on to the next one.","t":"他以系統化的方式完成每項任務，在進行下一步之前仔細檢查每個步驟。"},{"w":"fashionable","p":"adj.","d":"following the newest trendy styles cleanly.","c":"時髦的、流行的","s":"The new café quickly became very fashionable among young people because of its stylish interior design and creative menu.","t":"這家新咖啡館因其時尚的室內設計和創意菜單，迅速在年輕人中成為非常流行的地方。"},{"w":"old-fashioned","p":"adj.","d":"no longer modern or popular; using historic setups.","c":"過時的、老式的","s":"Some people think that writing letters by hand is old-fashioned, but others find it more personal and meaningful than email.","t":"有些人認為手寫信件是過時的，但其他人覺得它比電子郵件更個人化、更有意義。"},{"w":"in a peaceful fashion","p":"phr.","d":"completing a protest or meeting with zero violence.","c":"以和平的方式","s":"The residents expressed their concerns about the new road in a peaceful fashion, gathering quietly outside the town hall.","t":"居民們以和平的方式表達他們對新道路的擔憂，安靜地聚集在市政廳外面。"},{"w":"investigate","p":"v.","d":"to carefully examine a crime or problem to find facts.","c":"調查、審查","s":"Journalists spent six months investigating the company's financial records before publishing their report on the fraud.","t":"記者花了六個月調查該公司的財務記錄，然後才發表關於詐欺的報告。"},{"w":"investigation","p":"n.","d":"the official systematic check to find a hidden answer.","c":"調查","s":"The police launched a full investigation into the cause of the fire, interviewing dozens of witnesses over several weeks.","t":"警方對火災原因展開全面調查，在幾週內採訪了數十名目擊者。"},{"w":"investigator","p":"n.","d":"a detective or agent handling fact-finding tasks.","c":"調查員、偵探","s":"The private investigator was hired by the insurance company to look into the suspicious circumstances of the claim.","t":"保險公司聘請了私人調查員，調查這起索賠案的可疑情況。"},{"w":"launch an investigation","p":"phr.","d":"to officially start a deep background check on a case.","c":"展開調查","s":"The government decided to launch an investigation into the safety standards used at the construction site after the accident.","t":"政府決定在事故後對建築工地的安全標準展開調查。"},{"w":"bare","p":"adj.","d":"without any clothes, coverage, or decorations.","c":"赤裸的、空無一物的","s":"The apartment walls were completely bare when they moved in, so they spent the weekend hanging photos and artwork.","t":"他們搬進來時，公寓的牆壁完全空無一物，所以他們花了整個週末掛照片和藝術品。"},{"w":"bare feet","p":"phr.","d":"feet without socks or shoes on walking surfaces.","c":"赤腳、光腳","s":"She walked across the cool grass on bare feet and enjoyed the sensation of the dew between her toes.","t":"她赤腳走過涼爽的草地，享受著露水在腳趾間的感覺。"},{"w":"bare arms","p":"phr.","d":"limbs unprotected by shirt sleeves in cold air.","c":"裸露的手臂","s":"She regretted wearing short sleeves because the air conditioning left her bare arms covered in goosebumps.","t":"她後悔穿了短袖，因為空調讓她裸露的手臂起了雞皮疙瘩。"},{"w":"naked","p":"adj.","d":"fully without clothing garments; in a natural state.","c":"裸體的、赤裸的","s":"The wildlife photographer captured a rare image of a naked mole rat, an unusual species that has almost no fur at all.","t":"這位野生動物攝影師拍下了一張裸鼴鼠的罕見照片，這是一種幾乎沒有毛的不尋常物種。"},{"w":"grin","p":"n.","d":"a wide, broad smile showcasing high happiness.","c":"露齒的笑、大大的微笑","s":"A wide grin spread across his face when he opened his birthday card and found the concert tickets tucked inside.","t":"當他打開生日卡，發現裡面夾著音樂會門票時，他臉上露出了大大的笑容。"},{"w":"grin / grinned / grinned","p":"v.","d":"to smile widely, often showing your teeth.","c":"露齒而笑","s":"She grinned from ear to ear when she heard that she had been selected for the lead role in the school play.","t":"當她聽說自己被選為學校戲劇的主角時，她咧嘴笑得合不攏嘴。"},{"w":"big grin","p":"phr.","d":"a massive facial reflection suggesting fine news.","c":"大大的微笑","s":"He walked into the room with a big grin on his face, and everyone immediately knew he had good news to share.","t":"他帶著大大的微笑走進房間，每個人立刻就知道他有好消息要分享。"},{"w":"laugh","p":"v.","d":"to make sounds showing amusement or mockery.","c":"笑、嘲笑","s":"The comedian's timing was perfect, and the audience began to laugh uncontrollably from the very first minute of the show.","t":"喜劇演員的時機掌握得恰到好處，觀眾從演出的第一分鐘開始就忍不住大笑。"},{"w":"smile","p":"v.","d":"turning up the corners of the mouth silently.","c":"微笑","s":"She gave a warm smile to the nervous new student and invited her to sit at the same lunch table with her friends.","t":"她對緊張的新同學報以溫暖的微笑，並邀請她坐在同一張午餐桌旁。"},{"w":"breathe","p":"v.","d":"to take air into the lungs and send it out again.","c":"呼吸","s":"She stepped outside the crowded room to breathe some fresh air and calm herself down before her big presentation.","t":"她走出擁擠的房間，呼吸一些新鮮空氣，在大型演講前讓自己冷靜下來。"},{"w":"breath","p":"n.","d":"the actual air taken in or blown out during respiration.","c":"呼吸、氣息（名詞）","s":"He was so out of breath after climbing the steep stairs that he had to stop on the landing to rest for a moment.","t":"他爬完陡峭的樓梯後氣喘吁吁，不得不在樓梯平台上停下來休息片刻。"},{"w":"take a deep breath","p":"phr.","d":"filling lungs completely to calm down an upset mind.","c":"深呼吸","s":"The teacher advised students to take a deep breath before starting the exam to help them feel less nervous.","t":"老師建議學生在開始考試前深呼吸，幫助他們感到不那麼緊張。"},{"w":"hold one's breath","p":"phr.","d":"deliberately stopping respiration under water channels.","c":"憋氣、屏息","s":"She learned to hold her breath for over a minute during swimming lessons, which impressed her instructor greatly.","t":"她在游泳課上學會了憋氣超過一分鐘，這讓她的教練印象深刻。"},{"w":"tickle","p":"v.","d":"to touch someone lightly to make them laugh or wiggle.","c":"搔癢、使發癢","s":"The father gently tickled his baby daughter on the tummy, and she burst into the most adorable giggling laughter.","t":"父親輕輕地搔癢他的小女兒的肚子，她爆發出最可愛的咯咯笑聲。"},{"w":"pitch","p":"n.","d":"the high or low level of a musical sound or voice.","c":"音高","s":"The soprano hit an incredibly high pitch in the final chorus that filled the entire concert hall with vibrating sound.","t":"女高音在最後的合唱中達到了令人難以置信的高音，整個音樂廳都充滿了震動的聲音。"},{"w":"pitch","p":"v.","d":"to throw a sports ball toward a player with a bat.","c":"投（球）","s":"The veteran player stepped up to pitch the ball in the final inning, determined to strike the batter out.","t":"這位老將球員在最後一局走上前投球，決心讓打者三振出局。"},{"w":"high pitch","p":"phr.","d":"a sharp voice tone triggered by extreme nervousness.","c":"高音、高音調","s":"Her voice rose to an unusually high pitch when she realized her wallet was missing from her bag on the subway.","t":"當她在地鐵上意識到錢包從包包裡不見了時，她的聲音變得異常高亢。"},{"w":"pitcher","p":"n.","d":"the central baseball player who throws toward home base.","c":"投手","s":"The pitcher threw a perfect game last night, striking out nine batters and allowing zero hits throughout the entire match.","t":"這位投手昨晚投出了完美比賽，三振了九名打者，整場比賽沒有讓對方打出任何安打。"},{"w":"attitude","p":"n.","d":"a settled way of thinking or feeling about an object.","c":"態度、看法","s":"Her positive attitude toward challenges inspired her teammates to keep working hard even when things became very difficult.","t":"她對挑戰的積極態度激勵了隊友們，即使事情變得非常困難時也要繼續努力工作。"},{"w":"positive attitude","p":"phr.","d":"a hopeful mind layout that keeps co-workers happy.","c":"積極的態度","s":"Keeping a positive attitude even during setbacks is one of the most important qualities of successful leaders.","t":"即使在挫折時期保持積極的態度，是成功領導者最重要的品質之一。"},{"w":"attitude toward","p":"phr.","d":"an individual's explicit psychological stance on a topic.","c":"對…的態度","s":"Society's attitude toward mental health has changed significantly over the past decade, with more people seeking help.","t":"過去十年來，社會對心理健康的態度發生了顯著變化，越來越多的人尋求幫助。"},{"w":"stress","p":"n.","d":"great worry or mental strain caused by a tough job.","c":"壓力、緊張","s":"She found that regular exercise helped her manage stress much more effectively than any other method she had tried.","t":"她發現規律運動比她嘗試過的任何其他方法都更能有效幫助她管理壓力。"},{"w":"stress","p":"v.","d":"to emphasize a point; to cause worry to a peer.","c":"強調、使緊張","s":"The coach stressed the importance of warming up properly before every training session to avoid muscle injuries.","t":"教練強調了在每次訓練課前適當熱身的重要性，以避免肌肉損傷。"},{"w":"stressful","p":"adj.","d":"causing a huge wave of ongoing anxiety and worry.","c":"壓力很大的","s":"Working in the emergency department is incredibly stressful, but the nurses and doctors say it is also very rewarding.","t":"在急診部門工作壓力非常大，但護士和醫生表示這也非常有成就感。"},{"w":"be stressed out","p":"phr.","d":"feeling completely crushed by taking on excess duties.","c":"壓力過大的、筋疲力竭的","s":"She was completely stressed out after juggling three deadlines at once and barely slept for two days.","t":"在同時應付三個截止日期後，她壓力過大，幾乎兩天沒睡。"},{"w":"pressure","p":"n.","d":"a heavy physical or social load pushing against you.","c":"壓力","s":"Students often feel enormous pressure during exam season, especially when parents have high expectations of their results.","t":"學生在考試季節常常感到巨大的壓力，尤其是當父母對他們的成績有很高期望時。"},{"w":"shelter","p":"n.","d":"a building structure providing safety from wind or harm.","c":"庇護所、避難處","s":"The hikers found a small wooden shelter near the top of the mountain and waited there until the storm had passed.","t":"登山者在山頂附近找到一個小木屋庇護所，在那裡等待暴風雨過去。"},{"w":"animal shelter","p":"phr.","d":"a temporary home keeping lost dogs safe before adoption.","c":"動物收容所","s":"She adopted her dog from the local animal shelter and gave him a loving home after he had been there for months.","t":"她從當地動物收容所領養了她的狗，在牠在那裡待了幾個月後給了牠一個充滿愛的家。"},{"w":"take shelter","p":"phr.","d":"entering a secure room to avoid a violent storm track.","c":"避難、尋求庇護","s":"When the typhoon warning was issued, residents were advised to take shelter and stay indoors until it had passed.","t":"颱風警報發布後，居民被建議避難並待在室內，直到颱風過去。"},{"w":"calm","p":"adj.","d":"peaceful, quiet, and not showing any panic or worry.","c":"冷靜的、平靜的","s":"Despite the chaos around her, she remained completely calm and gave clear instructions to everyone in the room.","t":"儘管周圍一片混亂，她仍然保持完全冷靜，並向房間裡的每個人發出清晰的指示。"},{"w":"calm","p":"v.","d":"to make a wild animal or panicked peer peaceful.","c":"使平靜、使鎮定","s":"The nurse spoke in a soft, gentle voice to calm the anxious child before the doctor came in to examine him.","t":"醫生進來檢查之前，護士用柔和溫和的聲音讓焦慮的孩子平靜下來。"},{"w":"calm down","p":"phr.","d":"taking a minute to lower heart rates after bad news.","c":"冷靜下來、鎮定下來","s":"She took several deep breaths to calm down after the argument and then went back to have a rational conversation.","t":"爭論後她深呼吸幾次讓自己冷靜下來，然後回去進行理性的對話。"},{"w":"calm lake","p":"phr.","d":"a flat water surface tracking zero waves or wind.","c":"平靜的湖面","s":"The kayakers set off early in the morning when the calm lake was perfectly still and reflected the sunrise.","t":"皮划艇運動員在清晨出發，那時平靜的湖面完全靜止，映照著日出。"},{"w":"still","p":"adj.","d":"completely stationary; tracking zero movements.","c":"靜止的、一動不動的","s":"The deer froze and stood completely still when it heard the snap of a twig nearby in the quiet forest.","t":"鹿在安靜的森林中聽到附近樹枝折斷的聲音時，僵住了，完全一動不動地站著。"},{"w":"stay still","p":"phr.","d":"a medical reminder telling patients to stop wiggling.","c":"保持不動","s":"The technician asked the patient to stay still during the scan so that the images would come out clearly.","t":"技術員要求病人在掃描期間保持不動，以便圖像能清晰地呈現。"},{"w":"bond","p":"n.","d":"a close connection or deep friendship linking peers.","c":"情感紐帶、緊密關係","s":"The shared experience of studying abroad created a strong bond between the students that lasted for many years.","t":"在國外學習的共同經歷在學生之間建立了持久多年的強烈情感紐帶。"},{"w":"bond","p":"v.","d":"to develop a close link; to glue objects together.","c":"建立關係、黏合","s":"The team went on a weekend retreat to bond and get to know each other better before the big project began.","t":"團隊在大型項目開始前進行了週末靜修，以建立關係並更好地相互了解。"},{"w":"strong bond","p":"phr.","d":"an unbreakable connection with a best family peer.","c":"緊密的關係","s":"The twins shared a strong bond that meant they always seemed to know what the other one was thinking.","t":"這對雙胞胎分享著一種緊密的關係，這意味著他們似乎總是知道對方在想什麼。"},{"w":"bonding","p":"n.","d":"the active process of developing closeness with pets.","c":"培養感情、凝聚力","s":"The puppy bonding programme at the hospital allowed patients to interact with dogs and reduce their anxiety.","t":"醫院的幼犬培養感情計劃讓病人與狗互動，減少他們的焦慮。"},{"w":"seek / sought / sought","p":"v.","d":"to search for or try to find a specialized entry.","c":"尋找、尋求","s":"Many young graduates seek opportunities abroad because they believe it will broaden their career prospects significantly.","t":"許多年輕畢業生在海外尋求機會，因為他們相信這將大幅拓寬他們的職業前景。"},{"w":"seek to","p":"phr.","d":"trying hard to encourage students to read for fun.","c":"試圖去…、力圖","s":"The new library programme seek to make reading more enjoyable for children by hosting weekly storytelling events.","t":"新的圖書館計劃力圖通過每週舉辦說故事活動，讓孩子們更享受閱讀。"},{"w":"seek help","p":"phr.","d":"calling an expert to claim support during a crisis.","c":"尋求幫助","s":"It takes courage to seek help when you are struggling mentally, but it is always the right thing to do.","t":"當你在心理上掙扎時尋求幫助需要勇氣，但這始終是正確的事情。"},{"w":"depression","p":"n.","d":"a psychological state of deep sadness and low energy.","c":"憂鬱症、沮喪","s":"Many people suffer from depression in silence because they are afraid of being judged or misunderstood by others.","t":"許多人默默遭受憂鬱症的折磨，因為他們害怕被別人評判或誤解。"},{"w":"depress","p":"v.","d":"to make someone feel sad, tired, or helpless.","c":"使沮喪、使憂鬱","s":"The constant grey skies and cold rain during November always seemed to depress her and drain her of energy.","t":"十一月持續的陰天和冷雨似乎總是讓她感到沮喪，消耗她的精力。"},{"w":"depressed","p":"adj.","d":"experiencing an ongoing mental low due to failure.","c":"感到沮喪的、憂鬱的","s":"He felt deeply depressed after losing his job and found it hard to get out of bed or engage with everyday life.","t":"失業後他感到深深的沮喪，很難從床上起來或投入日常生活。"},{"w":"economic depression","p":"phr.","d":"a severe historical era tracking zero corporate trades.","c":"經濟大蕭條","s":"The economic depression of the 1930s caused widespread unemployment and poverty across many countries worldwide.","t":"1930年代的經濟大蕭條在全球許多國家造成了普遍的失業和貧困。"}]},{"unit":17,"theme":"annual – remain cheerful","cards":[{"w":"annual","p":"adj.","d":"happening or done once every single year.","c":"每年的、年度的","s":"The school holds its annual sports day in October, and students spend weeks training for their chosen events.","t":"學校在十月舉行年度運動會，學生們花了數週時間為他們選擇的項目進行訓練。"},{"w":"annual sale","p":"phr.","d":"a yearly store event driving massive arrival lines.","c":"年度大拍賣","s":"She saved up for months just to attend the department store's annual sale, where discounts reached up to seventy percent.","t":"她存了幾個月的錢，就是為了參加百貨公司的年度大拍賣，折扣高達七折。"},{"w":"turn out","p":"phr.","d":"to arrive or assemble at an event to participate.","c":"出席、結果是","s":"Hundreds of residents turned out to support the charity marathon despite the cold and rainy weather conditions.","t":"儘管天氣寒冷多雨，數百名居民仍然出席支持慈善馬拉松。"},{"w":"turn out to be","p":"phr.","d":"proving to be something else unexpected in the end.","c":"結果竟然是…","s":"The film that nobody expected much from turn out to be one of the biggest box office hits of the entire year.","t":"沒有人對這部電影抱有太大期望，結果它竟然是全年最大的票房大片之一。"},{"w":"admire","p":"v.","d":"to respect and approve of someone's talents or skill.","c":"欽佩、欣賞、讚賞","s":"She has always admired her grandmother's patience and kindness, and hopes to develop those same qualities herself.","t":"她一直欽佩祖母的耐心和善良，希望自己也能培養出這些相同的品質。"},{"w":"admirable","p":"adj.","d":"deserving deep respect; tracking flawless traits.","c":"令人欽佩的、值得讚賞的","s":"Her dedication to volunteering every single weekend despite her busy schedule is truly admirable and inspires everyone around her.","t":"儘管行程繁忙，她仍然每個週末堅持做義工，這真的令人欽佩，並激勵了周圍的每個人。"},{"w":"admiration","p":"n.","d":"a feeling of deep respect and approval for a peer.","c":"欽佩、讚賞","s":"She looked at the stunning mountain view with deep admiration and felt grateful to have made the difficult climb.","t":"她帶著深深的欽佩欣賞著令人嘆為觀止的山景，並為自己完成了艱難的攀登而感到感激。"},{"w":"wrap","p":"v.","d":"to cover something completely by folding cloth around it.","c":"包裹、纏繞","s":"She carefully wrapped each fragile ornament in tissue paper before placing it in the box for storage.","t":"她在將每個易碎裝飾品放入儲物箱之前，仔細地用薄棉紙包裹起來。"},{"w":"wrap up","p":"phr.","d":"to bring a hard day's work to a successful finish.","c":"結束、圓滿完成（工作等）","s":"Let's wrap up the meeting in the next ten minutes so everyone can leave before the evening rush hour.","t":"讓我們在接下來的十分鐘內結束會議，這樣每個人都可以在晚高峰前離開。"},{"w":"wrap a scarf","p":"phr.","d":"twisting wool around the neck to withstand cold air.","c":"圍圍巾","s":"Her mother reminded her to wrap a scarf around her neck tightly before heading out into the freezing winter morning.","t":"媽媽提醒她在外出到寒冷的冬天早晨之前，要把圍巾緊緊圍在脖子上。"},{"w":"in advance","p":"phr.","d":"before a particular time or event; beforehand.","c":"預先、事先","s":"Tickets for the popular concert must be booked well in advance, as they tend to sell out within hours of release.","t":"這場熱門音樂會的門票必須提前預訂，因為它們往往在發售後幾小時內就售罄。"},{"w":"advance","p":"v.","d":"to move forward or a step forward in development.","c":"前進、進步","s":"Technology continues to advance at an incredible pace, changing the way people work, communicate, and spend their time.","t":"技術繼續以令人難以置信的速度進步，改變著人們工作、溝通和消磨時間的方式。"},{"w":"advanced","p":"adj.","d":"using modern complex technology or high level math.","c":"先進的、高級的","s":"She enrolled in an advanced mathematics course at the university to deepen her understanding of statistics and data analysis.","t":"她在大學選修了一門高級數學課程，以加深她對統計學和數據分析的理解。"},{"w":"advancement","p":"n.","d":"an improvement or promotion inside a corporate role.","c":"提升、前進、進步","s":"Rapid advancement in medical technology has made it possible to detect serious diseases much earlier than ever before.","t":"醫療技術的快速進步使得比以往更早發現嚴重疾病成為可能。"},{"w":"expert","p":"n.","d":"a person with high knowledge or skill in a field.","c":"專家","s":"The hospital brought in a leading expert in cardiology to perform the complex surgery that local doctors could not do.","t":"醫院請來了心臟病學的頂尖專家，進行當地醫生無法完成的複雜手術。"},{"w":"expert","p":"adj.","d":"tracking massive professional mastery over a task.","c":"專家的、內行的","s":"She received expert guidance from a professional chef who taught her how to prepare traditional French sauces correctly.","t":"她從一位職業廚師那裡獲得了專業指導，教她如何正確製作傳統法式醬汁。"},{"w":"expert builder","p":"phr.","d":"a seasoned master who solves foundational house leaks.","c":"建築專家","s":"The homeowner hired an expert builder to fix the structural damage caused by years of water leaking through the roof.","t":"房主聘請了一位建築專家來修復多年屋頂漏水造成的結構性損壞。"},{"w":"expert at","p":"phr.","d":"an individual highly skilled at baking top pizza dishes.","c":"擅長…的專家","s":"She is an absolute expert at making sourdough bread, and people come from across the city to buy her loaves.","t":"她是製作酸麵團麵包的絕對專家，人們從城市各地趕來購買她的麵包。"},{"w":"expertise","p":"n.","d":"high specialized knowledge mastered over years of work.","c":"專門知識、專業技能","s":"Her expertise in environmental law made her the ideal candidate to lead the international climate negotiations.","t":"她在環境法方面的專業技能使她成為領導國際氣候談判的理想人選。"},{"w":"instrument","p":"n.","d":"an object used for producing beautiful music tracks.","c":"樂器","s":"Learning to play a musical instrument as a child is known to improve memory, focus, and creative thinking skills.","t":"據說兒時學習演奏樂器可以提高記憶力、專注力和創造性思維能力。"},{"w":"instrument","p":"n.","d":"a hand tool used for writing or precise science tasks.","c":"儀器、工具（書寫等）","s":"The surgeon carefully selected the surgical instrument needed for the operation and made sure everything was fully sterilised.","t":"外科醫生仔細選擇了手術所需的外科器械，並確保所有器械都已完全消毒。"},{"w":"musical instrument","p":"phr.","d":"a device like a piano or guitar kept inside schools.","c":"樂器","s":"The school donated several second-hand musical instruments to the community centre so that local children could learn music.","t":"學校向社區中心捐贈了幾件二手樂器，讓當地兒童能夠學習音樂。"},{"w":"writing instrument","p":"phr.","d":"tool units like pens or pencils used to complete tests.","c":"書寫工具","s":"Students are reminded to bring their own writing instrument to the examination hall as none will be provided on the day.","t":"提醒學生自行帶書寫工具到考場，考試當天不提供任何書寫工具。"},{"w":"instrumental","p":"adj.","d":"being a highly important factor in causing a result.","c":"起重要作用的、有幫助的","s":"She was instrumental in securing the funding that allowed the community garden project to go ahead after years of planning.","t":"她在確保資金方面起了重要作用，使社區花園項目在多年規劃後得以繼續推進。"},{"w":"decoration","p":"n.","d":"items added to a room to make it look attractive.","c":"裝飾品、裝飾","s":"The students made paper decorations to hang around the classroom before the school's end-of-year celebration party.","t":"學生們製作了紙質裝飾品，在學校年終慶祝派對前掛在教室周圍。"},{"w":"decorate","p":"v.","d":"to paint or add festive items to a bedroom space.","c":"裝飾、布置","s":"The family spent the whole Saturday morning decorating the house with fairy lights and wreaths for the holiday season.","t":"全家人花了整個週六早上用串燈和花環裝飾房子，迎接節日季節。"},{"w":"christmas decorations","p":"phr.","d":"lights and ornaments put up by children in December.","c":"聖誕裝飾","s":"The children helped put up the christmas decorations on the first weekend of December and were very proud of the result.","t":"孩子們在十二月的第一個週末幫忙掛上聖誕裝飾，對結果感到非常自豪。"},{"w":"decorative","p":"adj.","d":"designed purely to look pretty rather than be useful.","c":"裝飾性的","s":"The decorative tiles on the kitchen wall added a splash of colour to the room without serving any practical function.","t":"廚房牆上的裝飾性瓷磚為房間增添了一抹色彩，但沒有任何實際功能。"},{"w":"crisp","p":"adj.","d":"pleasantly cool, dry, and fresh (describing weather).","c":"涼爽的、清新的（空氣等）","s":"The morning air was crisp and cool as they set off on their hike through the autumn forest just after sunrise.","t":"日出後不久，他們出發在秋天的森林中徒步時，清晨的空氣清新涼爽。"},{"w":"crisp","p":"adj.","d":"hard, dry, and easily broken in a pleasant way.","c":"酥脆的（食物等）","s":"She bit into the crisp apple with a satisfying crunch and enjoyed the sweet, refreshing juice that followed.","t":"她咬了一口酥脆的蘋果，發出令人滿足的嘎吱聲，享受著隨之而來的甜蜜清爽果汁。"},{"w":"crispy","p":"adj.","d":"tracking a perfect crunchy texture from being fried.","c":"酥脆的","s":"The golden, crispy skin of the roast duck was the highlight of the meal and everyone reached for extra pieces.","t":"烤鴨金黃酥脆的皮是這頓飯的亮點，每個人都伸手要更多。"},{"w":"crispy chicken","p":"phr.","d":"poultry meat fried to perfection and dusted with spices.","c":"脆皮炸雞","s":"The restaurant is famous for its crispy chicken, which is marinated for twenty-four hours before being deep fried.","t":"這家餐廳以其脆皮炸雞聞名，炸雞在油炸前醃製了二十四小時。"},{"w":"crisp air","p":"phr.","d":"the refreshing scent of autumn morning breezes.","c":"清新的空氣","s":"She opened her bedroom window to breathe in the crisp air of the countryside early on an autumn morning.","t":"她在秋天早晨打開臥室窗戶，呼吸農村的清新空氣。"},{"w":"beam","p":"n.","d":"a narrow line of light shining from a star or laser.","c":"光線、光束","s":"A single beam of sunlight broke through the storm clouds and lit up a small patch of the grey ocean below.","t":"一道陽光穿破暴風雲，照亮了下方灰色海洋的一小片區域。"},{"w":"beams of light","p":"phr.","d":"strange bright streaks observed up in the night sky.","c":"束光、光芒","s":"Visitors to the northern regions were treated to spectacular beams of light dancing across the night sky.","t":"前往北部地區的遊客欣賞到了壯觀的束光在夜空中舞動的景象。"},{"w":"entire","p":"adj.","d":"whole or complete, with absolutely zero parts missing.","c":"全部的、整個的","s":"She read the entire novel in one sitting because the plot was so gripping that she simply could not put it down.","t":"她一口氣讀完了整本小說，因為情節太引人入勝，她根本無法放下書本。"},{"w":"entire pizza","p":"phr.","d":"eating a whole baked pie alone without sharing.","c":"整塊披薩","s":"After the long hike, he was so hungry that he ordered an entire pizza and finished every single slice himself.","t":"長途徒步後，他非常飢餓，點了一整塊披薩，並自己吃完了每一片。"},{"w":"explore","p":"v.","d":"to travel around an unknown place to learn about it.","c":"探索、探險、研究","s":"During their gap year, they decided to explore Southeast Asia by travelling through six countries on a tight budget.","t":"在間隔年期間，他們決定以有限的預算穿越六個國家，探索東南亞。"},{"w":"exploration","p":"n.","d":"the active traversal of deep caves or outer space.","c":"探索、探查","s":"The exploration of deep-sea environments has revealed hundreds of new species that science had never documented before.","t":"對深海環境的探索揭示了數百個科學從未記錄過的新物種。"},{"w":"explorer","p":"n.","d":"a brave traveler mapping out hidden wild zones.","c":"探險家","s":"The explorer spent three years mapping uncharted rainforest territory and discovered several previously unknown rivers.","t":"這位探險家花了三年時間繪製未知的雨林地圖，並發現了幾條以前未知的河流。"},{"w":"explore a cave","p":"phr.","d":"divers moving through dangerous deep water channels.","c":"探索洞穴","s":"The group hired an experienced guide to help them safely explore a cave deep in the jungle during their trip.","t":"這個小組聘請了一位有經驗的導遊，幫助他們在旅行期間安全探索叢林深處的洞穴。"},{"w":"explore how","p":"phr.","d":"a study checking how sleep logs impact school grades.","c":"探究、研究如何…","s":"Researchers are keen to explore how technology can be used to support students with different learning needs.","t":"研究人員急於探究技術如何能夠支持有不同學習需求的學生。"},{"w":"fee","p":"n.","d":"an amount of money paid for a specific service or entry.","c":"費用、服務費、會費","s":"The membership fee for the fitness centre covers unlimited access to all classes and equipment throughout the year.","t":"健身中心的會員費涵蓋全年無限次進入所有課程和設備的機會。"},{"w":"movie club fee","p":"phr.","d":"a forty dollar currency requirement to join a group.","c":"電影俱樂部會費","s":"The movie club fee is very affordable and covers the cost of all screenings and events for one full year.","t":"電影俱樂部的會費非常實惠，涵蓋整整一年所有放映和活動的費用。"},{"w":"admission fee","p":"phr.","d":"cash required at a front gate to enter theme parks.","c":"門票、入場費","s":"The museum charges a small admission fee for adults, but children under twelve can always enter completely free of charge.","t":"博物館對成人收取小額入場費，但十二歲以下的兒童始終可以完全免費入場。"},{"w":"introduction","p":"n.","d":"the opening chapter of a book providing base facts.","c":"序言、引言、導論","s":"The introduction of the textbook gave students a clear overview of what they would study throughout the entire academic year.","t":"教科書的導論讓學生對整個學年將學習的內容有了清晰的概述。"},{"w":"introduction","p":"n.","d":"the presentation of a person by name to a crowd.","c":"介紹","s":"The host made a warm introduction before each speaker came on stage, highlighting their achievements and background.","t":"主持人在每位演講者上台前做了熱情的介紹，強調了他們的成就和背景。"},{"w":"introduce","p":"v.","d":"to present a peer or bring a new plant line to a town.","c":"介紹、引進","s":"She was nervous about having to introduce herself to the new class on the first day, but everyone was very welcoming.","t":"她對第一天必須向新班級自我介紹感到緊張，但每個人都非常熱情歡迎。"},{"w":"clear introduction","p":"phr.","d":"an easy textbook chapter explaining historic roots.","c":"清晰的介紹","s":"The professor gave a clear introduction to the topic that made even the most complex concepts easy to understand.","t":"教授對這個話題做了清晰的介紹，使即使是最複雜的概念也變得容易理解。"},{"w":"make the introductions","p":"phr.","d":"the master of ceremonies naming guests before a show.","c":"做介紹、引見","s":"As the host, it was her job to make the introductions and ensure that all the guests knew who they were sitting next to.","t":"作為主持人，她的工作是做介紹，確保所有賓客都知道他們旁邊坐的是誰。"},{"w":"changeable","p":"adj.","d":"often shifting; able to be altered easily.","c":"易變的、可改變的","s":"Spring weather in this region is very changeable, so visitors are always advised to pack both a raincoat and sunscreen.","t":"這個地區的春季天氣非常多變，所以建議遊客始終攜帶雨衣和防曬霜。"},{"w":"change","p":"v.","d":"to make an asset different; a shift in conditions.","c":"改變","s":"The sudden change in weather forced the outdoor event to be moved indoors at very short notice.","t":"天氣的突然變化迫使戶外活動在很短的時間內移至室內舉行。"},{"w":"changeable plans","p":"phr.","d":"next week's schedule track that can be rescheduled.","c":"可變動的計畫","s":"Our changeable plans for the weekend depend entirely on the weather forecast, so we will decide on Saturday morning.","t":"我們週末的可變動計畫完全取決於天氣預報，所以我們將在週六早上做決定。"},{"w":"challenge","p":"n.","d":"a difficult task testing an individual's abilities.","c":"挑戰","s":"Moving to a new country is a huge challenge, but it also offers incredible opportunities to grow and learn.","t":"搬到一個新國家是一個巨大的挑戰，但它也提供了令人難以置信的成長和學習機會。"},{"w":"challenge","p":"v.","d":"to test someone's limits or invite them to compete.","c":"挑戰、考驗","s":"The coach challenged his players to push beyond their comfort zones and attempt techniques they had never tried before.","t":"教練挑戰球員們超越自己的舒適圈，嘗試他們以前從未嘗試過的技術。"},{"w":"challenging","p":"adj.","d":"tough but highly interesting; demanding hard work.","c":"具挑戰性的","s":"She finds her new role very challenging but also incredibly rewarding because every day brings a different problem to solve.","t":"她發現自己的新職位非常具有挑戰性，但也極為有成就感，因為每天都有不同的問題需要解決。"},{"w":"face a challenge","p":"phr.","d":"a sports team gearing up to play a dominant rival.","c":"面臨挑戰","s":"Every athlete must face a challenge at some point in their career, and how they respond often defines them.","t":"每位運動員在職業生涯的某個時候都必須面臨挑戰，他們的應對方式往往定義了他們。"},{"w":"melt","p":"v.","d":"to turn from a solid into a liquid state via heat.","c":"融化、熔化","s":"The snow on the mountain began to melt in early spring, causing the river below to rise significantly.","t":"山上的雪在早春開始融化，導致下方的河流顯著上漲。"},{"w":"ice cream melts","p":"phr.","d":"a dairy dessert turning into fluid under hot sun.","c":"冰淇淋融化","s":"Ice cream melts very quickly on a hot summer day, so it is best to eat it in a shaded spot right away.","t":"冰淇淋在炎熱的夏天融化得非常快，所以最好立刻在陰涼的地方吃掉它。"},{"w":"temperature","p":"n.","d":"a measurement of how hot or cold a place or body is.","c":"溫度、體溫","s":"The nurse took the patient's temperature and found it was slightly above normal, so she called the doctor immediately.","t":"護士量了病人的體溫，發現略高於正常值，於是立即叫了醫生。"},{"w":"high temperature","p":"phr.","d":"a diagnostic fever spike shown on medical checks.","c":"高溫、發燒","s":"The child was kept home from school because of a high temperature that had not come down despite two days of rest.","t":"孩子因為持續兩天休息後仍未退燒而留在家中沒有上學。"},{"w":"check temperature","p":"phr.","d":"scanning climate charts before choosing daily clothes.","c":"檢查溫度","s":"She always check temperature on her weather app before getting dressed so she knows how many layers to wear.","t":"她在穿衣服之前總是在天氣應用程式上查看溫度，以便知道要穿多少層衣物。"},{"w":"adjust","p":"v.","d":"to change something slightly to make it work better.","c":"調整、調節","s":"She had to adjust her study schedule after joining the school choir, which rehearsed three times a week.","t":"加入每週排練三次的學校合唱團後，她不得不調整自己的學習計劃。"},{"w":"adjustment","p":"n.","d":"a small modification made to a setting or machine.","c":"調整","s":"Moving to a new city required several adjustments to her daily routine, including finding new places to shop and exercise.","t":"搬到新城市需要對她的日常生活進行幾項調整，包括找到新的購物和運動場所。"},{"w":"adjust the speed","p":"phr.","d":"turning a dial to control a washing machine cycle.","c":"調節速度","s":"The cycling instructor asked participants to adjust the speed on their bikes to match the pace of the music.","t":"單車教練要求參加者調節自行車速度，以配合音樂的節奏。"},{"w":"make adjustments to","p":"phr.","d":"altering corporate strategy to fit current markets.","c":"對…做出調整","s":"After reviewing the feedback, the team decided to make adjustments to the original design before the final launch.","t":"在審查反饋後，團隊決定在最終發布前對原始設計做出調整。"},{"w":"absorb","p":"v.","d":"to take in liquid, gas, or data completely.","c":"吸收","s":"A sponge can absorb many times its own weight in water, making it very useful for cleaning up large spills quickly.","t":"海綿能吸收比自身重量多許多倍的水，使其在快速清理大量溢出物時非常有用。"},{"w":"rice absorbed water","p":"phr.","d":"grain units soaking up fluid until ready to eat.","c":"米吸收了水分","s":"After thirty minutes of soaking, the rice absorbed water fully and was ready to be cooked on the stove.","t":"浸泡三十分鐘後，米充分吸收了水分，準備好在爐子上烹煮。"},{"w":"absorption","p":"n.","d":"the biological process of taking in nutrients cleanly.","c":"吸收（名詞）","s":"Vitamin D plays a crucial role in the absorption of calcium, which is essential for maintaining strong and healthy bones.","t":"維生素D在鈣的吸收中起著至關重要的作用，這對維持強健的骨骼至關重要。"},{"w":"surrounding","p":"adj.","d":"existing entirely around a central point or object.","c":"周圍的、環繞的","s":"The forest fire quickly spread to the surrounding villages, and residents were evacuated within hours of the alarm.","t":"森林大火迅速蔓延到周圍的村莊，居民在警報發出後數小時內被疏散。"},{"w":"surround","p":"v.","d":"to move all the way around an entry to close it in.","c":"環繞、圍繞","s":"Tall pine trees surrounded the small mountain cabin, providing natural shade and shelter from the cold winter winds.","t":"高大的松樹環繞著山上的小木屋，提供了天然的陰涼和抵禦寒冷冬風的庇護。"},{"w":"surroundings","p":"n.","d":"the physical environment or conditions around you.","c":"環境、周圍事物（固定複數）","s":"It took her a few weeks to get used to her new surroundings after moving to the countryside from the busy city.","t":"從繁忙的城市搬到農村後，她花了幾週時間才適應新的環境。"},{"w":"surrounding land","p":"phr.","d":"corporate fields located right next to a home asset.","c":"周圍的土地","s":"The developer bought the surrounding land next to the old factory and plans to build a new residential community.","t":"開發商購買了舊工廠旁邊的周圍土地，計劃建設新的住宅社區。"},{"w":"environmental","p":"adj.","d":"relating to the natural world of air, water, and land.","c":"環境的、保護環境的","s":"The company has made several environmental commitments, including reducing carbon emissions by fifty percent within ten years.","t":"該公司做出了幾項環境承諾，包括在十年內將碳排放量減少百分之五十。"},{"w":"environment","p":"n.","d":"the natural conditions or context inside a zone.","c":"環境","s":"Protecting the natural environment is everyone's responsibility, not just governments and large corporations.","t":"保護自然環境是每個人的責任，而不只是政府和大型企業的責任。"},{"w":"environmentally friendly","p":"phr.","d":"taking a local transit bus to reduce fuel emissions.","c":"環保的、對環境友善的","s":"More consumers are choosing environmentally friendly products, forcing companies to change how they manufacture and package goods.","t":"越來越多的消費者選擇環保產品，迫使公司改變他們製造和包裝商品的方式。"},{"w":"environmental law","p":"phr.","d":"state rules controlling corporate factory waste outputs.","c":"環境保護法","s":"The firm was fined heavily for violating environmental law by dumping chemical waste into the river near the factory.","t":"該公司因向工廠附近的河流傾倒化學廢料而違反環境保護法，被重罰。"},{"w":"impact","p":"n.","d":"a powerful effect or influence on a scenario state.","c":"影響、衝擊","s":"The new highway had a significant impact on the local economy, making it much easier for businesses to transport goods.","t":"新高速公路對當地經濟產生了顯著的影響，使企業運輸貨物變得更加容易。"},{"w":"impact","p":"v.","d":"to produce a clear, notable change in something.","c":"影響、對…產生衝擊","s":"Rising sea levels are beginning to impact coastal communities around the world, threatening homes and livelihoods.","t":"海平面上升開始影響世界各地的沿海社區，威脅著家園和生計。"},{"w":"impression","p":"n.","d":"an opinion or feeling formed about a peer or event.","c":"印象、想法","s":"She made an excellent first impression at the job interview by arriving early, dressing professionally, and speaking clearly.","t":"她在工作面試中通過提前到達、穿著專業和清晰表達，給人留下了出色的第一印象。"},{"w":"impress","p":"v.","d":"to make someone admire or notice your top talents.","c":"給…留下深刻印象、使欽佩","s":"The young chef managed to impress the panel of judges with her creative dish that combined local and international flavours.","t":"這位年輕廚師以融合本地和國際風味的創意菜餚，成功給評委小組留下了深刻印象。"},{"w":"impressive","p":"adj.","d":"making a deep impact due to being excellent or large.","c":"令人印象深刻的、出眾的","s":"The student delivered an impressive speech that left the entire audience silent for a moment before they burst into applause.","t":"這位學生發表了一篇令人印象深刻的演講，讓整個觀眾沉默了片刻，然後爆發出掌聲。"},{"w":"get the impression","p":"phr.","d":"forming an internal feeling that a peer likes you.","c":"得到…的印象、覺得","s":"She get the impression that her manager was not happy with her work, even though nothing was said directly.","t":"她得到了經理對她的工作不滿意的印象，儘管沒有直接說出來任何話。"},{"w":"remain","p":"v.","d":"to stay in the same place or keep a specific state.","c":"保持、依然、留下","s":"Despite the heavy criticism from online reviewers, the restaurant remained popular with its loyal local customers.","t":"儘管受到網路評論者的嚴厲批評，這家餐廳仍然受到其忠實本地顧客的歡迎。"},{"w":"remains","p":"n.","d":"the pieces left behind after an object breaks down.","c":"剩餘物、遺跡、遺體（複數）","s":"The archaeologists carefully excavated the remains of the ancient settlement, which had been buried for over two thousand years.","t":"考古學家們仔細挖掘了這個已被埋藏兩千多年的古代聚落的遺跡。"},{"w":"remain cheerful","p":"phr.","d":"keeping a happy face despite recent operational trouble.","c":"保持樂觀/開朗","s":"She managed to remain cheerful throughout the difficult period and her positive energy helped lift the whole team.","t":"她在困難時期設法保持樂觀，她積極的能量幫助提振了整個團隊的士氣。"}]},{"unit":18,"theme":"journey – guided us to","cards":[{"w":"journey","p":"n.","d":"an act of traveling from one long distance to another.","c":"旅程、旅行","s":"The journey from the capital city to the remote village took over twelve hours by bus along winding mountain roads.","t":"從首都到偏遠村莊的旅程沿著蜿蜒的山路乘公共汽車需要十二個多小時。"},{"w":"journey","p":"v.","d":"to travel across a long distance or wide region.","c":"旅行、徒步旅行","s":"The explorers journeyed for three weeks through dense jungle before finally reaching the ancient ruins they sought.","t":"探險家們在茂密的叢林中旅行了三週，最終到達了他們尋找的古代遺跡。"},{"w":"journal","p":"n.","d":"a daily diary book recording real personal events.","c":"日誌、期刊","s":"She kept a detailed travel journal during her year abroad, recording her observations, feelings, and daily experiences.","t":"她在海外那一年保留了詳細的旅行日誌，記錄她的觀察、感受和日常經歷。"},{"w":"journey around the world","p":"phr.","d":"a global travel track starting from a base city.","c":"環球旅程","s":"His journey around the world took two years and included stops in over thirty countries across five continents.","t":"他的環球旅程花了兩年時間，途經五大洲三十多個國家。"},{"w":"journeyed up the river","p":"phr.","d":"a group traveling on water paths across three days.","c":"沿河逆流而上","s":"The research team journeyed up the river for four days before reaching the remote wetland habitat they were studying.","t":"研究團隊沿河逆流而上行駛了四天，才到達他們正在研究的偏遠濕地棲息地。"},{"w":"travel","p":"v.","d":"the general activity of moving across distinct towns.","c":"旅遊、旅行（總稱）","s":"She loves to travel and has visited over twenty countries, always choosing to stay with local families rather than hotels.","t":"她喜歡旅行，已經去過二十多個國家，總是選擇與當地家庭住在一起，而不是住酒店。"},{"w":"trip","p":"n.","d":"a brief explicit journey to a town and back again.","c":"出遊、趟旅行（短程等）","s":"The school organised a day trip to the science museum for all students in the seventh grade next Thursday.","t":"學校為七年級的所有學生組織了下週四前往科學博物館的一日遊。"},{"w":"wild","p":"adj.","d":"living or growing in nature; not managed by humans.","c":"野生的、未馴化的","s":"Wild animals in the national park are protected by law, and visitors are strictly forbidden from feeding them.","t":"國家公園中的野生動物受法律保護，嚴格禁止遊客餵食牠們。"},{"w":"wild","p":"n.","d":"a natural state or region untouched by urban growth.","c":"荒野、自然界","s":"The documentary showed the challenges that young elephants face when learning to survive in the wild.","t":"這部紀錄片展示了年輕象在學習在荒野中生存時所面臨的挑戰。"},{"w":"wildlife","p":"n.","d":"wild animals, birds, and insects living in a zone.","c":"野生生物","s":"The region is home to incredibly diverse wildlife, including rare birds, reptiles, and dozens of mammal species.","t":"這個地區擁有極其多樣的野生生物，包括稀有鳥類、爬行動物和數十種哺乳動物。"},{"w":"go wild","p":"phr.","d":"fans screaming with extreme excitement after a win.","c":"瘋狂、失控、雀躍","s":"The crowd go wild when the home team scored the winning goal in the final seconds of the match.","t":"當主隊在比賽最後幾秒鐘打進致勝球時，人群雀躍狂歡。"},{"w":"in the wild","p":"phr.","d":"locating fresh strawberries growing deep inside forests.","c":"在野外、在自然環境中","s":"These wolves were born in captivity but are now being prepared for release back to live in the wild.","t":"這些狼出生於人工飼養環境，現在正在為放歸野外做準備。"},{"w":"return to the wild","p":"phr.","d":"releasing a pet bird back into its natural habitat.","c":"放歸大自然","s":"After months of rehabilitation, the injured eagle was strong enough to return to the wild.","t":"經過數月的康復治療，受傷的老鷹已經足夠強壯，可以放歸大自然。"},{"w":"overseas","p":"adv.","d":"in or to a foreign country across ocean channels.","c":"在海外、向海外","s":"Her company sent her overseas for a two-year assignment in Singapore, which was both exciting and challenging.","t":"她的公司派她去新加坡海外工作兩年，這既令人興奮又具有挑戰性。"},{"w":"overseas","p":"adj.","d":"connected with foreign countries across the sea.","c":"海外的、國外的","s":"The university has strong overseas partnerships with institutions in Europe, Asia, and North America.","t":"這所大學與歐洲、亞洲和北美的機構建立了強大的海外合作關係。"},{"w":"move overseas","p":"phr.","d":"relocating your entire home base to a foreign state.","c":"搬到海外","s":"They decided to move overseas after retirement and chose Portugal for its warm climate and low cost of living.","t":"他們決定退休後搬到海外，因其溫暖的氣候和較低的生活成本而選擇了葡萄牙。"},{"w":"overseas trips","p":"phr.","d":"business travel routes requiring passport checks.","c":"出國旅行、海外行程","s":"Her job requires frequent overseas trips, and she travels to at least six different countries every year for work.","t":"她的工作需要頻繁的出國旅行，每年至少前往六個不同的國家出差。"},{"w":"occur / occurred / occurred","p":"v.","d":"to happen, take place, or exist in a spot.","c":"發生、出現","s":"The earthquake occurred in the early hours of the morning when most residents were still asleep in their homes.","t":"地震在大多數居民還在家中熟睡的清晨發生。"},{"w":"occurrence","p":"n.","d":"an event or instance of something happening cleanly.","c":"發生、發生的事件","s":"Flooding in this low-lying area is not a rare occurrence — it happens almost every time there is heavy rainfall.","t":"這個低窪地區的洪水並非罕見事件——幾乎每次大雨都會發生。"},{"w":"occur to somebody","p":"phr.","d":"a sudden thought or idea entering an agent's mind.","c":"某人想到…","s":"It suddenly occurred to her that she had left the oven on when she was halfway to the train station.","t":"當她走到火車站一半路程時，她突然想到她把烤箱忘記開著了。"},{"w":"it occurs to me that","p":"phr.","d":"suddenly realizing that a peer's talk was serious.","c":"我突然想到…","s":"It occurs to me that we have never actually discussed what happens if the project runs over budget.","t":"我突然想到，我們從來沒有真正討論過如果項目超出預算會怎樣。"},{"w":"painful","p":"adj.","d":"causing physical or emotional suffering and hurt.","c":"痛苦的、疼痛的","s":"The end of a close friendship can be just as painful as a physical injury, especially when there is no clear reason.","t":"親密友誼的結束可能和身體傷害一樣痛苦，尤其是在沒有明確原因的情況下。"},{"w":"pain","p":"n.","d":"a physical feeling of hurt caused by a severe cut.","c":"疼痛、痛苦","s":"She gritted her teeth through the pain and finished the final lap of the race before collapsing at the finish line.","t":"她咬牙忍痛完成了比賽的最後一圈，然後在終點線倒下。"},{"w":"painfully","p":"adv.","d":"in a very distressing or extremely clear manner.","c":"痛苦地、極度地","s":"It was painfully obvious to everyone in the room that the speaker had not prepared adequately for the presentation.","t":"對房間裡的每個人來說，演講者沒有充分準備這次演講是極為明顯的。"},{"w":"painful cut","p":"phr.","d":"a skin wound that hurts badly despite looking minor.","c":"會痛的傷口","s":"She got a painful cut on her hand while cooking and had to stop and wash it under cold running water.","t":"她在做飯時手上受了一道會痛的傷口，不得不停下來在冷水下沖洗。"},{"w":"intensive","p":"adj.","d":"involving a lot of effort or work within brief eras.","c":"密集的、精深的","s":"The intensive language course ran for eight hours a day for six weeks, and students made remarkable progress.","t":"這門密集語言課程每天進行八小時，為期六週，學生們取得了顯著的進步。"},{"w":"intensively","p":"adv.","d":"handling tasks with high focus and rapid speed steps.","c":"密集地","s":"The athletes trained intensively for three months leading up to the international competition to peak at the right time.","t":"運動員在國際比賽前三個月密集訓練，以便在適當的時候達到最佳狀態。"},{"w":"intensive meetings","p":"phr.","d":"back-to-back corporate talks to finalize a trade deal.","c":"密集會議","s":"After three days of intensive meetings, the negotiating teams finally reached an agreement on the trade terms.","t":"經過三天的密集會議後，談判團隊終於就貿易條款達成了協議。"},{"w":"intensive training","p":"phr.","d":"a short, highly packed skill learning master camp.","c":"密集訓練","s":"New recruits underwent four weeks of intensive training before being assigned to their first posts in the field.","t":"新兵在被分配到野外的第一個崗位之前，接受了四週的密集訓練。"},{"w":"event","p":"n.","d":"a highly important social gathering or happening.","c":"事件、重大活動","s":"The charity event raised over fifty thousand dollars in a single evening, exceeding the organisers' expectations.","t":"這場慈善活動在一個晚上籌集了超過五萬元，超出了主辦方的預期。"},{"w":"event took place","p":"phr.","d":"a wedding celebration occurring on a specific date.","c":"活動舉行","s":"The outdoor festival event took place in the city park last weekend and attracted over ten thousand visitors.","t":"上週末，戶外節日在城市公園舉行，吸引了超過一萬名遊客。"},{"w":"major","p":"adj.","d":"highly important, large, or serious in scale.","c":"主要的、重大的","s":"The discovery of clean water sources underground was a major breakthrough for the drought-affected communities in the region.","t":"地下清潔水源的發現對該地區受乾旱影響的社區來說是一個重大突破。"},{"w":"major","p":"v.","d":"to specialize in a specific academic field at college.","c":"主修","s":"She decided to major in environmental science because she wanted to pursue a career in conservation and policy.","t":"她決定主修環境科學，因為她想從事保育和政策方面的職業。"},{"w":"major mistakes","p":"phr.","d":"severe errors inside an essay that catch eyes.","c":"重大錯誤","s":"The engineer reviewed the design plans carefully to identify any major mistakes before construction work began.","t":"工程師在建設工作開始之前仔細審查了設計方案，以識別任何重大錯誤。"},{"w":"major part","p":"phr.","d":"listening skills standing as a baseline core of language.","c":"主要部分","s":"Active listening plays a major part in effective communication, yet it is often the most overlooked skill.","t":"積極傾聽在有效溝通中起著主要部分的作用，然而它往往是最被忽視的技能。"},{"w":"majoring in business","p":"phr.","d":"a student focusing entirely on management science.","c":"主修商業管理","s":"She is majoring in business and hopes to start her own company after graduating from university.","t":"她正在主修商業管理，希望大學畢業後創辦自己的公司。"},{"w":"minor","p":"adj.","d":"small, low, or non-serious; tracking zero risks.","c":"次要的、微小的","s":"The damage to the car was relatively minor, so she decided to pay for the repairs herself rather than claim insurance.","t":"汽車的損壞相對次要，所以她決定自己支付維修費用，而不是申請保險。"},{"w":"examination","p":"n.","d":"an official test checking your knowledge or health.","c":"考試、檢查、審查","s":"Students must register for the final examination at least two weeks in advance or they will not be permitted to sit it.","t":"學生必須至少提前兩週報名參加期末考試，否則將不被允許參加。"},{"w":"examine","p":"v.","d":"to check an object meticulously to find flaws.","c":"檢查、審查、考試","s":"The doctor examined the patient thoroughly and ordered several tests before making a preliminary diagnosis.","t":"醫生徹底檢查了病人，並在做出初步診斷之前下令進行幾項測試。"},{"w":"math examination","p":"phr.","d":"a two hour academic test tracking arithmetic skills.","c":"數學考試","s":"She stayed up until midnight revising for the math examination the next morning and felt well-prepared.","t":"她為第二天早上的數學考試複習到午夜，感到準備充分。"},{"w":"medical examination","p":"phr.","d":"a clinical checkup run by doctors to track health.","c":"醫療檢查、健康檢查","s":"All new employees are required to undergo a full medical examination before their first day at the company.","t":"所有新員工在公司第一天工作之前，都需要接受全面的醫療檢查。"},{"w":"exam","p":"n.","d":"a short casual word for an academic test unit.","c":"考試（examination的簡稱）","s":"She felt much more relaxed after the exam than she expected, because the questions matched exactly what she had studied.","t":"考試後她感到比預期輕鬆得多，因為問題與她所學的內容完全吻合。"},{"w":"frequent","p":"adj.","d":"happening or done very often across brief intervals.","c":"頻繁的、經常的","s":"She made frequent visits to the doctor throughout the winter because she kept catching colds one after another.","t":"整個冬天她頻繁地去看醫生，因為她不斷地連續感冒。"},{"w":"frequent","p":"v.","d":"to visit a specific neighborhood spot regularly.","c":"常去、時常出沒於","s":"He frequents the small café on the corner every morning before work and always orders the same black coffee.","t":"他每天早上上班前常去街角的小咖啡館，總是點同樣的黑咖啡。"},{"w":"frequently","p":"adv.","d":"regularly; tracking a high routine repetition rate.","c":"頻繁地、經常地","s":"She frequently misplaces her keys and has started leaving a spare set with her neighbour as a backup solution.","t":"她頻繁地找不到鑰匙，已經開始把備用鑰匙放在鄰居那裡作為備用解決方案。"},{"w":"frequency","p":"n.","d":"the count of times an event repeats in a duration.","c":"頻率、次數","s":"The frequency of her headaches increased significantly after she started working longer hours at her new job.","t":"她開始在新工作中工作更長時間後，頭痛的頻率顯著增加。"},{"w":"frequent absences","p":"phr.","d":"a pupil repeatedly missing school days recently.","c":"頻繁缺席","s":"The teacher expressed concern about the student's frequent absences and arranged a meeting with her parents.","t":"老師對這位學生的頻繁缺席表示擔憂，並安排了與她父母的會面。"},{"w":"frequent the courts","p":"phr.","d":"boys regularly hanging around local basketball spots.","c":"常去球場","s":"He used to frequent the courts every evening after school and that is where he developed his basketball skills.","t":"他過去每天放學後常去球場，正是在那裡他培養了自己的籃球技能。"},{"w":"exactly","p":"adv.","d":"precisely; tracked with 100% perfect accuracy.","c":"確切地、正是、精準地","s":"The train arrived at exactly nine o'clock, which gave them just enough time to grab a coffee before boarding.","t":"火車確切地在九點到達，給了他們剛好足夠的時間在登車前喝杯咖啡。"},{"w":"exact","p":"adj.","d":"completely correct; matching digits with zero gaps.","c":"確切的、精確的","s":"Could you give me the exact measurements of the room so I can order the correct size of carpet?","t":"你能給我房間的確切尺寸嗎，這樣我就可以訂購正確尺寸的地毯了？"},{"w":"exactly what I need","p":"phr.","d":"a full day of rest matching your core desires perfectly.","c":"正是我所需要的","s":"A quiet weekend at home with good food and a good book is exactly what I need after such a stressful week.","t":"在如此緊張的一週之後，在家度過一個安靜的週末，享用美食和好書，正是我所需要的。"},{"w":"react","p":"v.","d":"to behave in a specific way due to an external action.","c":"做出反應、反應","s":"She was not sure how he would react to the surprise news, but he seemed genuinely pleased when she told him.","t":"她不確定他會如何對這個驚喜消息做出反應，但當她告訴他時，他似乎真的很高興。"},{"w":"reaction","p":"n.","d":"an outward behavior or chemical change from a trigger.","c":"反應","s":"His immediate reaction to winning the award was to burst into tears and thank his parents for their lifelong support.","t":"他對獲獎的即時反應是喜極而泣，並感謝父母一生的支持。"},{"w":"overreact","p":"v.","d":"to show an excess, yelling panic stance over minor news.","c":"反應過度","s":"She admitted that she had overreacted to the situation and apologised for making the problem seem bigger than it was.","t":"她承認自己對這種情況反應過度，並為使問題看起來比實際更大而道歉。"},{"w":"react to loud noise","p":"phr.","d":"a pet dog running away instantly due to a bang sound.","c":"對大聲響做出反應","s":"Babies naturally react to loud noise by startling and crying, as it is an instinctive safety response.","t":"嬰兒自然地對大聲響做出反應，表現為驚跳和哭泣，因為這是一種本能的安全反應。"},{"w":"position","p":"n.","d":"the explicit place where an object sits or stands.","c":"位置、地方","s":"She adjusted the mirror into the correct position so that she could see clearly without turning her head while driving.","t":"她把鏡子調整到正確的位置，這樣她在開車時就可以清楚地看到，而不必轉動頭部。"},{"w":"position","p":"n.","d":"a high rank or specialized role within a company.","c":"職位、地位、處境","s":"She applied for the position of marketing director and was thrilled when she was invited for a second interview.","t":"她申請了市場總監的職位，當她被邀請參加第二次面試時，她感到非常興奮。"},{"w":"position","p":"v.","d":"to build or place an asset down in a specific spot.","c":"安置、使處於某位置","s":"The photographer positioned her subjects carefully in front of the waterfall to capture the best possible shot.","t":"攝影師仔細地將她的拍攝對象安置在瀑布前，以捕捉最好的照片。"},{"w":"comfortable position","p":"phr.","d":"a relaxing posture used while sitting on a couch.","c":"舒服的姿勢/位置","s":"She found a comfortable position on the sofa and settled in to watch the film with a warm blanket over her.","t":"她在沙發上找到了一個舒服的位置，裹著溫暖的毯子，安頓下來觀看電影。"},{"w":"high position","p":"phr.","d":"holding an executive director role inside a firm.","c":"高階職位","s":"After twenty years with the company, she finally achieved a high position in senior management.","t":"在公司工作二十年後，她終於在高層管理中獲得了一個高階職位。"},{"w":"in a position to","p":"phr.","d":"tracking enough cash or power to take a vacation.","c":"有能力…、處於可以…的地位","s":"After saving for two years, he was finally in a position to afford to buy his own apartment in the city.","t":"存了兩年錢後，他終於有能力在城市裡買下自己的公寓。"},{"w":"memory","p":"n.","d":"the brain's internal ability to store and recall data.","c":"記憶力、記憶","s":"She has an excellent memory for names and faces, which makes her very effective at building professional relationships.","t":"她對名字和面孔有出色的記憶力，這使她在建立職業關係方面非常有效。"},{"w":"memorize","p":"v.","d":"to commit words to mind systematically via study.","c":"記住、背誦","s":"She used flashcards to memorize the vocabulary list and tested herself every evening before going to sleep.","t":"她用卡片來背誦詞彙表，每天晚上睡覺前自我測試。"},{"w":"trouble with memory","p":"phr.","d":"an old citizen starting to face minor forgetful gaps.","c":"記憶力有問題","s":"As she got older, she began to experience some trouble with memory and would occasionally forget recent events.","t":"隨著年齡增長，她開始出現一些記憶力方面的問題，偶爾會忘記最近發生的事情。"},{"w":"in memory of","p":"phr.","d":"building a statue to honor a late mayor pioneer.","c":"為了紀念…","s":"A beautiful garden was planted in memory of the teacher who had inspired hundreds of students over her career.","t":"為了紀念這位在職業生涯中激勵了數百名學生的老師，人們種植了一座美麗的花園。"},{"w":"naturally","p":"adv.","d":"as a normal organic result; without artificial help.","c":"自然地、天生功能上","s":"She was naturally gifted at languages and picked up Spanish without formal lessons after just a few months abroad.","t":"她天生擅長語言，在海外僅幾個月後，沒有正式課程就學會了西班牙語。"},{"w":"nature","p":"n.","d":"the physical world of wild plants, trees, and air.","c":"大自然、天性","s":"Spending time in nature has been shown to reduce stress levels and improve both mental and physical wellbeing.","t":"在大自然中度過時光已被證明可以降低壓力水平，並改善心理和身體健康。"},{"w":"natural","p":"adj.","d":"normal in nature; tracking zero chemical additives.","c":"自然的、天生的","s":"She prefers to use natural skincare products made from plant-based ingredients rather than those with synthetic chemicals.","t":"她更喜歡使用由植物成分製成的天然護膚產品，而不是含有合成化學品的產品。"},{"w":"come naturally","p":"phr.","d":"a skill like piano play flowing easily without hard practice.","c":"天生具備、信手拈來","s":"Public speaking does not come naturally for everyone, but with practice it becomes much less intimidating.","t":"公開演講並非人人都能信手拈來，但通過練習，它會變得不那麼令人畏懼。"},{"w":"guide","p":"v.","d":"to show someone the right path or process to follow.","c":"引導、帶路、指導","s":"The experienced teacher guided her students through the complex research process step by step with great patience.","t":"經驗豐富的老師以極大的耐心，一步一步地引導她的學生完成複雜的研究過程。"},{"w":"guide","p":"n.","d":"a professional agent who shows travelers around town.","c":"導遊、指南","s":"They hired a local guide who spoke both English and Mandarin to take them around the historic old city district.","t":"他們聘請了一位會說英語和普通話的當地導遊，帶他們遊覽歷史悠久的老城區。"},{"w":"tour guide","p":"phr.","d":"a professional translator running regional transits.","c":"導遊","s":"The tour guide explained the history of each temple clearly and answered every question the tourists had.","t":"導遊清晰地解釋了每座寺廟的歷史，並回答了遊客的每個問題。"},{"w":"guideline","p":"n.","d":"an official baseline rule detailing operational steps.","c":"指南、準則、方針","s":"The government issued new health guidelines advising people to wear masks in crowded indoor public spaces.","t":"政府發布了新的健康準則，建議人們在擁擠的室內公共場所佩戴口罩。"},{"w":"guided us to","p":"phr.","d":"a local police officer leading travelers to a post office.","c":"引導我們去…","s":"The friendly local farmer guided us to his barn and showed us the newborn lambs sheltering inside.","t":"友善的當地農夫引導我們去他的穀倉，向我們展示了在裡面避寒的新生羔羊。"}]}];
